// Built by tools/maths/build_cards.py from tools/maths/cards/*.json (see tools/maths/GAMES.md). Do not edit by hand.
window.MathsCards = {"10":[{"id":"2015-P1-Q4:(a):1","from":"2015-P1-Q4","q":"Solve the equation −x² + 6x − 4 = 0. Give each solution correct to one decimal place.","right":"x = 0.8 or x = 5.2","wrong":["x = −0.8 or x = −5.2","x = −0.6 or x = 6.6","x = 0.7 or x = 5.2"],"why":"a = −1, b = 6, c = −4: x = (−6 ± √(36 − 16)) / 2(−1) = (−6 ± √20)/(−2), so x = 0.763… ≈ 0.8 or x = 5.236… ≈ 5.2.","hook":"Brackets round every negative: 2a = 2(−1) = −2, not 2.","keys":["(−6 ± √20)/(−2)","0.763… ≈ 0.8"]},{"id":"2015-P1-Q4:(a):2","from":"2015-P1-Q4","q":"You solve −x² + 6x − 4 = 0 with the quadratic formula. What is b² − 4ac, the number under the square root?","right":"20","wrong":["52","−4","32"],"why":"a = −1, b = 6, c = −4: b² − 4ac = 6² − 4(−1)(−4) = 36 − 16 = 20. (−1)(−4) is +4, and the minus in front makes −16.","hook":"Bracket every negative: −4(−1)(−4) = −16.","keys":["36 − 16 = 20"]},{"id":"2015-P1-Q4:(b):1","from":"2015-P1-Q4","q":"Find the co-ordinates of the turning point of the function f(x) = −x² + 6x − 4.","right":"(3, 5)","wrong":["(3, 23)","(1, 1)","(−3, −31)"],"why":"f′(x) = −2x + 6 = 0 gives x = 3. Then f(3) = −9 + 18 − 4 = 5, so the turning point is (3, 5).","hook":"Slope 0 finds the x; the original f(x) finds the y. −3² is −9.","keys":["f′(x) = −2x + 6 = 0","f(3) = −9 + 18 − 4 = 5"]},{"id":"2015-P1-Q4:(b):2","from":"2015-P1-Q4","q":"To find the turning point of f(x) = −x² + 6x − 4, which equation do you solve first?","right":"−2x + 6 = 0","wrong":["−x² + 6x − 4 = 0","−2x + 2 = 0","−x + 6 = 0"],"why":"At a turning point the curve is flat, so its slope f′(x) is 0. f′(x) = −2x + 6 (the −4 goes), so solve −2x + 6 = 0. f(x) = 0 gives the roots instead.","hook":"Turning point: slope = 0, so f′(x) = 0, not f(x) = 0.","keys":["f′(x) = −2x + 6 (the −4 goes)"]},{"id":"2015-P1-Q4:(c):1","from":"2015-P1-Q4","q":"Sketch y = −x² + 6x − 4 using its roots x ≈ 0.8 and x ≈ 5.2 and its turning point (3, 5). What must the sketch show to get full marks?","right":"Roots, top at (3, 5), scale on both axes","wrong":["Roots and top at (3, 5); no scale","Ruled lines joining the three points","A U shape with its bottom at (3, 5)"],"why":"One smooth upside-down U (the −x² flips it) through (0.8, 0) and (5.2, 0) with its top at (3, 5), and both axes numbered: the scale earns marks too.","hook":"Minus x² = a frown ∩. Number both axes before you draw.","keys":["both axes numbered"]},{"id":"2015-P1-Q8:(a):1","from":"2015-P1-Q8","q":"An oil trader's daily profit is p = 96x − 0.03x² euro, where x is the number of barrels traded. Complete the table: what is the profit when x = 1000?","right":"€66 000","wrong":["€95 970","€95 100","€93 000"],"why":"p = 96(1000) − 0.03(1000)² = 96 000 − 0.03 × 1 000 000 = 96 000 − 30 000 = €66 000.","hook":"Square first, then multiply by 0.03.","keys":["0.03 × 1 000 000"]},{"id":"2015-P1-Q8:(b):1","from":"2015-P1-Q8","q":"You plot (500, 40 500), (1000, 66 000), (1500, 76 500), (2000, 72 000) and (2500, 52 500) for p = 96x − 0.03x². How do you draw the graph?","right":"Smooth curve, top between 1500 and 2000","wrong":["Ruled straight lines, point to point","Smooth curve, top at (1500, 76 500)","Plot the five points; don't join them"],"why":"The x² makes the graph a curve: join all five points freehand with one smooth curve. It is still rising at 1500 and turns before 2000.","hook":"x² in the formula → one smooth curve, never ruled lines.","keys":["one smooth curve"]},{"id":"2015-P1-Q8:(c)(i):1","from":"2015-P1-Q8","q":"Graph of the profit p = 96x − 0.03x²: barrels x across, profit p up. How do you use it to estimate the daily profit when 1750 barrels are traded?","right":"Up from 1750 barrels to the curve, across","wrong":["Across from 1750 on the p axis, then down","Halfway between the 1500 and 2000 profits","Read the slope of the curve at x = 1750"],"why":"Profit is on the up axis. Find 1750 on the barrels axis, go up to the curve, then across to read the profit: about €76 000 (the formula gives €76 125).","hook":"Start on the axis you know, finish on the axis you want.","keys":["go up to the curve, then across"]},{"id":"2015-P1-Q8:(c)(ii):1","from":"2015-P1-Q8","q":"Graph of the profit p = 96x − 0.03x² (barrels across, profit up). A line across at €60 000 is drawn. About how many barrels are traded when the daily profit is €60 000?","right":"About 850 or about 2350 barrels","wrong":["About 850 barrels only","About 2350 barrels only","About 625 barrels"],"why":"The line across at €60 000 cuts the hill-shaped curve twice, once going up and once coming down: about 850 and about 2350 barrels. Give both.","hook":"A line across a hill can cut it twice: give both answers.","keys":["cuts the hill-shaped curve twice"]},{"id":"2015-P1-Q8:(d)(i):1","from":"2015-P1-Q8","q":"Daily profit p = 96x − 0.03x² for x barrels. Use calculus to find the number of barrels traded that will earn the maximum daily profit.","right":"1600 barrels","wrong":["3200 barrels","160 barrels","1500 barrels"],"why":"dp/dx = 96 − 0.06x (2 × 0.03 = 0.06). At the maximum the slope is 0: 96 − 0.06x = 0, so x = 96 ÷ 0.06 = 1600 barrels.","hook":"Max or min: set the derivative equal to 0.","keys":["dp/dx = 96 − 0.06x","x = 96 ÷ 0.06 = 1600"]},{"id":"2015-P1-Q8:(d)(i):2","from":"2015-P1-Q8","q":"The daily profit is p = 96x − 0.03x². What is dp/dx?","right":"96 − 0.06x","wrong":["96 − 0.03x","96x − 0.06x","96 − 0.06x²"],"why":"96x becomes 96. For 0.03x², bring the 2 down (2 × 0.03 = 0.06) and take one off the power: 0.06x. So dp/dx = 96 − 0.06x.","hook":"Power down in front, then one off the power.","keys":["2 × 0.03 = 0.06"]},{"id":"2015-P1-Q8:(d)(ii):1","from":"2015-P1-Q8","q":"The profit p = 96x − 0.03x² is greatest when x = 1600 barrels (dp/dx = 96 − 0.06x). Find this maximum daily profit.","right":"€76 800","wrong":["€0","€153 552","€151 296"],"why":"Put x = 1600 into the profit function itself, not into dp/dx: p = 96(1600) − 0.03(1600)² = 153 600 − 76 800 = €76 800.","hook":"Derivative says WHERE the max is; the function says HOW BIG it is.","keys":["not into dp/dx"]},{"id":"2015-P1-Q8:(e):1","from":"2015-P1-Q8","q":"Daily profit p = 96x − 0.03x² for x barrels. The trader will not make a profit if he trades more than k barrels of oil in a day. Calculate k.","right":"3200 barrels","wrong":["1600 barrels","0 barrels","320 barrels"],"why":"No profit means p = 0: 96x − 0.03x² = 0, so x(96 − 0.03x) = 0. x = 0 is trading nothing; the other gives x = 96 ÷ 0.03 = 3200.","hook":"Break-even: set the profit itself to 0, not its derivative.","keys":["x(96 − 0.03x) = 0","96 ÷ 0.03 = 3200"]},{"id":"2016-P1-Q4:(a):1","from":"2016-P1-Q4","q":"f(x) = x³ + x² − 2x + 7. Find the co-ordinates of the point where the graph of f cuts the y-axis.","right":"(0, 7)","wrong":["(7, 0)","(1, 7)","(0, 5)"],"why":"Every point on the y-axis has x = 0: f(0) = 0 + 0 − 2(0) + 7 = 7, so the graph cuts the y-axis at (0, 7).","hook":"y-axis: put x = 0. x-axis: put y = 0.","keys":["f(0) = 0 + 0 − 2(0) + 7 = 7"]},{"id":"2016-P1-Q4:(b):1","from":"2016-P1-Q4","q":"f(x) = x³ + x² − 2x + 7. How do you verify, using algebra, that the point A(1, 7) is on the graph of f?","right":"Work out f(1) and get 7","wrong":["Work out f(7) and get 1","Work out f′(1) and get 7","Work out f(1) and get 0"],"why":"A point is on the graph when its x, put into f, gives its y: f(1) = 1 + 1 − 2 + 7 = 7, the same as the y of A(1, 7).","hook":"On the graph means: put in x, get out y.","keys":["f(1) = 1 + 1 − 2 + 7 = 7"]},{"id":"2016-P1-Q4:(c)(i):1","from":"2016-P1-Q4","q":"f(x) = x³ + x² − 2x + 7. Find f′(x), the derivative of f(x).","right":"f′(x) = 3x² + 2x − 2","wrong":["f′(x) = 3x² + 2x + 5","f′(x) = x² + x − 2","f′(x) = 3x³ + 2x² − 2x"],"why":"Bring each power down and take one off: x³ → 3x², x² → 2x, −2x → −2, and the 7 on its own → 0. So f′(x) = 3x² + 2x − 2.","hook":"Power down in front, one off the power; a number on its own vanishes.","keys":["the 7 on its own → 0"]},{"id":"2016-P1-Q4:(c)(i):2","from":"2016-P1-Q4","q":"f(x) = x³ + x² − 2x + 7 and f′(x) = 3x² + 2x − 2. What is the slope of the tangent to the graph of f when x = 1?","right":"3","wrong":["7","10","0"],"why":"The slope of the tangent is f′(1), not f(1): f′(1) = 3(1)² + 2(1) − 2 = 3 + 2 − 2 = 3.","hook":"Slope → put x into f′(x). Height → put x into f(x).","keys":["f′(1) = 3(1)² + 2(1) − 2 = 3 + 2 − 2 = 3"]},{"id":"2016-P1-Q4:(c)(ii):1","from":"2016-P1-Q4","q":"The tangent to the graph of f(x) = x³ + x² − 2x + 7 at the point A(1, 7) has slope 3. Find the equation of the tangent.","right":"y = 3x + 4","wrong":["y = 3x + 7","y = 3x − 20","y = 3x + 10"],"why":"Use y − y₁ = m(x − x₁) with (1, 7) and m = 3: y − 7 = 3(x − 1), so y − 7 = 3x − 3 and y = 3x + 4.","hook":"A line needs a point and a slope: y − y₁ = m(x − x₁).","keys":["y − 7 = 3(x − 1)"]},{"id":"2016-P1-Q8:(a):1","from":"2016-P1-Q8","q":"Kieran has 21 m of fencing to enclose a rectangular garden of length x m and width y m. Which equation for the perimeter leads to y = 10.5 − x?","right":"2x + 2y = 21","wrong":["x + y = 21","xy = 21","2x + y = 21"],"why":"The perimeter is two lengths and two widths, all 21 m of fencing: 2x + 2y = 21. Divide by 2: x + y = 10.5, so y = 10.5 − x.","hook":"Perimeter = all the way round: 2 lengths + 2 widths.","keys":["2x + 2y = 21"]},{"id":"2016-P1-Q8:(b)(i):1","from":"2016-P1-Q8","q":"Kieran's garden has length x m and width y = 10.5 − x m. Complete the table: what are y and the area A when x = 7?","right":"y = 3.5 m, A = 24.5 m²","wrong":["y = 3.5 m, A = 10.5 m²","y = 3.5 m, A = 21 m²","y = 17.5 m, A = 122.5 m²"],"why":"y = 10.5 − 7 = 3.5 m. The area of a rectangle is length × width, so A = 7 × 3.5 = 24.5 m².","hook":"Area multiplies length × width; perimeter adds all four sides.","keys":["A = 7 × 3.5 = 24.5 m²"]},{"id":"2016-P1-Q8:(b)(ii):1","from":"2016-P1-Q8","q":"One column of Kieran's table reads x = 3 m, y = 7.5 m, A = 22.5 m². You plot the graph of A (up) against x (across). Which point do you plot for this column?","right":"(3, 22.5)","wrong":["(3, 7.5)","(22.5, 3)","(7.5, 22.5)"],"why":"Points are (across, up). The graph is A against x: x = 3 across, A = 22.5 up, so plot (3, 22.5). The width y is not plotted.","hook":"(x, y) means across first, then up.","keys":["plot (3, 22.5)"]},{"id":"2016-P1-Q8:(c):1","from":"2016-P1-Q8","q":"On your graph of the garden's area A (up) against its length x (across), how do you estimate the maximum area and the length that gives it?","right":"Top of the curve: across to A, down to x","wrong":["Top of the curve: down to A, across to x","Where the curve meets the x-axis","The right-hand end of the curve, x = 10"],"why":"The maximum area is the highest point of the curve. Read across to the A axis (about 27.5 m²) and down to the x axis (about 5.25 m).","hook":"Max = the top of the hill. Across for its height, down for its x.","keys":["highest point of the curve"]},{"id":"2016-P1-Q8:(d)(i):1","from":"2016-P1-Q8","q":"Kieran's rectangular garden has length x m and width y = 10.5 − x m. Write its area A in terms of x only.","right":"A = 10.5x − x²","wrong":["A = 10.5 − x²","A = 10.5x − 2x","A = 21x − 2x²"],"why":"Area = length × width = x × y. Replace y with 10.5 − x and multiply out: A = x(10.5 − x) = 10.5x − x².","hook":"Max/min problems: first get the thing you want in ONE letter.","keys":["A = x(10.5 − x) = 10.5x − x²"]},{"id":"2016-P1-Q8:(d)(ii):1","from":"2016-P1-Q8","q":"The area of Kieran's garden is A = 10.5x − x². Find dA/dx.","right":"10.5 − 2x","wrong":["10.5 − x","−2x","10.5x − 2x"],"why":"10.5x differentiates to 10.5 (the x goes, the number stays). For x², bring the 2 down and take one off: 2x. So dA/dx = 10.5 − 2x.","hook":"ax → a; x² → 2x; a number on its own → 0.","keys":["10.5x differentiates to 10.5"]},{"id":"2016-P1-Q8:(d)(iii):1","from":"2016-P1-Q8","q":"The garden's area is A = 10.5x − x² and dA/dx = 10.5 − 2x. Find the value of x which will give the maximum area.","right":"x = 5.25 m","wrong":["x = 10.5 m","x = 21 m","x = 5 m"],"why":"At the maximum the slope is 0: 10.5 − 2x = 0, so 2x = 10.5 and x = 10.5 ÷ 2 = 5.25 m.","hook":"Biggest area → slope 0 → solve dA/dx = 0.","keys":["10.5 − 2x = 0","x = 10.5 ÷ 2 = 5.25 m"]},{"id":"2016-P1-Q8:(d)(iii):2","from":"2016-P1-Q8","q":"The area of Kieran's garden is A = 10.5x − x². Why is dA/dx = 0 at the length that gives the maximum area?","right":"The curve is flat at its top: slope 0","wrong":["The area is 0 at the top","The length x is 0 at the top","dA/dx is at its largest at the top"],"why":"dA/dx is the slope of the area graph. Going up to the top the slope is positive, after it negative: at the top it is 0, so the curve is flat there.","hook":"Top of a hill: flat for a moment, so the slope is 0.","keys":["at the top it is 0"]},{"id":"2016-P1-Q8:(d)(iv):1","from":"2016-P1-Q8","q":"Kieran's garden: area A = 10.5x − x², dA/dx = 10.5 − 2x, and the maximum is at length x = 5.25 m. Find this maximum area.","right":"27.56 m²","wrong":["0 m²","10.5 m²","55.13 m²"],"why":"Put x = 5.25 into A, not into dA/dx. The width is 10.5 − 5.25 = 5.25 m too, so A = 5.25 × 5.25 = 27.5625 ≈ 27.56 m².","hook":"The derivative finds where; the area formula finds how much.","keys":["A = 5.25 × 5.25 = 27.5625"]},{"id":"2017-P1-Q3:(a):1","from":"2017-P1-Q3","q":"Find the two values of x for which 3x² − 6x − 8 = 0. Give each answer correct to 1 decimal place.","right":"x = 2.9 or x = −0.9","wrong":["x = 0.9 or x = −2.9","x = 2.3 or x = −0.3","x = 8.7 or x = −2.7"],"why":"a = 3, b = −6, c = −8: x = (6 ± √(36 + 96))/6 = (6 ± √132)/6, so x = 2.914… ≈ 2.9 or x = −0.948… ≈ −0.9.","hook":"−b of a negative b is positive; (−6)² = +36; 2a = 6.","keys":["(6 ± √132)/6"]},{"id":"2017-P1-Q3:(a):2","from":"2017-P1-Q3","q":"You use the quadratic formula to solve 3x² − 6x − 8 = 0. What are a, b and c?","right":"a = 3, b = −6, c = −8","wrong":["a = 3, b = 6, c = −8","a = 3, b = 6, c = 8","a = 3, b = −6, c = 8"],"why":"Match 3x² − 6x − 8 = 0 to ax² + bx + c = 0 and keep each sign with its number: a = 3, b = −6, c = −8.","hook":"The sign in front belongs to the number: −6x gives b = −6.","keys":["keep each sign with its number"]},{"id":"2017-P1-Q3:(b):1","from":"2017-P1-Q3","q":"Find the co-ordinates of the minimum point of the function f(x) = 3x² − 6x − 8.","right":"(1, −11)","wrong":["(2, −8)","(−1, 1)","(1, 0)"],"why":"f′(x) = 6x − 6. At the minimum 6x − 6 = 0, so x = 1. Then y = f(1) = 3 − 6 − 8 = −11: the minimum point is (1, −11).","hook":"Co-ordinates = x AND y. The y comes from f(x), not f′(x).","keys":["f′(x) = 6x − 6","f(1) = 3 − 6 − 8 = −11"]},{"id":"2017-P1-Q3:(b):2","from":"2017-P1-Q3","q":"f(x) = 3x² − 6x − 8. Solving f′(x) = 6x − 6 = 0 gives x = 1 at the minimum point. How do you get its y co-ordinate?","right":"Put x = 1 into f(x)","wrong":["Put x = 1 into f′(x)","Solve 3x² − 6x − 8 = 0","No need: x = 1 is the answer"],"why":"The point is on the curve, so its height comes from f itself: f(1) = 3(1)² − 6(1) − 8 = −11. f′(1) = 0 is only the slope there.","hook":"f′(x) = 0 finds the x; f(x) finds the y. Give both.","keys":["f(1) = 3(1)² − 6(1) − 8 = −11"]},{"id":"2017-P1-Q8:(a):1","from":"2017-P1-Q8","q":"A company's weekly profit is P(x) = 275x − x² − 2000 euro, where x is the km of cable sold. How much money does it lose if it sells no cable?","right":"€2000","wrong":["€0","€275","€1725"],"why":"Selling no cable means x = 0, and 275 × 0 = 0: P(0) = 0 − 0 − 2000 = −2000. A profit of −€2000 is a loss of €2000.","hook":"Nothing sold → put x = 0. A negative profit is a loss.","keys":["P(0) = 0 − 0 − 2000 = −2000"]},{"id":"2017-P1-Q8:(b):1","from":"2017-P1-Q8","q":"Profit P(x) = 275x − x² − 2000 euro for x km of cable, and at most 200 km can be sold. One week the profit was €8350. How many km were sold?","right":"45 km","wrong":["230 km","45 km or 230 km","34.8 km"],"why":"275x − x² − 2000 = 8350 gives x² − 275x + 10 350 = 0, so (x − 45)(x − 230) = 0. At most 200 km can be sold, so x = 45 km.","hook":"Check every answer against the limits: here x ≤ 200.","keys":["(x − 45)(x − 230) = 0","x = 45 km"]},{"id":"2017-P1-Q8:(b):2","from":"2017-P1-Q8","q":"Profit P(x) = 275x − x² − 2000 euro for x km of cable. Which equation finds the km sold in a week when the profit was €8350?","right":"275x − x² − 2000 = 8350","wrong":["275 − 2x = 8350","275x − x² − 2000 = 0","275x − x² = 8350"],"why":"The profit itself is €8350, so set P(x) = 8350 and keep the −2000. The derivative 275 − 2x is the rate the profit changes, not the profit.","hook":"Amount given → set P(x) to it. Rate given → set P′(x) to it.","keys":["set P(x) = 8350"]},{"id":"2017-P1-Q8:(c)(i):1","from":"2017-P1-Q8","q":"Profit P(x) = 275x − x² − 2000 euro for x km of cable. Complete the table: what is the profit when x = 50?","right":"€9250","wrong":["€14 250","€11 650","€11 250"],"why":"P(50) = 275(50) − 50² − 2000 = 13 750 − 2500 − 2000 = €9250.","hook":"Square first, keep every minus, and don't drop the −2000.","keys":["13 750 − 2500 − 2000 = €9250"]},{"id":"2017-P1-Q8:(c)(ii):1","from":"2017-P1-Q8","q":"Profit P(x) = 275x − x² − 2000. You plot (50, 9250), (60, 10 900), (70, 12 350), (80, 13 600), (90, 14 650), (100, 15 500). What do you draw?","right":"Smooth curve, rising more and more slowly","wrong":["Smooth curve, rising faster and faster","One straight line through the points","Ruled lines from point to point"],"why":"The profit goes up by 1650, 1450, 1250, 1050, 850: still rising, but by less each time. Join the points with one smooth curve that bends over.","hook":"Look at the gaps: shrinking gaps = a curve that flattens.","keys":["1650, 1450, 1250, 1050, 850"]},{"id":"2017-P1-Q8:(c)(iii):1","from":"2017-P1-Q8","q":"Graph of the profit P (up, in €) against km of cable sold x (across). How do you find the sales that give a profit between €10 000 and €14 000?","right":"Across from €10 000 and €14 000, then down","wrong":["Up from 10 000 and 14 000 on the km axis","Put x = 10 000 and x = 14 000 into P(x)","Solve P′(x) = 10 000 and P′(x) = 14 000"],"why":"Profit is on the up axis. Draw lines across at €10 000 and €14 000 to the curve, then down: about 55 km and 83 km. Sales between them work.","hook":"Know the profit? Start on the profit axis, go across, then down.","keys":["about 55 km and 83 km"]},{"id":"2017-P1-Q8:(d):1","from":"2017-P1-Q8","q":"Profit P(x) = 275x − x² − 2000 euro for x km of cable. Use calculus to find the km sold when the profit is increasing at a rate of €105 per km.","right":"85 km","wrong":["137.5 km","170 km","190 km"],"why":"The rate the profit increases is P′(x) = 275 − 2x. Set it equal to 105: 275 − 2x = 105, so 2x = 170 and x = 85 km.","hook":"Rate of change = derivative. Set P′(x) equal to the rate given.","keys":["275 − 2x = 105","x = 85 km"]},{"id":"2017-P1-Q8:(d):2","from":"2017-P1-Q8","q":"Profit P(x) = 275x − x² − 2000. The profit is increasing at a rate of €105 per km. Which equation do you solve?","right":"275 − 2x = 105","wrong":["275x − x² − 2000 = 105","275 − 2x = 0","275 − 2x − 2000 = 105"],"why":"\"Increasing at a rate of\" means the derivative: P′(x) = 275 − 2x (the −2000 goes to 0). Set it equal to 105, not to 0.","hook":"Rate → P′(x). Amount → P(x). Max or min → P′(x) = 0.","keys":["P′(x) = 275 − 2x"]},{"id":"2018-P1-Q5:(a):1","from":"2018-P1-Q5","q":"A quadratic graph cuts the y-axis at height 6 (point A) and the x-axis at −2 (point B) and at 3 (point C). Write down the co-ordinates of A, B and C.","right":"A(0, 6), B(−2, 0), C(3, 0)","wrong":["A(6, 0), B(0, −2), C(0, 3)","A(6, 0), B(−2, 0), C(3, 0)","A(0, 6), B(0, −2), C(0, 3)"],"why":"On the y-axis x = 0, so A = (0, 6). On the x-axis y = 0, so B = (−2, 0) and C = (3, 0). Co-ordinates are (across, up).","hook":"(x, y): across first, then up. On the x-axis, y = 0.","keys":["A = (0, 6)","B = (−2, 0) and C = (3, 0)"]},{"id":"2018-P1-Q5:(b):1","from":"2018-P1-Q5","q":"A quadratic graph is an upside-down U that cuts the x-axis at x = −2 and x = 3, and the y-axis at 6. Which formula fits it?","right":"f(x) = −(x + 2)(x − 3)","wrong":["f(x) = (x + 2)(x − 3)","f(x) = −(x − 2)(x + 3)","f(x) = (x − 2)(x + 3)"],"why":"Each root gives a factor with its sign changed: x = −2 → (x + 2), x = 3 → (x − 3). The ∩ needs a minus in front: −(x + 2)(x − 3) = −x² + x + 6.","hook":"Root −2 → factor (x + 2): change the sign.","keys":["−(x + 2)(x − 3) = −x² + x + 6"]},{"id":"2018-P1-Q5:(b):2","from":"2018-P1-Q5","q":"The quadratic with roots −2 and 3 and an upside-down U shape is f(x) = −(x + 2)(x − 3). Multiply it out.","right":"−x² + x + 6","wrong":["−x² − x − 6","x² − x − 6","−x² + 5x + 6"],"why":"(x + 2)(x − 3) = x² − 3x + 2x − 6 = x² − x − 6. The minus in front changes every sign: −x² + x + 6.","hook":"Multiply out the brackets first, then flip every sign.","keys":["x² − 3x + 2x − 6 = x² − x − 6"]},{"id":"2018-P1-Q5:(c):1","from":"2018-P1-Q5","q":"f(x) = −x² + x + 6. Use calculus to find the maximum point of f(x).","right":"(0.5, 6.25)","wrong":["(−0.5, 5.25)","(0.5, 6.75)","(1, 6)"],"why":"f′(x) = −2x + 1 = 0 gives x = 0.5. Then f(0.5) = −0.25 + 0.5 + 6 = 6.25, so the maximum point is (0.5, 6.25).","hook":"−(0.5)² = −0.25: square first, then put the minus in front.","keys":["f′(x) = −2x + 1 = 0","f(0.5) = −0.25 + 0.5 + 6 = 6.25"]},{"id":"2018-P1-Q5:(c):2","from":"2018-P1-Q5","q":"f(x) = −x² + x + 6. What is f′(x)?","right":"−2x + 1","wrong":["−2x + 7","2x + 1","−x + 1"],"why":"−x² → −2x (bring the 2 down and keep the minus), x → 1, and the 6 on its own → 0. So f′(x) = −2x + 1.","hook":"Keep the sign in front when you bring the power down.","keys":["the 6 on its own → 0"]},{"id":"2018-P1-Q8:(a):1","from":"2018-P1-Q8","q":"The amount of a drug in the bloodstream t hours after it is taken is C(t) = −t³ + 4.5t² + 54t units. What is the amount after 4 hours?","right":"224 units","wrong":["276 units","188 units","476 units"],"why":"C(4) = −(4)³ + 4.5(4)² + 54(4) = −64 + 4.5 × 16 + 216 = −64 + 72 + 216 = 224 units.","hook":"Powers first: 4³ = 64 and 4² = 16, then multiply.","keys":["−64 + 4.5 × 16 + 216"]},{"id":"2018-P1-Q8:(b):1","from":"2018-P1-Q8","q":"Drug amount C(t) = −t³ + 4.5t² + 54t units after t hours. Complete the table: what is C(3)?","right":"175.5 units","wrong":["229.5 units","193.5 units","162 units"],"why":"C(3) = −(3)³ + 4.5(3)² + 54(3) = −27 + 4.5 × 9 + 162 = −27 + 40.5 + 162 = 175.5 units.","hook":"Bracket the number: −(3)³ = −27, and 3² = 9 before × 4.5.","keys":["−27 + 40.5 + 162 = 175.5"]},{"id":"2018-P1-Q8:(d)(i):1","from":"2018-P1-Q8","q":"Graph of the drug amount C(t): time t in hours across, amount in units up. How do you use it to estimate the amount after 3½ hours?","right":"Up from 3.5 on the time axis, then across","wrong":["Up from 3.3 on the time axis, then across","Across from 3.5 on the amount axis, down","Read the slope of the curve at t = 3.5"],"why":"3½ hours is 3.5 (not 3.3: half an hour is 0.5). Go up from 3.5 on the time axis to the curve, then across: about 200 units.","hook":"Time is across: start there. 3½ h = 3.5, not 3.3.","keys":["3½ hours is 3.5"]},{"id":"2018-P1-Q8:(d)(ii):1","from":"2018-P1-Q8","q":"Graph of the drug amount C(t) against time t (hours). Going across from 100 units to the curve and down, you reach 1.75 on the time axis. How long after taking the drug is that?","right":"1 hour 45 minutes","wrong":["1 hour 75 minutes","1 hour 7.5 minutes","1 hour 15 minutes"],"why":"1.75 hours is 1 hour and 0.75 of an hour: 0.75 × 60 = 45 minutes. So about 1 hour 45 minutes.","hook":"Decimal hours → minutes: multiply the decimal part by 60.","keys":["0.75 × 60 = 45 minutes"]},{"id":"2018-P1-Q8:(e)(i):1","from":"2018-P1-Q8","q":"Drug amount C(t) = −t³ + 4.5t² + 54t. Find, in terms of t, the rate at which the drug amount is changing after t hours.","right":"C′(t) = −3t² + 9t + 54","wrong":["C′(t) = −3t² + 4.5t + 54","C′(t) = 3t² + 9t + 54","C′(t) = −3t³ + 9t² + 54t"],"why":"Rate of change = derivative. Bring each power down and take one off: −t³ → −3t², 4.5t² → 9t (2 × 4.5), 54t → 54.","hook":"\"Rate at which it is changing\" = differentiate.","keys":["4.5t² → 9t (2 × 4.5)"]},{"id":"2018-P1-Q8:(e)(i):2","from":"2018-P1-Q8","q":"Drug amount C(t) = −t³ + 4.5t² + 54t units after t hours. \"The rate at which the drug amount is changing after t hours\" means which of these?","right":"C′(t), the derivative of C(t)","wrong":["C(t), the amount itself","C(t) ÷ t, the amount per hour","C″(t), the second derivative"],"why":"A rate of change is the derivative: how fast C is going up or down at that moment. C(t) is the amount, and C(t) ÷ t is only an average.","hook":"\"Rate\", \"how fast\", \"increasing at\" → the derivative.","keys":["A rate of change is the derivative"]},{"id":"2018-P1-Q8:(e)(ii):1","from":"2018-P1-Q8","q":"The drug amount changes at the rate C′(t) = −3t² + 9t + 54 units per hour. Find the rate at which the drug amount is changing after 4 hours.","right":"42 units per hour","wrong":["224 units per hour","138 units per hour","−54 units per hour"],"why":"Put t = 4 into the derivative, not into C(t): C′(4) = −3(16) + 9(4) + 54 = −48 + 36 + 54 = 42 units per hour.","hook":"Rate → C′(t). Amount → C(t).","keys":["C′(4) = −3(16) + 9(4) + 54"]},{"id":"2018-P1-Q8:(e)(iii):1","from":"2018-P1-Q8","q":"C(t) = −t³ + 4.5t² + 54t for 0 ≤ t ≤ 9, and C′(t) = −3t² + 9t + 54. Find the maximum amount of the drug in the bloodstream over the first 9 hours.","right":"270 units","wrong":["175.5 units","121.5 units","0 units"],"why":"Set C′(t) = 0 and divide by −3: t² − 3t − 18 = 0, so (t − 6)(t + 3) = 0 and t = 6 (not −3). C(6) = −216 + 162 + 324 = 270 units.","hook":"C′(t) = 0 finds WHEN; C(t) finds HOW MUCH.","keys":["(t − 6)(t + 3) = 0","C(6) = −216 + 162 + 324 = 270"]},{"id":"2018-P1-Q8:(e)(iii):2","from":"2018-P1-Q8","q":"At the maximum drug amount C′(t) = −3t² + 9t + 54 = 0. Dividing by −3 gives t² − 3t − 18 = 0. Which time do you use?","right":"t = 6 hours","wrong":["t = −3 hours","t = 3 hours","t = 6 and t = −3 hours"],"why":"(t − 6)(t + 3) = 0 gives t = 6 or t = −3. The time after taking the drug can't be negative, so t = 6 hours.","hook":"Check roots against the story: time can't be negative.","keys":["(t − 6)(t + 3) = 0"]},{"id":"2018-P1-Q8:(e)(iv):1","from":"2018-P1-Q8","q":"The drug amount changes at the rate C′(t) = −3t² + 9t + 54 units per hour. Which shows the amount is decreasing 7 hours after the drug was taken?","right":"C′(7) = −30 < 0, so it is decreasing","wrong":["C′(7) = 264 > 0, so it is increasing","C(7) = 255.5 > 0, so it is decreasing","C′(7) = −30, so 30 units are left"],"why":"C′(7) = −3(49) + 9(7) + 54 = −147 + 63 + 54 = −30. A negative rate means the amount is going down, by 30 units per hour.","hook":"Sign of the derivative: + going up, − going down.","keys":["−147 + 63 + 54 = −30"]},{"id":"2019-P1-Q3:(a)(i):1","from":"2019-P1-Q3","q":"f(x) = −x³ + 4x² + x − 2. Complete the table: what is f(−1)?","right":"2","wrong":["0","−6","4"],"why":"f(−1) = −(−1)³ + 4(−1)² + (−1) − 2 = −(−1) + 4(1) − 1 − 2 = 1 + 4 − 1 − 2 = 2.","hook":"Bracket the negative: (−1)³ = −1, so −(−1)³ = +1.","keys":["1 + 4 − 1 − 2 = 2"]},{"id":"2019-P1-Q3:(a)(ii):1","from":"2019-P1-Q3","q":"You have drawn the graph of f(x) = −x³ + 4x² + x − 2 for −1 ≤ x ≤ 4. Where on the graph do you read the two roots of f(x)?","right":"Where the curve cuts the x-axis","wrong":["Where the curve cuts the y-axis","At the bottom and top of the curve","At the two ends, x = −1 and x = 4"],"why":"A root is where f(x) = 0, a height of 0: where the curve cuts the x-axis. It crosses twice in this domain, at about x = −0.7 and x = 0.7.","hook":"Roots = where the curve cuts the x-axis (height 0).","keys":["about x = −0.7 and x = 0.7"]},{"id":"2019-P1-Q3:(b):1","from":"2019-P1-Q3","q":"f(x) = −x³ + 4x² + x − 2. Find the value of x for which f″(x) = 0, where f″(x) is the second derivative of f(x).","right":"x = 4/3","wrong":["x = −4/3","x = 2/3","x = 3/4"],"why":"f′(x) = −3x² + 8x + 1. Differentiate again: f″(x) = −6x + 8. Then −6x + 8 = 0 gives 6x = 8, so x = 8/6 = 4/3.","hook":"f″: differentiate, then differentiate again.","keys":["f″(x) = −6x + 8","x = 8/6 = 4/3"]},{"id":"2019-P1-Q3:(b):2","from":"2019-P1-Q3","q":"f(x) = −x³ + 4x² + x − 2. What is f″(x), the second derivative?","right":"−6x + 8","wrong":["−3x² + 8x + 1","−6x + 9","6x + 8"],"why":"First f′(x) = −3x² + 8x + 1 (the −2 goes). Differentiate again: −3x² → −6x, 8x → 8, 1 → 0. So f″(x) = −6x + 8.","hook":"Second derivative = differentiate twice. Numbers on their own vanish.","keys":["f′(x) = −3x² + 8x + 1"]},{"id":"2019-P1-Q7:(a):1","from":"2019-P1-Q7","q":"A ball is hit straight up. Its height is f(t) = −4t² + 16t + 1 metres, t seconds after it is hit. At what height was the ball when it was hit?","right":"1 m","wrong":["16 m","13 m","17 m"],"why":"When the ball is hit, no time has passed: t = 0. f(0) = −4(0)² + 16(0) + 1 = 1 m.","hook":"At the start, t = 0.","keys":["f(0) = −4(0)² + 16(0) + 1 = 1 m"]},{"id":"2019-P1-Q7:(b)(i):1","from":"2019-P1-Q7","q":"Ball height f(t) = −4t² + 16t + 1 metres after t seconds. Complete the table: what is the height at t = 0.5?","right":"8 m","wrong":["13 m","5 m","10 m"],"why":"f(0.5) = −4(0.5)² + 16(0.5) + 1 = −4 × 0.25 + 8 + 1 = −1 + 8 + 1 = 8 m.","hook":"Square first: 0.5² = 0.25, not 1. Then × −4.","keys":["−4 × 0.25 + 8 + 1"]},{"id":"2019-P1-Q7:(c)(i):1","from":"2019-P1-Q7","q":"Ball height f(t) = −4t² + 16t + 1 m. Your table stops at t = 4 s, when the ball is still 1 m up. How do you use the graph to find how long it was in the air?","right":"Extend the curve to the time axis, read t","wrong":["Read the last time in the table, t = 4","Read the time at the top of the curve","Read where the curve meets the height axis"],"why":"The ball is in the air until its height is 0, so carry the curve down to the time axis: it lands just after t = 4, at about 4.1 s.","hook":"Landed = height 0 = on the time axis.","keys":["about 4.1 s"]},{"id":"2019-P1-Q7:(c)(ii):1","from":"2019-P1-Q7","q":"Ball height f(t) = −4t² + 16t + 1 m. A line across at 10 m cuts the graph at about t = 0.6 s and t = 3.4 s. For how long was the ball 10 m or more above the ground?","right":"about 2.8 s","wrong":["about 3.4 s","about 4 s","about 1.4 s"],"why":"The ball passes 10 m going up (t ≈ 0.6 s) and coming down (t ≈ 3.4 s). Length of time = later − earlier = 3.4 − 0.6 = 2.8 s.","hook":"\"How long\" = later time minus earlier time.","keys":["3.4 − 0.6 = 2.8 s"]},{"id":"2019-P1-Q7:(d)(i):1","from":"2019-P1-Q7","q":"Ball height f(t) = −4t² + 16t + 1. Find f′(t), the derivative of f(t).","right":"f′(t) = −8t + 16","wrong":["f′(t) = −8t + 17","f′(t) = 8t + 16","f′(t) = −4t + 16"],"why":"−4t² → 2 × (−4)t = −8t, 16t → 16, and the 1 on its own → 0. So f′(t) = −8t + 16.","hook":"Bring the power down and multiply: 2 × (−4) = −8.","keys":["2 × (−4)t = −8t"]},{"id":"2019-P1-Q7:(d)(ii):1","from":"2019-P1-Q7","q":"Ball height f(t) = −4t² + 16t + 1 m, and f′(t) = −8t + 16. Find the speed of the ball when it had been in the air for 4 seconds.","right":"16 m/s","wrong":["1 m/s","48 m/s","0 m/s"],"why":"Speed comes from the derivative: f′(4) = −8(4) + 16 = −32 + 16 = −16. The minus only says the ball is falling, so the speed is 16 m/s.","hook":"Height → f(t). Speed → f′(t).","keys":["f′(4) = −8(4) + 16 = −32 + 16 = −16"]},{"id":"2019-P1-Q7:(d)(ii):2","from":"2019-P1-Q7","q":"For the ball, f′(4) = −16, where f′(t) is the rate its height changes in m/s. What does the minus sign tell you?","right":"The ball is coming down","wrong":["The ball is 16 m below the pitch","The ball is slowing down","The ball is going up at 16 m/s"],"why":"f′(t) is the rate the height changes. Negative means the height is going down: the ball is falling at 16 m/s. It says nothing about where the ball is.","hook":"Sign of the derivative: + rising, − falling.","keys":["the ball is falling at 16 m/s"]},{"id":"2019-P1-Q7:(d)(iii):1","from":"2019-P1-Q7","q":"Ball height f(t) = −4t² + 16t + 1 m, and f′(t) = −8t + 16. Find the time t when the ball was descending at a speed of 8 m/s.","right":"t = 3 s","wrong":["t = 1 s","t = 3.5 s","t = 6 s"],"why":"Descending means the height is falling, so the rate is negative: f′(t) = −8. −8t + 16 = −8 gives 8t = 24, so t = 3 s. (+8 gives t = 1, still rising.)","hook":"Going down → negative derivative.","keys":["f′(t) = −8","t = 3 s"]},{"id":"2020-P1-Q6:(a)(i):1","from":"2020-P1-Q6","q":"Differentiate f(x) = 4x³ − 3x² + x − 7 with respect to x.","right":"12x² − 6x + 1","wrong":["12x² − 6x − 6","12x³ − 6x² + x","4x² − 3x + 1"],"why":"Bring each power down and take one off: 4x³ → 12x², −3x² → −6x, x → 1, and the number −7 → 0.","hook":"Power down in front, then one off the power. A number on its own becomes 0.","keys":["−7 → 0"]},{"id":"2020-P1-Q6:(a)(i):2","from":"2020-P1-Q6","q":"When you differentiate a term axⁿ (like 4x³), what does it become?","right":"naxⁿ⁻¹","wrong":["axⁿ⁻¹","naxⁿ","(n − 1)axⁿ⁻¹"],"why":"Multiply by the power, then take one off the power: 4x³ → 3 × 4x² = 12x².","hook":"Down, then one off: the power comes down in front, then drops by one.","keys":["Multiply by the power"]},{"id":"2020-P1-Q6:(a)(ii):1","from":"2020-P1-Q6","q":"f(x) = 4x³ − 3x² + x − 7, so f′(x) = 12x² − 6x + 1. Find the slope of the tangent to the graph of f at the point (1, −5).","right":"7","wrong":["−5","0","2"],"why":"The slope of the tangent is f′(1) = 12(1)² − 6(1) + 1 = 7. The −5 is only the height of the point.","hook":"Slope of the tangent = f′ at that x. f gives the height, f′ gives the slope.","keys":["f′(1) = 12(1)² − 6(1) + 1 = 7"]},{"id":"2020-P1-Q6:(a)(iii):1","from":"2020-P1-Q6","q":"The tangent to the graph of f at the point (1, −5) has slope 7. Find the equation of the tangent.","right":"y = 7x − 12","wrong":["y = 7x + 12","y = 7x − 2","y = 7x − 5"],"why":"y − y₁ = m(x − x₁): y − (−5) = 7(x − 1), so y + 5 = 7x − 7 and y = 7x − 12 (or 7x − y − 12 = 0).","hook":"Minus a minus is a plus: y − (−5) is y + 5.","keys":["y − (−5) = 7(x − 1)"]},{"id":"2020-P1-Q6:(a)(iii):2","from":"2020-P1-Q6","q":"You know one point (x₁, y₁) on a line and its slope m. Which formula gives the equation of the line?","right":"y − y₁ = m(x − x₁)","wrong":["m = (y₂ − y₁) ÷ (x₂ − x₁)","y − x₁ = m(x − y₁)","y = m(x − x₁)"],"why":"y − y₁ = m(x − x₁) builds a line from one point and its slope. m = (y₂ − y₁) ÷ (x₂ − x₁) only finds a slope from two points.","hook":"Point + slope → y − y₁ = m(x − x₁). It is in the Formulae and Tables booklet.","keys":["one point and its slope"]},{"id":"2020-P1-Q6:(b):1","from":"2020-P1-Q6","q":"g(x) = 2x² + px + q, where p and q are whole numbers. What is g′(x)?","right":"4x + p","wrong":["4x + p + q","2x + p","4x"],"why":"p and q are just numbers: 2x² → 4x, px → p (like 5x → 5) and q → 0.","hook":"Letters like p and q are numbers in disguise: px → p, q → 0.","keys":["px → p"]},{"id":"2020-P1-Q6:(b):2","from":"2020-P1-Q6","q":"g(x) = 2x² + px + q. Given that g(2) = 6 and g′(3) = 9, find the value of p and the value of q.","right":"p = −3, q = 4","wrong":["p = −7, q = 12","p = 1, q = −4","p = 3, q = −8"],"why":"g′(x) = 4x + p, so g′(3) = 12 + p = 9 gives p = −3. Then g(2) = 8 + 2(−3) + q = 6 gives q = 4.","hook":"Start with the clue that has only one unknown: g′(x) has no q in it.","keys":["12 + p = 9"]},{"id":"2020-P1-Q8:(a):1","from":"2020-P1-Q8","q":"A swimmer dives off a block. Her level above the water is h(x) = (1/60)x² − (1/4)x + 3/5 m when she is x m out from the block. Find the height of the block above the water.","right":"0.6 m","wrong":["0.37 m","3 m","0.34 m"],"why":"On the block she hasn't moved forward yet, so x = 0: h(0) = 0 − 0 + 3/5 = 3/5 m = 0.6 m.","hook":"Where it starts: put x = 0. Every x term vanishes, leaving the number.","keys":["x = 0"]},{"id":"2020-P1-Q8:(b)(i):1","from":"2020-P1-Q8","q":"Show that h(x) = (1/60)x² − (1/4)x + 3/5 is 0 when x = 12. What are its three terms worth at x = 12?","right":"2.4 − 3 + 0.6","wrong":["0.2 − 3 + 0.6","0.4 − 3 + 0.6","2.4 − 0.25 + 0.6"],"why":"(1/60)(12)² = 144 ÷ 60 = 2.4, (1/4)(12) = 3 and 3/5 = 0.6, so h(12) = 2.4 − 3 + 0.6 = 0.","hook":"Square first: (1/60)(12)² is 144 ÷ 60, not 12 ÷ 60.","keys":["144 ÷ 60 = 2.4"]},{"id":"2020-P1-Q8:(b)(ii):1","from":"2020-P1-Q8","q":"Swimmer: h(x) = (1/60)x² − (1/4)x + 3/5 m. She is on the surface when h(x) = 0, and h(12) = 0 is where she comes back up. How far from the block does she enter the water?","right":"3 m","wrong":["12 m","7.5 m","0.6 m"],"why":"Multiply h(x) = 0 by 60: x² − 15x + 36 = 0, so (x − 3)(x − 12) = 0. She comes up at 12 m, so she goes in at 3 m.","hook":"Two roots, two splashes: in at the first, out at the second.","keys":["x² − 15x + 36 = 0"]},{"id":"2020-P1-Q8:(b)(ii):2","from":"2020-P1-Q8","q":"To clear the fractions in (1/60)x² − (1/4)x + 3/5 = 0, you multiply every term by 60. What equation do you get?","right":"x² − 15x + 36 = 0","wrong":["x² − 15x + 3/5 = 0","x² − (1/4)x + 36 = 0","x² − 15x + 100 = 0"],"why":"60 × 1/60 = 1, 60 × 1/4 = 15 and 60 × 3/5 = 36, so x² − 15x + 36 = 0. Every term gets multiplied, the number too.","hook":"Multiply EVERY term by the common denominator, the number at the end too.","keys":["60 × 3/5 = 36"]},{"id":"2020-P1-Q8:(c)(i):1","from":"2020-P1-Q8","q":"Find h′(x), the derivative of h(x) = (1/60)x² − (1/4)x + 3/5.","right":"(1/30)x − 1/4","wrong":["(1/60)x − 1/4","(1/120)x − 1/4","(1/30)x − 1/4 + 3/5"],"why":"Bring the 2 down: 2 × 1/60 = 1/30, so (1/60)x² → (1/30)x. Then −(1/4)x → −1/4 and the 3/5 → 0.","hook":"Fractions follow the same rule: multiply by the power, then take one off.","keys":["2 × 1/60 = 1/30"]},{"id":"2020-P1-Q8:(c)(ii):1","from":"2020-P1-Q8","q":"Swimmer: h(x) = (1/60)x² − (1/4)x + 3/5 m, and h′(x) = (1/30)x − 1/4. How far from the block (x) does she reach her greatest depth?","right":"7.5 m","wrong":["3 m","0.008 m","120 m"],"why":"At the greatest depth the slope is 0: (1/30)x − 1/4 = 0, so (1/30)x = 1/4 and x = 30/4 = 7.5 m.","hook":"Deepest point = bottom of the U = flat tangent: set h′(x) = 0.","keys":["the slope is 0"]},{"id":"2020-P1-Q8:(c)(ii):2","from":"2020-P1-Q8","q":"Why do you set h′(x) = 0 to find where the swimmer is deepest?","right":"The slope is 0 at the bottom of the dip","wrong":["She is at the water's surface there","h′(x) gives her depth below the water","The curve is steepest at the bottom"],"why":"h′(x) is the slope of her path. At the lowest point she stops going down and starts coming up: the tangent is flat, so h′(x) = 0.","hook":"Top of a hill or bottom of a dip: the tangent is flat, so the derivative is 0.","keys":["the tangent is flat"]},{"id":"2020-P1-Q8:(c)(iii):1","from":"2020-P1-Q8","q":"Swimmer: h(x) = (1/60)x² − (1/4)x + 3/5 m. She is deepest at x = 7.5 m. Find her greatest depth.","right":"0.3375 m","wrong":["0 m","3.4125 m","1.15 m"],"why":"Put x = 7.5 into h itself: 0.9375 − 1.875 + 0.6 = −0.3375. The minus means below the water: 0.3375 m (27/80 m) deep.","hook":"f′ = 0 tells you where; f tells you how high (or how deep).","keys":["Put x = 7.5 into h itself"]},{"id":"2020-P1-Q8:(d)(i):1","from":"2020-P1-Q8","q":"Phelps' 50 m split times: 28.5 s for 50–100 m, then 29.33 s for 100–150 m. Find the percentage increase, correct to one decimal place.","right":"2.9%","wrong":["2.8%","0.8%","102.9%"],"why":"Increase ÷ old value × 100: (29.33 − 28.5) ÷ 28.5 × 100 = 0.83 ÷ 28.5 × 100 = 2.91…%, so 2.9%.","hook":"Percentage change: always divide by the OLD value.","keys":["Increase ÷ old value × 100"]},{"id":"2020-P1-Q8:(d)(i):2","from":"2020-P1-Q8","q":"Phelps' four 50 m splits: 24.85 s, 28.5 s, 29.33 s, then 30.68 s. Find the percentage increase of the last split on the one before it, to one decimal place.","right":"4.6%","wrong":["4.4%","23.5%","1.4%"],"why":"Compare with the previous split, 29.33 s: (30.68 − 29.33) ÷ 29.33 × 100 = 1.35 ÷ 29.33 × 100 = 4.60…%, so 4.6%.","hook":"'On the one before it': the old value is the previous split.","keys":["Compare with the previous split"]},{"id":"2020-P1-Q8:(d)(ii):1","from":"2020-P1-Q8","q":"Another swimmer's first 50 m split is 25.01 s. His second split is 14.7% longer, the same increase as Phelps'. Which calculation gives his second split?","right":"25.01 × 1.147","wrong":["25.01 × 0.147","25.01 + 14.7","28.5 × 1.147"],"why":"An increase of 14.7% means 100% + 14.7% = 114.7% of the old time: 25.01 × 1.147 = 28.69 s.","hook":"Increase by r%: multiply by (1 + r/100) in one step.","keys":["25.01 × 1.147 = 28.69 s"]},{"id":"2020-P1-Q8:(d)(ii):2","from":"2020-P1-Q8","q":"His four splits add up to 114.10 s. Phelps' finishing time was 1:53.36 (1 minute 53.36 seconds). What is the difference between their times?","right":"0.74 s","wrong":["39.26 s","60.74 s","1.26 s"],"why":"1:53.36 is 60 + 53.36 = 113.36 seconds, so the difference is 114.10 − 113.36 = 0.74 s.","hook":"Change minutes to seconds first: 1 minute is 60 seconds, not 100.","keys":["60 + 53.36 = 113.36"]},{"id":"2021-P1-Q5:(a):1","from":"2021-P1-Q5","q":"f(x) = 3x² − 6x + 7. Find f(0.67), correct to 2 decimal places.","right":"4.33","wrong":["4.99","7.02","4.32"],"why":"3(0.67)² = 3 × 0.4489 = 1.3467 and 6(0.67) = 4.02, so f(0.67) = 1.3467 − 4.02 + 7 = 4.3267 ≈ 4.33.","hook":"3x² means 3 × (x²): square first, then multiply.","keys":["3 × 0.4489 = 1.3467"]},{"id":"2021-P1-Q5:(b):1","from":"2021-P1-Q5","q":"f(x) = 3x² − 6x + 7. To find the value of x when f(x) = 4, what is your first step?","right":"Subtract 4: 3x² − 6x + 3 = 0","wrong":["Put x = 4 into f(x)","Add 4: 3x² − 6x + 11 = 0","Solve 3x² − 6x + 7 = 0"],"why":"f(x) = 4 means 3x² − 6x + 7 = 4. Take 4 from both sides so one side is 0: 3x² − 6x + 3 = 0. Then factorise.","hook":"f(x) = 4 asks for x. f(4) gives you a y. Don't mix them up.","keys":["Take 4 from both sides"]},{"id":"2021-P1-Q5:(b):2","from":"2021-P1-Q5","q":"f(x) = 3x² − 6x + 7. Find the value of x when f(x) = 4.","right":"x = 1","wrong":["x = −1","x = 5/3","x = 1 or x = −1"],"why":"3x² − 6x + 3 = 0 → x² − 2x + 1 = 0 → (x − 1)(x − 1) = 0, so x = 1, and only x = 1.","hook":"A repeated factor gives just one answer: the curve only touches that height.","keys":["(x − 1)(x − 1) = 0"]},{"id":"2021-P1-Q5:(c):1","from":"2021-P1-Q5","q":"Use calculus to find the co-ordinates of the local minimum point of f(x) = 3x² − 6x + 7.","right":"(1, 4)","wrong":["(−1, 16)","(2, 7)","(1, 0)"],"why":"f′(x) = 6x − 6 = 0 gives x = 1. Then f(1) = 3(1)² − 6(1) + 7 = 4, so the minimum is (1, 4).","hook":"'Use calculus' means differentiate: no f′(x) in your working, no marks.","keys":["f′(x) = 6x − 6 = 0"]},{"id":"2021-P1-Q5:(c):2","from":"2021-P1-Q5","q":"f(x) = 3x² − 6x + 7. You solved f′(x) = 0 and got x = 1. How do you get the y co-ordinate of the local minimum?","right":"Put x = 1 into f(x)","wrong":["Put x = 1 into f′(x)","Solve f(x) = 0","No need: the answer is just x = 1"],"why":"The point is on the curve y = f(x), so y = f(1) = 3 − 6 + 7 = 4. f′(1) = 0 is the slope there, not the height.","hook":"Turning point: f′(x) = 0 gives x, then f(x) gives y.","keys":["y = f(1) = 3 − 6 + 7 = 4"]},{"id":"2022-P1-Q4:(a)(i):1","from":"2022-P1-Q4","q":"g(x) = x³ − 7x² + x − 12. Work out the value of g(5).","right":"−57","wrong":["−1107","−167","48"],"why":"Powers first: 5³ = 125 and 7(5)² = 7 × 25 = 175. So g(5) = 125 − 175 + 5 − 12 = −57.","hook":"Powers before multiplying: 7(5)² is 7 × 25, not 35².","keys":["7 × 25 = 175"]},{"id":"2022-P1-Q4:(a)(ii):1","from":"2022-P1-Q4","q":"Find g′(x), the derivative of g(x) = x³ − 7x² + x − 12.","right":"3x² − 14x + 1","wrong":["3x² − 14x − 11","3x² − 7x + 1","3x² − 14x"],"why":"x³ → 3x², −7x² → 2 × (−7)x = −14x, x → 1 and −12 → 0.","hook":"An x on its own becomes 1; a number on its own becomes 0.","keys":["x → 1"]},{"id":"2022-P1-Q4:(a)(iii):1","from":"2022-P1-Q4","q":"g(x) = x³ − 7x² + x − 12. For the tangent to y = g(x) at x = 5, where do its point and its slope come from?","right":"Point from g(5), slope from g′(5)","wrong":["Point from g′(5), slope from g(5)","Point (5, 0), slope from g′(5)","Point from g(5), slope g(5) ÷ 5"],"why":"The tangent touches the curve at (5, g(5)) = (5, −57). Its slope is the slope of the curve there: g′(5) = 6.","hook":"Tangent recipe: point from f, slope from f′, then y − y₁ = m(x − x₁).","keys":["g′(5) = 6"]},{"id":"2022-P1-Q4:(a)(iii):2","from":"2022-P1-Q4","q":"g(5) = −57 and g′(5) = 6. Find the equation of the tangent to y = g(x) at x = 5, in the form ax + by + c = 0.","right":"6x − y − 87 = 0","wrong":["6x − y + 27 = 0","6x − y − 27 = 0","57x + y − 291 = 0"],"why":"Point (5, −57), slope 6: y − (−57) = 6(x − 5), so y + 57 = 6x − 30, which gives 6x − y − 87 = 0.","hook":"Finish in the form asked: everything on one side, = 0.","keys":["y + 57 = 6x − 30"]},{"id":"2022-P1-Q4:(b)(i):1","from":"2022-P1-Q4","q":"A graph of y = u(x), 0 ≤ x ≤ 10: it rises from (0, −2.5), crosses the x-axis at x = 3, climbs to (4, 2), is flat near 2.2 around x = 5.5, then falls to (10, 0.4). Where is u′(x) negative?","right":"Where it falls, e.g. x = 8","wrong":["Below the x-axis, e.g. x = 1","Where it crosses the x-axis, x = 3","At the flat top, where it turns"],"why":"u′(x) is the slope. It is negative where the graph goes down as you move right: after the flat top, e.g. x = 8.","hook":"Read left to right: uphill u′ > 0, downhill u′ < 0, flat u′ = 0.","keys":["goes down as you move right"]},{"id":"2022-P1-Q4:(b)(ii):1","from":"2022-P1-Q4","q":"How do you estimate u′(4) from the graph of y = u(x)?","right":"Draw the tangent at x = 4: its slope","wrong":["Read the height of the curve at x = 4","Join (0, u(0)) to (4, u(4)): its slope","Draw the tangent where y = 4: its slope"],"why":"u′(4) is the slope of the curve at x = 4, which is the slope of the tangent there. A line to another point on the curve is not the tangent.","hook":"A derivative at a point = the slope of the tangent at that point.","keys":["the slope of the tangent there"]},{"id":"2022-P1-Q4:(b)(ii):2","from":"2022-P1-Q4","q":"The tangent you draw to y = u(x) at the point (4, 2) also passes through the point (6, 3). Use it to estimate u′(4).","right":"1/2","wrong":["2","−1/2","1"],"why":"u′(4) is the slope of the tangent: rise ÷ run = (3 − 2) ÷ (6 − 4) = 1/2.","hook":"Slope = rise ÷ run: the up goes on top.","keys":["rise ÷ run"]},{"id":"2022-P1-Q7:(a)(i):1","from":"2022-P1-Q7","q":"Joseph's heart-rate is h(x) = −0.38x³ + 2.6x² − 0.13x + 158 BPM, x minutes into a session. Find h(2), to the nearest whole number.","right":"165","wrong":["166","171","160"],"why":"h(2) = −0.38(8) + 2.6(4) − 0.13(2) + 158 = −3.04 + 10.4 − 0.26 + 158 = 165.1 ≈ 165.","hook":"Powers first, with the minus kept: −0.38(2)³ = −0.38 × 8.","keys":["−0.38(8)"]},{"id":"2022-P1-Q7:(a)(ii):1","from":"2022-P1-Q7","q":"Heart-rate table: at x = 0, 1, 2, 3, 4, 5, 6 minutes, h(x) = 158, 160, 165, 171, 175, 175, 169 BPM. When you draw the curve through these points, where is its peak?","right":"Between 4 and 5 minutes","wrong":["At exactly 4 minutes","At exactly 5 minutes","Two peaks: at 4 and at 5 minutes"],"why":"h(4) and h(5) are both about 175, with lower values either side, so the smooth curve tops out between 4 and 5 minutes (at 4.54, part (f)).","hook":"Two equal top values: a smooth curve peaks once, between them.","keys":["between 4 and 5 minutes"]},{"id":"2022-P1-Q7:(b):1","from":"2022-P1-Q7","q":"On the graph of Joseph's heart-rate, h(x) in BPM against time x in minutes, what does the point A (6, 169) mean?","right":"At 6 minutes his heart-rate is 169 BPM","wrong":["At 169 minutes his heart-rate is 6 BPM","It rose by 169 BPM in 6 minutes","It stayed at 169 BPM for 6 minutes"],"why":"The first number is the time x (6 minutes) and the second is the heart-rate h(x) (169 BPM): 6 minutes after the start, his heart-rate is 169 BPM.","hook":"A point is (x, y): say what each number is, with its units.","keys":["6 minutes after the start"]},{"id":"2022-P1-Q7:(c):1","from":"2022-P1-Q7","q":"From A (6, 169), Joseph's heart-rate stays level for 2 minutes, then falls at a steady 10 BPM per minute for 2 minutes. Where does the graph end?","right":"(10, 149)","wrong":["(10, 159)","(8, 149)","(10, 129)"],"why":"Level from (6, 169) to (8, 169). Then 2 minutes at 10 BPM per minute is a drop of 20: 169 − 20 = 149, at x = 10.","hook":"Rate × time = change: 10 BPM per minute for 2 minutes is 20 BPM.","keys":["169 − 20 = 149"]},{"id":"2022-P1-Q7:(c):2","from":"2022-P1-Q7","q":"Joseph's heart-rate falls at a steady rate of 10 BPM per minute for 2 minutes. What does that part of the graph look like?","right":"A straight line sloping down","wrong":["A curve that gets steeper","A curve that levels off","A flat (horizontal) line"],"why":"A steady rate means the same drop every minute, so the slope never changes: a straight line, going down 10 for every 1 across.","hook":"Steady rate = constant slope = straight line.","keys":["a straight line"]},{"id":"2022-P1-Q7:(d):1","from":"2022-P1-Q7","q":"Calories burned per minute: c(x) = 0.1 h(x) − 7, where h(x) is Joseph's heart-rate after x minutes. His heart-rate at 6 minutes is 169 BPM. Find c(6).","right":"9.9","wrong":["−6.4","16.2","16.9"],"why":"c(6) uses h(6), the heart-rate at 6 minutes: c(6) = 0.1(169) − 7 = 16.9 − 7 = 9.9 calories per minute.","hook":"c(6) needs h(6) first: put the heart-rate in, not the time.","keys":["c(6) uses h(6)"]},{"id":"2022-P1-Q7:(e):1","from":"2022-P1-Q7","q":"A smart watch beeps every 15 seconds: first at exactly 2:55 p.m. and last at exactly 3:23 p.m. How many times does it beep in total, including the first and last?","right":"113","wrong":["112","273","421"],"why":"2:55 to 3:23 is 28 minutes. 4 beeps a minute gives 4 × 28 = 112 gaps, and there is one more beep than gaps: 112 + 1 = 113.","hook":"Fence posts: count the gaps, then add one for the first post.","keys":["112 + 1 = 113"]},{"id":"2022-P1-Q7:(f):1","from":"2022-P1-Q7","q":"Solve h′(x) = −1.14x² + 5.2x − 0.13 = 0 to find when Joseph's heart-rate is at a maximum, 0 ≤ x ≤ 6. Give your answer in minutes, to 2 decimal places.","right":"4.54 minutes","wrong":["0.03 minutes","−4.54 minutes","9.07 minutes"],"why":"x = (−5.2 ± √(5.2² − 4(−1.14)(−0.13))) ÷ 2(−1.14) = 4.536… or 0.025…. The peak is between 4 and 5 minutes: 4.54.","hook":"−b ± √(b² − 4ac), all over 2a: keep every minus sign in brackets.","keys":["The peak is between 4 and 5 minutes"]},{"id":"2022-P1-Q7:(f):2","from":"2022-P1-Q7","q":"Heart-rate: h′(x) = 0 gives x = 4.54 or x = 0.03 minutes. Why is 4.54 the time of the maximum heart-rate?","right":"0.03 is a minimum; the top is near 4.5","wrong":["Always take the larger root","0.03 is outside 0 ≤ x ≤ 6","Both are maxima: take the later one"],"why":"h′(x) = 0 at both turning points. At 0.03 min the heart-rate is at its lowest (about 158); the curve peaks between 4 and 5 min, so 4.54.","hook":"Two roots of f′(x) = 0? Use the graph or table to see which one is the top.","keys":["the curve peaks between 4 and 5 min"]},{"id":"2022-P1-Q10:(a)(i):1","from":"2022-P1-Q10","q":"A hurling ball's height is h = −2t² + 5t + 1.2 metres, t seconds after it is hit. How high was the ball when it was hit?","right":"1.2 m","wrong":["4.2 m","0 m","4.325 m"],"why":"When it was hit, t = 0: h = −2(0)² + 5(0) + 1.2 = 1.2 m.","hook":"The start of the motion is t = 0: only the number on its own is left.","keys":["t = 0"]},{"id":"2022-P1-Q10:(a)(ii):1","from":"2022-P1-Q10","q":"Hurling ball: h = −2t² + 5t + 1.2 metres after t seconds. It was caught after 2.4 seconds. How high was it when it was caught?","right":"1.68 m","wrong":["8.4 m","24.72 m","36.24 m"],"why":"Square first: 2.4² = 5.76, so h = −2(5.76) + 5(2.4) + 1.2 = −11.52 + 12 + 1.2 = 1.68 m.","hook":"−2t² is −2 × (t²): only the t is squared, and the minus stays.","keys":["2.4² = 5.76"]},{"id":"2022-P1-Q10:(a)(iii):1","from":"2022-P1-Q10","q":"Hurling ball: h = −2t² + 5t + 1.2 metres after t seconds. To find when the ball is 3.2 m high, what do you do?","right":"Solve −2t² + 5t + 1.2 = 3.2","wrong":["Solve −2t² + 5t + 1.2 = 0","Solve −4t + 5 = 3.2","Put t = 3.2 into the formula"],"why":"3.2 is a height, so set h = 3.2: −2t² + 5t + 1.2 = 3.2, which gives 2t² − 5t + 2 = 0. Then solve for t.","hook":"Given the height, find the time: set the formula equal to that height.","keys":["3.2 is a height"]},{"id":"2022-P1-Q10:(a)(iii):2","from":"2022-P1-Q10","q":"h = −2t² + 5t + 1.2. Over the halfway line the ball was 3.2 m high and its height was decreasing. How many seconds after it was hit was that?","right":"2 s","wrong":["0.5 s","1.25 s","2.72 s"],"why":"−2t² + 5t + 1.2 = 3.2 → 2t² − 5t + 2 = 0 → (2t − 1)(t − 2) = 0, so t = ½ or 2. Coming down means the later one: 2 s.","hook":"A ball passes each height twice: once going up, once coming down.","keys":["(2t − 1)(t − 2) = 0"]},{"id":"2022-P1-Q10:(a)(iv):1","from":"2022-P1-Q10","q":"Hurling ball: h = −2t² + 5t + 1.2 metres. At its greatest height the ball is 4.325 m up. What is dh/dt at that moment?","right":"0 m/s","wrong":["4.325 m/s","5 m/s","−4 m/s"],"why":"dh/dt is how fast the height changes. At the very top the ball stops rising and starts falling, so dh/dt = 0 there.","hook":"Rate, not amount: at the top the height is big but its rate of change is 0.","keys":["dh/dt = 0 there"]},{"id":"2022-P1-Q10:(a)(iv):2","from":"2022-P1-Q10","q":"h = −2t² + 5t + 1.2 metres after t seconds. Find dh/dt and hence how long it took the ball to reach its greatest height.","right":"1.25 s","wrong":["2.5 s","0.8 s","−1.25 s"],"why":"dh/dt = −4t + 5. At the greatest height −4t + 5 = 0, so 4t = 5 and t = 5/4 = 1.25 s.","hook":"Greatest height: set dh/dt = 0 and solve for t.","keys":["−4t + 5 = 0"]},{"id":"2022-P1-Q10:(b):1","from":"2022-P1-Q10","q":"A ball is 1 m high when it is hit and reaches its greatest height, 5 m, after 2 seconds. Its height graph is a quadratic. Which other point must be on it?","right":"(4, 1)","wrong":["(4, 0)","(−2, 1)","(5, 2)"],"why":"A quadratic is symmetric about its top, at t = 2. t = 0 is 2 s before the top, so 2 s after it, at t = 4, the height is 1 m again: (4, 1).","hook":"Symmetry gives a free point: mirror the start in the top.","keys":["the height is 1 m again"]},{"id":"2022-P1-Q10:(b):2","from":"2022-P1-Q10","q":"The ball's height graph goes through (0, 1), (2, 5) and (4, 1), and the ball hits the ground without being caught. Where should your graph stop?","right":"On the t-axis, just after t = 4","wrong":["At (4, 1), 1 m above the ground","On the t-axis at exactly t = 4","At t = 5, the end of the axes"],"why":"At t = 4 the ball is still 1 m up. It keeps falling until the height is 0, so the curve carries on down to the t-axis just after t = 4.","hook":"Hits the ground means height 0: finish the curve on the t-axis.","keys":["until the height is 0"]},{"id":"2022-P1-Q10:(c)(i):1","from":"2022-P1-Q10","q":"A hurl usually costs €33. Keith gets a student discount of 15%. Work out the price Keith pays for the hurl.","right":"€28.05","wrong":["€4.95","€18.00","€37.95"],"why":"15% off means he pays 85%: €33 × 0.85 = €28.05.","hook":"A discount of r%: pay (100 − r)%, in one multiplication.","keys":["€33 × 0.85 = €28.05"]},{"id":"2022-P1-Q10:(c)(ii):1","from":"2022-P1-Q10","q":"A jersey costs €49.50, including VAT at 23%. Work out the VAT on the jersey, correct to the nearest cent.","right":"€9.26","wrong":["€11.39","€40.24","€38.12"],"why":"€49.50 is 123% of the price before VAT. 1% = 49.50 ÷ 123 = 0.4024…, so the VAT is 23 × 0.4024… = 9.256… ≈ €9.26.","hook":"A price including VAT is 123%, not 100%.","keys":["€49.50 is 123%"]},{"id":"2023-P1-Q4:(a)(i):1","from":"2023-P1-Q4","q":"From the graph of y = g(x), you want to estimate g(1.5). What do you read off the graph?","right":"The height of the curve at x = 1.5","wrong":["The x where the curve is 1.5 high","The slope of the curve at x = 1.5","1.5 times the y-intercept"],"why":"g(1.5) is the y value when x = 1.5: go up from 1.5 on the x-axis to the curve, then across to the y-axis (about 2 here).","hook":"g(number): the number goes on the x-axis; the answer is read on the y-axis.","keys":["go up from 1.5 on the x-axis"]},{"id":"2023-P1-Q4:(a)(ii):1","from":"2023-P1-Q4","q":"From the graph of y = g(x), how do you estimate the value of x for which g(x) = −6?","right":"Across from −6 on the y-axis; read x","wrong":["Up from −6 on the x-axis; read y","Across from 6 on the y-axis; read x","Read where the curve cuts the x-axis"],"why":"g(x) = −6 is a height. Find −6 on the y-axis, go across to the curve, then down to read x (about −2.8 here).","hook":"Known height: start on the y-axis. Known x: start on the x-axis.","keys":["g(x) = −6 is a height"]},{"id":"2023-P1-Q4:(a)(iii):1","from":"2023-P1-Q4","q":"On the graph of a function g, what is a real root of g?","right":"A point where the graph cuts the x-axis","wrong":["A point where it cuts the y-axis","A turning point (hump or dip)","The lowest point of the graph"],"why":"A root is a value of x where g(x) = 0, and g(x) = 0 is exactly where the graph meets the x-axis.","hook":"Roots live on the x-axis: count the crossings.","keys":["g(x) = 0"]},{"id":"2023-P1-Q4:(a)(iii):2","from":"2023-P1-Q4","q":"A cubic graph g, −3 ≤ x ≤ 2, rises from (−3, −8) to a hump at about (−1.6, −1), dips to about (0.25, −3.1), then climbs to (2, 8). How many real roots does g have here?","right":"1","wrong":["3","2","0"],"why":"Roots are where the graph cuts the x-axis. The hump and the dip are both below it, so the graph crosses only once, after the dip.","hook":"Count the crossings, not the bumps: a cubic can have 1, 2 or 3 roots.","keys":["the graph crosses only once"]},{"id":"2023-P1-Q4:(a)(iv):1","from":"2023-P1-Q4","q":"Graph of g, −3 ≤ x ≤ 2: lowest point drawn (−3, −8), a hump at about (−1.6, −1), a dip at about (0.25, −3.1), highest point drawn (2, 8). What is the local maximum point?","right":"(−1.6, −1)","wrong":["(2, 8)","(0.25, −3.1)","(−1, −1.6)"],"why":"A local maximum is the top of a hump, where the curve turns from going up to going down: (−1.6, −1). (2, 8) is just where the drawing ends.","hook":"Local max = top of a hill, even if the graph goes higher somewhere else.","keys":["the top of a hump"]},{"id":"2023-P1-Q4:(a)(iv):2","from":"2023-P1-Q4","q":"The graph of g has a hump at about (−1.6, −1) and a dip at about (0.25, −3.1). What is g′(x) at these two points?","right":"0 at both","wrong":["−1 at the hump, −3.1 at the dip","0 at the hump only","Largest at the hump, least at the dip"],"why":"g′(x) is the slope. At the top of a hump and the bottom of a dip the curve is flat for a moment, so the slope is 0 at both.","hook":"Hump or dip, the tangent is flat: g′(x) = 0 at every turning point.","keys":["the slope is 0 at both"]},{"id":"2023-P1-Q4:(b)(i):1","from":"2023-P1-Q4","q":"Find h′(x), the derivative of h(x) = x³ + 2x² − x − 8.","right":"3x² + 4x − 1","wrong":["3x² + 4x − 9","3x² + 4x + 1","3x² + 2x − 1"],"why":"x³ → 3x², 2x² → 2 × 2x = 4x, −x → −1 and −8 → 0.","hook":"Keep each term's sign: −x becomes −1, not +1.","keys":["−x → −1"]},{"id":"2023-P1-Q4:(b)(ii):1","from":"2023-P1-Q4","q":"h(x) = x³ + 2x² − x − 8 and h′(x) = 3x² + 4x − 1. What is the slope of the tangent to h(x) at the point (2, 6)?","right":"19","wrong":["6","131","43"],"why":"The slope is h′ at x = 2: h′(2) = 3(2)² + 4(2) − 1 = 12 + 8 − 1 = 19.","hook":"Put the point's x into h′(x), not its y.","keys":["h′(2) = 3(2)² + 4(2) − 1"]},{"id":"2023-P1-Q4:(b)(ii):2","from":"2023-P1-Q4","q":"The tangent to h(x) = x³ + 2x² − x − 8 at the point (2, 6) has slope 19. Find the equation of the tangent.","right":"19x − y − 32 = 0","wrong":["19x − y + 44 = 0","19x − y − 44 = 0","19x − y + 6 = 0"],"why":"y − y₁ = m(x − x₁): y − 6 = 19(x − 2), so y − 6 = 19x − 38, which gives 19x − y − 32 = 0.","hook":"y − y₁ = m(x − x₁): the point's own numbers go in after minus signs.","keys":["y − 6 = 19(x − 2)"]},{"id":"2023-P1-Q6:(a)(i):1","from":"2023-P1-Q6","q":"g(x) = x² + 8x − 6. Find the value of g(−5).","right":"−21","wrong":["−71","59","−56"],"why":"(−5)² = +25 and 8(−5) = −40, so g(−5) = 25 − 40 − 6 = −21.","hook":"A negative squared is positive: (−5)² = +25. Use brackets on the calculator.","keys":["(−5)² = +25"]},{"id":"2023-P1-Q6:(a)(ii):1","from":"2023-P1-Q6","q":"Use calculus to find the value of x which gives the minimum value of g(x) = x² + 8x − 6.","right":"x = −4","wrong":["x = 4","x = 0.69","x = −8"],"why":"g′(x) = 2x + 8. At the minimum the slope is 0: 2x + 8 = 0, so x = −4. (Solving g(x) = 0 instead earns no marks.)","hook":"Max or min: set the DERIVATIVE equal to 0, not the function.","keys":["2x + 8 = 0"]},{"id":"2023-P1-Q6:(b):1","from":"2023-P1-Q6","q":"Expand and simplify (2x − 4)² − 6.","right":"4x² − 16x + 10","wrong":["4x² + 10","4x² − 8x + 10","2x² − 16x + 10"],"why":"(2x − 4)(2x − 4) = 4x² − 8x − 8x + 16 = 4x² − 16x + 16. Then take away 6: 4x² − 16x + 10.","hook":"Squaring a bracket: write it out twice and multiply every term by every term.","keys":["4x² − 8x − 8x + 16"]},{"id":"2023-P1-Q6:(c):1","from":"2023-P1-Q6","q":"You solve 9x² + 6x − 5 = 0 with the quadratic formula. What is b² − 4ac?","right":"216","wrong":["−144","192","−5"],"why":"a = 9, b = 6, c = −5: b² − 4ac = 36 − 4(9)(−5) = 36 + 180 = 216. Minus times minus makes +180.","hook":"Put c in with its sign, in brackets: −4(9)(−5) = +180.","keys":["36 + 180 = 216"]},{"id":"2023-P1-Q6:(c):2","from":"2023-P1-Q6","q":"Solve the equation 9x² + 6x − 5 = 0. Give each answer correct to 2 decimal places.","right":"0.48 or −1.15","wrong":["1.15 or −0.48","0.97 or −2.30","−5.18 or −6.82"],"why":"x = (−6 ± √216) ÷ 18, so x = 0.483… ≈ 0.48 or x = −1.149… ≈ −1.15.","hook":"In the formula the whole top, −b ± √(b² − 4ac), is divided by 2a.","keys":["(−6 ± √216) ÷ 18"]},{"id":"2023-P1-Q7:(a)(i):1","from":"2023-P1-Q7","q":"The runoff curve number is C = 1000 ÷ (S + 10). Find the value of C when S = 15.","right":"40","wrong":["76.67","66.67","0.025"],"why":"Work out the bottom first: 15 + 10 = 25. Then C = 1000 ÷ 25 = 40.","hook":"Bottom first: the whole of (S + 10) divides the 1000.","keys":["15 + 10 = 25"]},{"id":"2023-P1-Q7:(a)(ii):1","from":"2023-P1-Q7","q":"C = 1000 ÷ (S + 10). When S increases, does C increase or decrease, and why?","right":"Decreases: the bottom gets bigger","wrong":["Increases: S is getting bigger","Increases: the bottom gets bigger","Stays the same: the top is fixed"],"why":"S is on the bottom. As S grows, 1000 is divided by a bigger number, so C gets smaller: 1000 ÷ 25 = 40 but 1000 ÷ 50 = 20.","hook":"Bigger bottom, smaller fraction: test it with two numbers.","keys":["1000 ÷ 25 = 40 but 1000 ÷ 50 = 20"]},{"id":"2023-P1-Q7:(a)(iii):1","from":"2023-P1-Q7","q":"Rearrange C = 1000 ÷ (S + 10) to write S in terms of C.","right":"S = (1000 − 10C) ÷ C","wrong":["S = 1000C − 10","S = 1000 ÷ C + 10","S = (1000 − 10) ÷ C"],"why":"Multiply by (S + 10): C(S + 10) = 1000, so CS + 10C = 1000, CS = 1000 − 10C and S = (1000 − 10C) ÷ C.","hook":"Get rid of the fraction first: multiply both sides by the bottom.","keys":["CS + 10C = 1000"]},{"id":"2023-P1-Q7:(a)(iv):1","from":"2023-P1-Q7","q":"S = (1000 − 10C) ÷ C, and the values of C go from 30 to 100. What is the range of values of S?","right":"0 to 23.3","wrong":["9.1 to 25","10 to 33.3","11.1 to 50"],"why":"C = 30: S = (1000 − 300) ÷ 30 = 23.3…; C = 100: S = (1000 − 1000) ÷ 100 = 0. So S goes from 0 to 23.3.","hook":"Put each end of the range of C into the formula for S.","keys":["S = (1000 − 1000) ÷ 100 = 0"]},{"id":"2023-P1-Q7:(b)(i):1","from":"2023-P1-Q7","q":"The probability that it is raining t hours after the start of the day is P(t) = 0.3 + 0.02t, 0 ≤ t ≤ 24. Find P(0) and P(24).","right":"0.3 and 0.78","wrong":["0.3 and 0.348","0 and 0.48","0.32 and 0.78"],"why":"Start of the day, t = 0: P(0) = 0.3. End of the day, t = 24: P(24) = 0.3 + 0.02(24) = 0.3 + 0.48 = 0.78.","hook":"Start of the day is t = 0, the end is t = 24: put each into P(t).","keys":["0.3 + 0.48 = 0.78"]},{"id":"2023-P1-Q7:(b)(ii):1","from":"2023-P1-Q7","q":"P(t) = 0.3 + 0.02t is the probability that it is raining t hours into the day. Find P′(t). What does its value mean?","right":"0.02: P goes up 0.02 every hour","wrong":["0.02: a 2% chance that it is raining","0.3: the chance of rain at the start","0.32: the chance after 1 hour"],"why":"P′(t) = 0.02 (the 0.3 → 0). It is a rate: the probability that it is raining goes up by 0.02 (2%) every hour.","hook":"A derivative is a rate: how much it changes per hour, not how much there is.","keys":["It is a rate"]},{"id":"2023-P1-Q7:(b)(iii):1","from":"2023-P1-Q7","q":"P(t) = 0.3 + 0.02t. At a certain time, the probability that it is raining is 0.35. What is the probability exactly 1 hour later?","right":"0.37","wrong":["0.32","0.357","0.55"],"why":"P′(t) = 0.02: the probability goes up 0.02 every hour, all day. One hour later: 0.35 + 0.02 = 0.37.","hook":"Constant rate: add the rate once for every hour.","keys":["0.35 + 0.02 = 0.37"]},{"id":"2024-P1-Q5:(a):1","from":"2024-P1-Q5","q":"Find the value of (3x + 5)/10 − 1/(x + 3) when x = 2. Give your answer in the form a/b.","right":"9/10","wrong":["10/5","19/10","−12/5"],"why":"(3(2) + 5)/10 − 1/(2 + 3) = 11/10 − 1/5 = 11/10 − 2/10 = 9/10.","hook":"Subtract fractions over a common bottom: never subtract the bottoms.","keys":["11/10 − 2/10 = 9/10"]},{"id":"2024-P1-Q5:(b):1","from":"2024-P1-Q5","q":"f(x) = 5x² − 20x + 2. What is f′(x)?","right":"10x − 20","wrong":["10x − 18","5x − 20","10x² − 20x"],"why":"5x² → 2 × 5x = 10x, −20x → −20, and the 2 on its own → 0.","hook":"A number on its own has a flat graph, slope 0: it disappears.","keys":["the 2 on its own → 0"]},{"id":"2024-P1-Q5:(b):2","from":"2024-P1-Q5","q":"Use calculus to find the co-ordinates of the local minimum point of f(x) = 5x² − 20x + 2.","right":"(2, −18)","wrong":["(−2, 62)","(4, 2)","(0.1, 0)"],"why":"f′(x) = 10x − 20 = 0 gives x = 2. Then f(2) = 5(4) − 40 + 2 = −18, so the minimum is (2, −18).","hook":"Three steps, three marks: f′(x), solve f′(x) = 0 for x, then f(x) for y.","keys":["f′(x) = 10x − 20 = 0"]},{"id":"2024-P1-Q5:(c):1","from":"2024-P1-Q5","q":"A straight line g(x) passes through (−3, −1), (0, 1) and (6, 5). Find its rate of change, g′(x), in the form a/b.","right":"2/3","wrong":["3/2","5/6","−2/3"],"why":"For a line, g′(x) is its slope: rise ÷ run = (5 − 1) ÷ (6 − 0) = 4/6 = 2/3, the same all along the line.","hook":"Straight line: the derivative is just the slope, the same everywhere.","keys":["4/6 = 2/3"]},{"id":"2024-P1-Q7:(a)(i):1","from":"2024-P1-Q7","q":"Bacteria in a dish: p(t) = t³ − 6t² + 6t + 20 thousand, t hours after the start. Find p(3).","right":"11","wrong":["−7","119","29"],"why":"p(3) = 27 − 6(9) + 18 + 20 = 27 − 54 + 18 + 20 = 11 (thousand).","hook":"Cube and square before multiplying: 6t² at t = 3 is 6 × 9.","keys":["27 − 54 + 18 + 20 = 11"]},{"id":"2024-P1-Q7:(a)(iii):1","from":"2024-P1-Q7","q":"Find p′(t), the derivative of p(t) = t³ − 6t² + 6t + 20.","right":"3t² − 12t + 6","wrong":["3t² − 12t + 26","3t² − 12t","t² − 6t + 6"],"why":"t³ → 3t², −6t² → 2 × (−6)t = −12t, 6t → 6 and the 20 → 0.","hook":"Same rule for t as for x: power down in front, then one off.","keys":["the 20 → 0"]},{"id":"2024-P1-Q7:(a)(iv):1","from":"2024-P1-Q7","q":"Bacteria: p(t) = t³ − 6t² + 6t + 20 and p′(t) = 3t² − 12t + 6. Find p′(2).","right":"−6","wrong":["16","18","42"],"why":"p′(2) = 3(2)² − 12(2) + 6 = 12 − 24 + 6 = −6. Negative: at 2 hours the number of bacteria is falling.","hook":"p′(2): put 2 into the derivative, not into p(t).","keys":["12 − 24 + 6 = −6"]},{"id":"2024-P1-Q7:(a)(v):1","from":"2024-P1-Q7","q":"p(t) is the number of bacteria, in thousands, t hours after the start. p′(4) = 6. What does this mean?","right":"At 4 h it grows by 6000 per hour","wrong":["At 4 h there are 6000 bacteria","At 4 h it grows by 6 per hour","In 4 h it grew by 6000 in total"],"why":"p′(4) is a rate: positive, so growing. p is in thousands and t in hours, so 6 means 6000 bacteria per hour.","hook":"Derivative in context: up or down, by how much, per what.","keys":["p′(4) is a rate"]},{"id":"2024-P1-Q7:(a)(v):2","from":"2024-P1-Q7","q":"p′(4) = 6, where p(t) is the number of bacteria at time t. What is the graph of p doing at t = 4?","right":"Going up as t increases","wrong":["Going down as t increases","Flat: a turning point","At a height of 6 (thousand)"],"why":"p′(4) is the slope of the graph at t = 4. It is positive, so the graph is going up there: the bacteria are increasing.","hook":"Sign of the derivative = direction of the graph: + up, − down, 0 flat.","keys":["It is positive"]},{"id":"2024-P1-Q7:(b)(i):1","from":"2024-P1-Q7","q":"Bacteria: k(t) = 3000 × 2.72^(0.5t) after t hours. Find the number of bacteria after 1 hour, correct to the nearest whole number.","right":"4948","wrong":["4080","8160","90"],"why":"k(1) = 3000 × 2.72^0.5 = 3000 × 1.649… = 4947.7… ≈ 4948. Only the 2.72 is raised to the power.","hook":"Power before multiplying: 3000 × (2.72^0.5). Put the power in brackets.","keys":["Only the 2.72 is raised to the power"]},{"id":"2024-P1-Q7:(b)(ii):1","from":"2024-P1-Q7","q":"k(t) = 3000 × 2.72^(0.5t) bacteria after t hours. Find the smallest whole number of hours, n, after which there are at least 35 000 bacteria.","right":"5","wrong":["4","3","11"],"why":"k(4) = 3000 × 2.72² = 22 195, less than 35 000, but k(5) = 3000 × 2.72^2.5 = 36 605, more. So n = 5.","hook":"Smallest n: show the value just below the target and the one just above.","keys":["k(5) = 3000 × 2.72^2.5 = 36 605"]},{"id":"2025-P1-Q4:(a):1","from":"2025-P1-Q4","q":"Solve the equation 5(a − 3) = 2a + 7.","right":"a = 22/3","wrong":["a = 10/3","a = −8/3","a = 22/7"],"why":"5a − 15 = 2a + 7, so 5a − 2a = 7 + 15, giving 3a = 22 and a = 22/3.","hook":"Multiply the 5 into BOTH terms of the bracket; change sign when you cross the =.","keys":["3a = 22"]},{"id":"2025-P1-Q4:(b):1","from":"2025-P1-Q4","q":"Find f′(x), the derivative of f(x) = x³ − 3x² + 4x − 8.","right":"3x² − 6x + 4","wrong":["3x² − 6x − 4","3x² − 3x + 4","3x² + 6x + 4"],"why":"x³ → 3x², −3x² → 2 × (−3)x = −6x, 4x → 4 and −8 → 0.","hook":"The sign travels with its term: −3x² gives −6x.","keys":["−3x² → 2 × (−3)x = −6x"]},{"id":"2025-P1-Q4:(b):2","from":"2025-P1-Q4","q":"f(x) = x³ − 3x² + 4x − 8, so f′(x) = 3x² − 6x + 4. Find the slope of the tangent to f(x) at the point (2, −4).","right":"4","wrong":["−4","8","76"],"why":"The slope is f′(2) = 3(2)² − 6(2) + 4 = 12 − 12 + 4 = 4. Putting 2 into f(x) only gives −4, the height of the point.","hook":"Slope at a point: put its x into f′(x), never into f(x).","keys":["f′(2) = 3(2)² − 6(2) + 4"]},{"id":"2025-P1-Q4:(c)(i):1","from":"2025-P1-Q4","q":"A cubic graph g: P is at the top of its hump, Q is on the part going down, R is on the part going up after the low point. All three are above the x-axis. Where is g′(x) < 0?","right":"At Q","wrong":["At P","At R","At none of them"],"why":"g′(x) is the slope. It is negative where the curve goes down as you move right: at Q. Being above the x-axis is about g(x), not g′(x).","hook":"The sign of g′ comes from the direction of the curve, not its height.","keys":["at Q"]},{"id":"2025-P1-Q4:(c)(i):2","from":"2025-P1-Q4","q":"On a cubic graph g, the point R is on the part going up after the low point. Which is true at R?","right":"g′(x) > 0: the curve is rising","wrong":["g′(x) < 0: R is lower than P","g′(x) = 0: R is near the low point","g′(x) < 0: it fell to get there"],"why":"At R the curve is going up as you move right, so its slope is positive: g′(x) > 0. How high R is, or what came before, does not matter.","hook":"Uphill to the right: g′ > 0. Downhill: g′ < 0. Flat: g′ = 0.","keys":["its slope is positive"]},{"id":"2025-P1-Q4:(c)(ii):1","from":"2025-P1-Q4","q":"On a cubic graph g, P is at the top of the hump. What is the reason that g′(x) = 0 at P?","right":"A turning point: the tangent is flat","wrong":["The curve is at its steepest at P","g(x) = 0 at P","g′(x) is biggest at the top"],"why":"At P the curve stops going up and starts going down: it is a turning point, so the tangent there is horizontal and its slope, g′(x), is 0.","hook":"Turning point = flat tangent = derivative 0.","keys":["it is a turning point"]},{"id":"2025-P1-Q8:(a)(i):1","from":"2025-P1-Q8","q":"A company's profit is P(x) = −1.5x² + 10.5x − 4 million euro, where x is the number of phones it makes, in tens of thousands. Find P(0) and say what it means.","right":"−4: no phones made, a €4m loss","wrong":["0: no phones made, no profit","4: no phones made, a €4m profit","−4: a loss of €4 on each phone"],"why":"P(0) = −1.5(0)² + 10.5(0) − 4 = −4. x = 0 means no phones, and −4 million euro is a loss: making no phones loses €4 million.","hook":"Explain in context: what x = 0 means AND what −4 means, with units.","keys":["making no phones loses €4 million"]},{"id":"2025-P1-Q8:(a)(ii):1","from":"2025-P1-Q8","q":"Profit P(x) = −1.5x² + 10.5x − 4 (millions of euro). Find P(3).","right":"14","wrong":["23","41","47.75"],"why":"P(3) = −1.5(9) + 10.5(3) − 4 = −13.5 + 31.5 − 4 = 14.","hook":"−1.5x² means −1.5 × (x²): square only the x, keep the minus.","keys":["−13.5 + 31.5 − 4 = 14"]},{"id":"2025-P1-Q8:(a)(ii):2","from":"2025-P1-Q8","q":"P(x) = −1.5x² + 10.5x − 4 gives P(0) = −4, P(1) = 5, P(2) = 11, P(3) = 14, P(4) = 14 and P(5) = 11. Without working it out, what is P(6)?","right":"5","wrong":["8","−4","11"],"why":"A quadratic is symmetric about its top. P(3) = P(4), so the mirror line is x = 3.5, and x = 6 mirrors x = 1: P(6) = P(1) = 5.","hook":"Two equal values: the mirror line is halfway between them.","keys":["P(6) = P(1) = 5"]},{"id":"2025-P1-Q8:(a)(iii):1","from":"2025-P1-Q8","q":"The graph of P(x) = −1.5x² + 10.5x − 4 is an upside-down U, with P(3) = P(4) = 14. What are the co-ordinates of its highest point?","right":"(3.5, 14.375)","wrong":["(3.5, 14)","(3, 14)","(14, 3.5)"],"why":"The top is halfway between x = 3 and x = 4, at x = 3.5, and it is above 14: P(3.5) = −18.375 + 36.75 − 4 = 14.375.","hook":"A smooth curve peaks between two equal values, a little higher than both.","keys":["it is above 14"]},{"id":"2025-P1-Q8:(a)(iv):1","from":"2025-P1-Q8","q":"On the graph of profit P(x), the line across from a profit of 6 cuts the curve at x ≈ 1.2 and x ≈ 5.8. For which values of x is the profit at least €6 million?","right":"1.2 ≤ x ≤ 5.8","wrong":["x ≤ 1.2 or x ≥ 5.8","x ≥ 1.2","x = 1.2 or x = 5.8"],"why":"Between the two crossings the curve is on or above the line at 6, so the profit is at least €6 million for 1.2 ≤ x ≤ 5.8.","hook":"'At least' = on or above the line: the x values BETWEEN the crossings.","keys":["Between the two crossings"]},{"id":"2025-P1-Q8:(b)(i):1","from":"2025-P1-Q8","q":"Second-year profit: Q(x) = −1.5x² + 9.6x − 3.5. What is Q′(x)?","right":"−3x + 9.6","wrong":["−3x + 6.1","3x + 9.6","−1.5x + 9.6"],"why":"−1.5x² → 2 × (−1.5)x = −3x, 9.6x → 9.6 and −3.5 → 0.","hook":"Keep the minus: 2 × (−1.5) = −3.","keys":["2 × (−1.5)x = −3x"]},{"id":"2025-P1-Q8:(b)(i):2","from":"2025-P1-Q8","q":"Second-year profit: Q(x) = −1.5x² + 9.6x − 3.5. Find Q′(x), and hence the value of x which gives the maximum value of Q(x).","right":"x = 3.2","wrong":["x = −3.2","x = 6.4","x = 0.39"],"why":"Q′(x) = −3x + 9.6. At the maximum the slope is 0: −3x + 9.6 = 0, so 3x = 9.6 and x = 3.2 (32 000 phones).","hook":"Top of the profit curve = flat tangent: Q′(x) = 0.","keys":["−3x + 9.6 = 0"]},{"id":"2025-P1-Q8:(b)(ii):1","from":"2025-P1-Q8","q":"Q(x) = −1.5x² + 9.6x − 3.5 (millions of euro) is greatest at x = 3.2. Find this maximum value of Q(x).","right":"€11.86 million","wrong":["€0 million","€42.58 million","€22.42 million"],"why":"Put x = 3.2 into Q itself: −1.5(10.24) + 9.6(3.2) − 3.5 = −15.36 + 30.72 − 3.5 = 11.86, so €11.86 million.","hook":"Q′ = 0 finds where the top is; Q gives how high it is.","keys":["Put x = 3.2 into Q itself"]},{"id":"2025-P1-Q8:(c)(i):1","from":"2025-P1-Q8","q":"Third-year profit is R(x) + 3 million euro, where R(x) is read off a graph. How do you find R(2) + 3?","right":"Read R at x = 2, then add 3","wrong":["Read R at x = 5 (2 + 3)","Read R at x = 2, then times by 3","Read x where R = 2, then add 3"],"why":"R(2) is the height of the graph at x = 2 (it reads 8). The + 3 is added after: R(2) + 3 = 8 + 3 = 11.","hook":"R(2) + 3: find R(2) first, then add 3. R(2 + 3) would be R(5).","keys":["R(2) + 3 = 8 + 3 = 11"]},{"id":"2025-P1-Q8:(c)(ii):1","from":"2025-P1-Q8","q":"The graph of R(x) has its top at (3, 9.5). Where is the top of the graph of y = R(x) + 3?","right":"(3, 12.5)","wrong":["(6, 9.5)","(0, 9.5)","(3, 6.5)"],"why":"Adding 3 to every profit moves every point of the graph straight up by 3: the top (3, 9.5) moves to (3, 12.5).","hook":"+3 outside the function moves the graph UP 3, not sideways.","keys":["straight up by 3"]}],"11":[{"id":"2015-P2-Q8:(a)(i):1","from":"2015-P2-Q8","q":"A spherical storage tank has a diameter of 12 m. What is the radius of the tank?","right":"6 m","wrong":["12 m","24 m","3 m"],"why":"The radius goes from the centre to the edge: half the diameter. 12 ÷ 2 = 6 m.","hook":"Diameter goes all the way across; radius is half of it.","keys":["half the diameter"]},{"id":"2015-P2-Q8:(a)(ii):1","from":"2015-P2-Q8","q":"A spherical tank has radius 6 m. What is its volume, correct to the nearest m³?","right":"905 m³","wrong":["7238 m³","679 m³","151 m³"],"why":"V = (4/3)πr³ = (4/3)π(6)³ = 288π = 904.78… ≈ 905 m³.","hook":"Sphere volume: four-thirds pi r cubed. Cube the radius, not the diameter.","keys":["(4/3)πr³"]},{"id":"2015-P2-Q8:(a)(ii):2","from":"2015-P2-Q8","q":"Which formula gives the volume of a sphere of radius r?","right":"V = (4/3)πr³","wrong":["V = 4πr²","V = (2/3)πr³","V = (4/3)πr²"],"why":"Volume is cubic, so r³: V = (4/3)πr³. 4πr² is the surface area and (2/3)πr³ is a hemisphere.","hook":"Volume has r³ (m³); area has r² (m²).","keys":["r³","4πr² is the surface area"]},{"id":"2015-P2-Q8:(b)(i):1","from":"2015-P2-Q8","q":"A spherical tank has radius 6 m. What is its curved surface area, correct to one decimal place?","right":"452.4 m²","wrong":["1809.6 m²","113.1 m²","75.4 m²"],"why":"Curved surface area of a sphere = 4πr² = 4π(6)² = 144π = 452.389… ≈ 452.4 m².","hook":"The skin of a sphere is four circles: 4πr².","keys":["4πr²"]},{"id":"2015-P2-Q8:(b)(ii):1","from":"2015-P2-Q8","q":"A tank has curved surface area 452.4 m² and volume 905 m³. One litre of paint covers 3.5 m². How many litres paint the curved surface, to the nearest litre?","right":"129 litres","wrong":["1583 litres","259 litres","452 litres"],"why":"Paint covers the surface, so use the area: 452.4 ÷ 3.5 = 129.26… ≈ 129 litres.","hook":"Paint goes on the area, not the volume. \"How many fit into\" means divide.","keys":["use the area","452.4 ÷ 3.5"]},{"id":"2015-P2-Q8:(b)(iii):1","from":"2015-P2-Q8","q":"129 litres of paint are needed. Paint is sold in 25 litre tins costing €180 each. What is the total cost of the paint?","right":"€1080","wrong":["€900","€928.80","€23,220"],"why":"129 ÷ 25 = 5.16, and you can’t buy part of a tin, so 6 tins: 6 × €180 = €1080.","hook":"Tins, boxes, buses: always round UP.","keys":["so 6 tins"]},{"id":"2015-P2-Q8:(c)(i):1","from":"2015-P2-Q8","q":"A tank has a hemisphere at each end, each of radius 4.5 m. What is the volume of one hemispherical end, correct to the nearest m³?","right":"191 m³","wrong":["382 m³","95 m³","127 m³"],"why":"A hemisphere is half a sphere: V = (2/3)πr³ = (2/3)π(4.5)³ = 190.85… ≈ 191 m³.","hook":"Hemi = half: half of (4/3)πr³ is (2/3)πr³.","keys":["(2/3)πr³"]},{"id":"2015-P2-Q8:(c)(ii):1","from":"2015-P2-Q8","q":"A tank of volume 905 m³ is a cylinder of length h with a hemisphere (191 m³ each) at each end, all of radius 4.5 m. Which equation finds h?","right":"2(191) + π(4.5)²h = 905","wrong":["191 + π(4.5)²h = 905","2(191) + 2π(4.5)h = 905","2(191) + π(9)²h = 905"],"why":"Parts add up to the total: two hemispheres plus the cylinder’s volume πr²h equals 905.","hook":"Write \"parts = total\" first, then solve for the one letter left.","keys":["two hemispheres","πr²h"]},{"id":"2015-P2-Q8:(c)(ii):2","from":"2015-P2-Q8","q":"A tank of volume 905 m³ is a cylinder of length h m with a 191 m³ hemisphere at each end, all of radius 4.5 m. Find h, correct to one decimal place.","right":"8.2 m","wrong":["11.2 m","14.2 m","2.1 m"],"why":"905 − 2(191) = 523 is the cylinder, so π(4.5)²h = 523 and h = 523 ÷ 63.62 = 8.22… ≈ 8.2 m.","hook":"Take away both ends before dividing by πr².","keys":["905 − 2(191) = 523"]},{"id":"2016-P2-Q7:(a):1","from":"2016-P2-Q7","q":"A billion is a thousand million. Write 165 billion in the form a × 10ⁿ, where 1 ≤ a < 10.","right":"1.65 × 10¹¹","wrong":["1.65 × 10⁹","1.65 × 10⁷","1.65 × 10²⁰"],"why":"A billion = 10³ × 10⁶ = 10⁹, so 165 billion = 165 × 10⁹ = 1.65 × 10² × 10⁹ = 1.65 × 10¹¹.","hook":"Multiplying powers of 10? Add the indices.","keys":["10³ × 10⁶ = 10⁹","1.65 × 10² × 10⁹"]},{"id":"2016-P2-Q7:(b)(i):1","from":"2016-P2-Q7","q":"Each sphere of the Atomium has a diameter of 18 metres. What is the radius of each sphere?","right":"9 m","wrong":["18 m","36 m","4.5 m"],"why":"The radius is half the diameter: 18 ÷ 2 = 9 m.","hook":"Radius = diameter ÷ 2. Halve it before any formula.","keys":["half the diameter"]},{"id":"2016-P2-Q7:(b)(ii):1","from":"2016-P2-Q7","q":"Each sphere of the Atomium has radius 9 m. What is the volume of one sphere, correct to 2 decimal places?","right":"3053.63 m³","wrong":["24,429.02 m³","2290.22 m³","1017.88 m³"],"why":"V = (4/3)πr³ = (4/3)π(9)³ = 972π = 3053.628… ≈ 3053.63 m³.","hook":"Four-thirds pi r cubed: cube first, then × 4 ÷ 3 × π.","keys":["972π"]},{"id":"2016-P2-Q7:(c):1","from":"2016-P2-Q7","q":"The Atomium has 9 identical spheres, each of radius 9 m. What is the combined surface area of the 9 spheres, to the nearest m²?","right":"9161 m²","wrong":["1018 m²","2290 m²","36,644 m²"],"why":"One sphere: 4πr² = 4π(9)² = 324π. Nine spheres: 9 × 324π = 2916π = 9160.88… ≈ 9161 m².","hook":"Find one, then multiply by how many there are.","keys":["9 × 324π = 2916π"]},{"id":"2016-P2-Q7:(d)(i):1","from":"2016-P2-Q7","q":"Which formula gives the curved surface area of a cylinder of radius r and height (length) h?","right":"2πrh","wrong":["πr²h","2πr² + 2πrh","πrh"],"why":"Unrolled, the curved surface is a rectangle: the circumference 2πr by the height h, so 2πrh. πr²h is the volume.","hook":"Peel the label off a can: a rectangle 2πr wide and h tall.","keys":["2πr by the height h"]},{"id":"2016-P2-Q7:(d)(i):2","from":"2016-P2-Q7","q":"Each of 8 cylindrical pipes has radius 1.65 m and length 23 m. What is the sum of the curved surface areas of all 8 pipes, to the nearest m²?","right":"1908 m²","wrong":["2044 m²","954 m²","238 m²"],"why":"One pipe: 2πrh = 2π(1.65)(23) = 75.9π. Eight pipes: 8 × 75.9π = 607.2π = 1907.57… ≈ 1908 m².","hook":"Curved only: no circular ends. Then × 8 for 8 pipes.","keys":["8 × 75.9π = 607.2π"]},{"id":"2016-P2-Q7:(d)(ii):1","from":"2016-P2-Q7","q":"12 equal cylindrical pipes, each of radius 1.45 m, have total curved surface area 3170 m². Which equation gives the length h of one pipe?","right":"12 × 2π(1.45)h = 3170","wrong":["2π(1.45)h = 3170","12 × π(1.45)²h = 3170","12 × π(1.45)h = 3170"],"why":"One pipe has curved area 2πrh = 2π(1.45)h, and 12 of them make 3170 m².","hook":"Area of one × number of pipes = total area.","keys":["2πrh = 2π(1.45)h"]},{"id":"2016-P2-Q7:(d)(ii):2","from":"2016-P2-Q7","q":"12 equal cylindrical pipes, each of radius 1.45 m, have total curved surface area 3170 m². Find the length of one pipe, to the nearest metre.","right":"29 m","wrong":["348 m","40 m","58 m"],"why":"One pipe: 3170 ÷ 12 = 264.17 m². Then 2π(1.45)h = 264.17, so h = 264.17 ÷ 9.11 = 28.997… ≈ 29 m.","hook":"Share the total out first: ÷ 12 gives one pipe.","keys":["3170 ÷ 12 = 264.17"]},{"id":"2016-P2-Q7:(d)(iii):1","from":"2016-P2-Q7","q":"Curved areas: 8 pipes 1908 m², 12 pipes 3170 m², 9 spheres 9161 m². Steel costs €70 per m². What is the cost of steel to cover all of them?","right":"€996,730","wrong":["€774,830","€426,720","€863,170"],"why":"Add every area: 1908 + 3170 + 9161 = 14 239 m². Then × €70: 14 239 × 70 = €996,730.","hook":"Total area first, then × the price per m².","keys":["1908 + 3170 + 9161 = 14 239"]},{"id":"2017-P1-Q5:(a):1","from":"2017-P1-Q5","q":"A field is cut into 8 strips of width 3 m. The heights are 4, 5.8, 7, 6.5, 6, 4.8, 6, 6.5 and 8 m. Use the trapezoidal rule to estimate its area.","right":"145.8 m²","wrong":["81.9 m²","291.6 m²","163.8 m²"],"why":"(3/2)[4 + 8 + 2(5.8 + 7 + 6.5 + 6 + 4.8 + 6 + 6.5)] = 1.5 × [12 + 85.2] = 145.8 m².","hook":"h over 2, times: first + last + twice the rest.","keys":["1.5 × [12 + 85.2]"]},{"id":"2017-P1-Q5:(a):2","from":"2017-P1-Q5","q":"In the trapezoidal rule, which of the heights get doubled?","right":"All except the first and last","wrong":["Only the first and last","All of them","None of them"],"why":"Area ≈ (h/2)[first + last + 2(all the others)]: each middle height is shared by two strips, so it counts twice.","hook":"Ends once, middles twice: the middles are shared by two strips.","keys":["2(all the others)","shared by two strips"]},{"id":"2017-P1-Q5:(b):1","from":"2017-P1-Q5","q":"Strips of width 4 m, heights 4, 6.4, 6.9, 6, x, 6.2, 8 m (the known middle heights add to 25.5). The trapezoidal area is 145.6 m². Which equation finds x?","right":"145.6 = 2[12 + 2(25.5 + x)]","wrong":["145.6 = 2[12 + 25.5 + x]","145.6 = 4[12 + 2(25.5 + x)]","145.6 = 2[2(12) + 2(25.5 + x)]"],"why":"h/2 = 4/2 = 2; first + last = 4 + 8 = 12; x is a middle height, so it is doubled with the others.","hook":"An unknown height goes in the same place a number would.","keys":["h/2 = 4/2 = 2","x is a middle height"]},{"id":"2017-P1-Q5:(b):2","from":"2017-P1-Q5","q":"Strips of width 4 m, heights 4, 6.4, 6.9, 6, x, 6.2, 8 m. The trapezoidal rule gives the area as 145.6 m². What is x?","right":"4.9 m","wrong":["9.8 m","35.3 m","17.65 m"],"why":"145.6 = 2[12 + 2(25.5 + x)] = 2[63 + 2x] = 126 + 4x, so 4x = 19.6 and x = 4.9 m.","hook":"Multiply out the brackets carefully: 2 × 2x = 4x.","keys":["126 + 4x","x = 4.9"]},{"id":"2017-P2-Q4:(a):1","from":"2017-P2-Q4","q":"You are constructing triangle ABC with |AB| = 8 cm, |AC| = 5 cm, |BC| = 7 cm. You have drawn [AB]. What next?","right":"Arcs: 5 cm from A, 7 cm from B","wrong":["Arcs: 7 cm from A, 5 cm from B","A 90° angle at A, then 5 cm up","Arcs of 5 cm and 7 cm, both from A"],"why":"C is 5 cm from A and 7 cm from B, so draw those two arcs; where they cross is C. Leave the arcs showing.","hook":"Three sides given? Ruler for one, compass arcs for the other two.","keys":["where they cross is C"]},{"id":"2017-P2-Q4:(b)(i):1","from":"2017-P2-Q4","q":"A square has side length 2k cm. What is its area, in terms of k?","right":"4k² cm²","wrong":["2k² cm²","8k cm²","4k cm²"],"why":"Area = side × side = (2k)(2k) = 4k²: square the 2 as well as the k.","hook":"(2k)² means 2k × 2k: square the number too.","keys":["square the 2 as well"]},{"id":"2017-P2-Q4:(b)(ii):1","from":"2017-P2-Q4","q":"A right-angled isosceles triangle with two sides of 20 cm has a hypotenuse of 2k cm. Find k, correct to 2 decimal places.","right":"k = 14.14","wrong":["k = 20.00","k = 28.28","k = 3.16"],"why":"Pythagoras: (2k)² = 20² + 20², so 4k² = 800, k² = 200 and k = √200 = 14.14.","hook":"Pythagoras: hyp² = a² + b². Square the WHOLE 2k.","keys":["4k² = 800","k = √200 = 14.14"]},{"id":"2017-P2-Q4:(b)(ii):2","from":"2017-P2-Q4","q":"A square of area 800 cm² has a right-angled triangle with two 20 cm sides cut from one corner. What is the area of the shaded part left?","right":"600 cm²","wrong":["400 cm²","200 cm²","800 cm²"],"why":"Triangle = ½ × 20 × 20 = 200 cm². Shaded part = square − triangle = 800 − 200 = 600 cm².","hook":"Shaded = whole − the bit cut out.","keys":["800 − 200 = 600"]},{"id":"2017-P2-Q7:(a)(i):1","from":"2017-P2-Q7","q":"The height of a cone equals the diameter of its base. The radius of the base is 2.25 m. What is the height of the cone?","right":"4.5 m","wrong":["2.25 m","1.125 m","9 m"],"why":"The diameter is twice the radius: 2 × 2.25 = 4.5 m, and the height equals the diameter.","hook":"Diameter = 2 × radius.","keys":["2 × 2.25 = 4.5"]},{"id":"2017-P2-Q7:(a)(ii):1","from":"2017-P2-Q7","q":"A cone has vertical height 4.5 m and base radius 2.25 m. Which calculation gives its slant height l?","right":"l² = 4.5² + 2.25²","wrong":["l² = 4.5² − 2.25²","l = 4.5 + 2.25","l² = 4.5² + 4.5²"],"why":"Height, radius and slant height make a right-angled triangle with l the hypotenuse: l² = 4.5² + 2.25², l = 5.03 m.","hook":"Slant height is the hypotenuse: l² = h² + r².","keys":["l the hypotenuse"]},{"id":"2017-P2-Q7:(b)(i):1","from":"2017-P2-Q7","q":"Which formula gives the curved surface area of a cone of base radius r?","right":"πrl, with l the slant height","wrong":["πrh, with h the vertical height","πrl + πr²","(1/3)πr²h"],"why":"Curved surface area of a cone = πrl, using the slant height l. Adding πr² gives the total (with the base); (1/3)πr²h is the volume.","hook":"Curved surface: slant height. Volume: vertical height.","keys":["πrl, using the slant height l"]},{"id":"2017-P2-Q7:(b)(i):2","from":"2017-P2-Q7","q":"A sculpture is 14 identical cones, each with base radius 2.25 m, height 4.5 m and slant height 5.03 m. What is their total curved surface area, to 2 decimal places?","right":"497.77 m²","wrong":["445.32 m²","720.43 m²","35.55 m²"],"why":"One cone: πrl = π(2.25)(5.03) = 35.55… m². Fourteen cones: 14 × 35.55… = 497.77 m².","hook":"Cone skin: πrl, with the slant height l.","keys":["πrl = π(2.25)(5.03)"]},{"id":"2017-P2-Q7:(b)(ii):1","from":"2017-P2-Q7","q":"A sculpture has curved surface area 497.77 m². One litre of polish covers 12.25 m². How many litres are needed, to the nearest litre?","right":"41 litres","wrong":["40 litres","6098 litres","3 litres"],"why":"497.77 ÷ 12.25 = 40.63…, which is 41 litres to the nearest litre.","hook":"Coverage: area ÷ (m² per litre).","keys":["497.77 ÷ 12.25 = 40.63"]},{"id":"2017-P2-Q7:(b)(iii):1","from":"2017-P2-Q7","q":"41 litres of polish are needed. A 5 litre container costs 110 Australian dollars (AUD), and AUD 1 = €0.68. What is the cost of the polish, to the nearest euro?","right":"€673","wrong":["€598","€1456","€613"],"why":"41 ÷ 5 = 8.2, so buy 9 containers: 9 × AUD 110 = AUD 990, and 990 × 0.68 = €673.20 ≈ €673.","hook":"Round containers UP; to change AUD to €, multiply by the rate.","keys":["buy 9 containers","990 × 0.68"]},{"id":"2017-P2-Q7:(c)(i):1","from":"2017-P2-Q7","q":"The net of a cone’s curved surface is a sector. When the net is rolled up into the cone, the arc of the sector becomes…","right":"the circumference of the base","wrong":["the slant height","the radius of the base","the height of the cone"],"why":"The arc wraps once round the bottom of the cone, so the arc length is the circumference of the base: p = 2πr.","hook":"Roll the sector up: its arc runs round the base.","keys":["circumference of the base"]},{"id":"2017-P2-Q7:(c)(i):2","from":"2017-P2-Q7","q":"A cone has base radius 2.25 m and slant height 5.03 m. Its net is a sector of radius 5.03 m. Find the arc length p of the sector, to 2 decimal places.","right":"14.14 m","wrong":["31.60 m","7.07 m","15.90 m"],"why":"The arc wraps round the base of the cone, so p = 2πr = 2π(2.25) = 14.137… ≈ 14.14 m.","hook":"Arc of the net = circumference of the cone’s base.","keys":["p = 2πr = 2π(2.25)"]},{"id":"2017-P2-Q7:(c)(ii):1","from":"2017-P2-Q7","q":"A sector of radius 5.03 m has arc length 14.14 m. Find θ, the angle at the centre, to the nearest degree.","right":"161°","wrong":["64°","322°","199°"],"why":"(θ/360) × 2π(5.03) = 14.14, so θ = 14.14 × 360 ÷ 31.605… = 161.07… ≈ 161°.","hook":"Arc = (θ/360) × 2πr: the slice of the whole circumference.","keys":["(θ/360) × 2π(5.03) = 14.14"]},{"id":"2018-P2-Q5:(a):1","from":"2018-P2-Q5","q":"Square ABCD has sides of 7 cm. Tilted square PQRS has its corners on the sides of ABCD, with Q on [AB] and |AQ| = 5 cm. What is the area of PQRS?","right":"29 cm²","wrong":["9 cm²","25 cm²","5.39 cm²"],"why":"Each corner triangle has sides 5 and 2, area ½(5)(2) = 5. PQRS = 49 − 4(5) = 29 cm². (Or |PQ|² = 5² + 2² = 29.)","hook":"Tilted square = big square − 4 corner triangles.","keys":["49 − 4(5) = 29"]},{"id":"2018-P2-Q5:(a):2","from":"2018-P2-Q5","q":"Square ABCD has sides of 7 cm; Q on [AB] with |AQ| = 5 cm, so the corner triangle has sides 5 cm and 2 cm. What is the side |PQ| of the tilted square?","right":"√29 cm","wrong":["√21 cm","7 cm","√74 cm"],"why":"|PQ| is the hypotenuse of the corner triangle: |PQ|² = 5² + 2² = 29, so |PQ| = √29 cm.","hook":"Hypotenuse² = sum of the squares of the other two sides.","keys":["|PQ|² = 5² + 2² = 29"]},{"id":"2018-P2-Q5:(b)(i):1","from":"2018-P2-Q5","q":"Wheel u has radius 4 cm and wheel v has radius 6 cm. What are their circumferences, in terms of π?","right":"u: 8π cm, v: 12π cm","wrong":["u: 16π cm, v: 36π cm","u: 4π cm, v: 6π cm","u: 16π cm, v: 24π cm"],"why":"Circumference = 2πr: u = 2π(4) = 8π cm and v = 2π(6) = 12π cm.","hook":"Circumference 2πr (a length, cm); area πr² (cm²).","keys":["Circumference = 2πr"]},{"id":"2018-P2-Q5:(b)(ii):1","from":"2018-P2-Q5","q":"Two wheels are in non-slip contact, so turning one turns the other. What is the same for both wheels?","right":"The distance moved by each rim","wrong":["The number of rotations","The angle each wheel turns","The time for one rotation"],"why":"The rims grip each other, so each moves the same distance. A smaller wheel has a shorter circumference, so it turns more times.","hook":"Non-slip: same rim distance, so the small wheel spins more.","keys":["each moves the same distance"]},{"id":"2018-P2-Q5:(b)(ii):2","from":"2018-P2-Q5","q":"Wheel u (circumference 8π cm) and wheel v (circumference 12π cm) are in non-slip contact. Wheel v makes 100 rotations. How many rotations does u make?","right":"150 rotations","wrong":["66 rotations","100 rotations","225 rotations"],"why":"v’s rim moves 100 × 12π = 1200π cm. u’s rim moves the same, so u turns 1200π ÷ 8π = 150 times.","hook":"Distance ÷ circumference = number of turns.","keys":["1200π ÷ 8π = 150"]},{"id":"2018-P2-Q9:(a)(i):1","from":"2018-P2-Q9","q":"What is the volume of a solid sphere of radius 0.3 cm, in cm³, correct to 3 decimal places?","right":"0.113 cm³","wrong":["0.085 cm³","1.131 cm³","0.377 cm³"],"why":"V = (4/3)πr³ = (4/3)π(0.3)³ = (4/3)π(0.027) = 0.113097… ≈ 0.113 cm³.","hook":"Sphere: (4/3)πr³. Cube small decimals carefully: 0.3³ = 0.027.","keys":["(4/3)π(0.027)"]},{"id":"2018-P2-Q9:(a)(ii):1","from":"2018-P2-Q9","q":"A gold sphere has volume 0.113 cm³. Each cm³ of gold weighs 19.3 g. How many grams of gold are in the sphere, to 2 decimal places?","right":"2.18 g","wrong":["0.01 g","170.80 g","2.12 g"],"why":"Every cm³ weighs 19.3 g, so multiply: 0.113 × 19.3 = 2.1809 ≈ 2.18 g. (Rounding 0.113 to 0.11 first gives 2.12.)","hook":"Grams per cm³ × cm³ = grams. Round only at the end.","keys":["0.113 × 19.3 = 2.1809"]},{"id":"2018-P2-Q9:(a)(iii):1","from":"2018-P2-Q9","q":"There are about 6.02 × 10²³ atoms in 197 g of gold. How many atoms are in 2.18 g of gold? (a to 2 significant figures)","right":"6.7 × 10²¹","wrong":["1.3 × 10²⁴","3.1 × 10²¹","5.4 × 10²⁵"],"why":"Atoms in 1 g: 6.02 × 10²³ ÷ 197. In 2.18 g: (6.02 × 10²³ ÷ 197) × 2.18 = 6.66… × 10²¹ ≈ 6.7 × 10²¹.","hook":"Go through 1: divide to get one gram, then multiply up.","keys":["(6.02 × 10²³ ÷ 197) × 2.18"]},{"id":"2019-P1-Q5:(a):1","from":"2019-P1-Q5","q":"A scale diagram (1 cm = 3 m) of a lawn is cut into 8 strips each 1 cm wide. Heights: 0, 5, 6, 5, 4, 5, 6, 5, 0 cm. Use the trapezoidal rule to estimate the real area.","right":"324 m²","wrong":["108 m²","162 m²","648 m²"],"why":"In metres: h = 3, heights 0, 15, 18, 15, 12, 15, 18, 15, 0. Area ≈ (3/2)[0 + 0 + 2(108)] = 1.5 × 216 = 324 m².","hook":"Change every length to real metres first, then use the rule.","keys":["(3/2)[0 + 0 + 2(108)]"]},{"id":"2019-P1-Q5:(a):2","from":"2019-P1-Q5","q":"On a scale diagram, 1 cm = 3 m. Each grid box is 0.5 cm tall. A vertical line is 10 boxes tall. What real length does it show?","right":"15 m","wrong":["30 m","5 m","1.67 m"],"why":"10 boxes × 0.5 cm = 5 cm on the diagram, and each cm is 3 m, so 5 × 3 = 15 m.","hook":"Boxes → cm → metres: one step at a time.","keys":["10 boxes × 0.5 cm = 5 cm","5 × 3 = 15 m"]},{"id":"2019-P1-Q5:(b):1","from":"2019-P1-Q5","q":"Nuala walks at a speed of 1.6 metres per second. What is this speed in kilometres per hour?","right":"5.76 km/h","wrong":["0.44 km/h","5760 km/h","0.096 km/h"],"why":"In an hour (3600 s) she walks 1.6 × 3600 = 5760 m, and 5760 ÷ 1000 = 5.76 km. So 5.76 km/h.","hook":"m/s to km/h: × 3600 ÷ 1000, which is × 3.6.","keys":["1.6 × 3600 = 5760 m","5760 ÷ 1000 = 5.76"]},{"id":"2019-P2-Q5:(a):1","from":"2019-P2-Q5","q":"A crescent is made by removing a disc of radius 2.5 cm from a disc of radius 3 cm. What is the area of the crescent, to 2 decimal places?","right":"8.64 cm²","wrong":["0.79 cm²","47.91 cm²","3.14 cm²"],"why":"Area = big disc − small disc = π(3)² − π(2.5)² = 9π − 6.25π = 2.75π = 8.639… ≈ 8.64 cm².","hook":"Shape with a hole: area of the whole − area of the hole.","keys":["9π − 6.25π = 2.75π"]},{"id":"2019-P2-Q5:(a):2","from":"2019-P2-Q5","q":"A crescent is made by removing a disc of radius 2.5 cm from a disc of radius 3 cm. What is the perimeter of the crescent, to 2 decimal places?","right":"34.56 cm","wrong":["3.14 cm","18.85 cm","17.28 cm"],"why":"The edge runs round the outer circle and back round the inner one, so add: 2π(3) + 2π(2.5) = 11π = 34.557… ≈ 34.56 cm.","hook":"Perimeter: trace the whole edge. Both curves count, so add them.","keys":["2π(3) + 2π(2.5) = 11π"]},{"id":"2019-P2-Q5:(b):1","from":"2019-P2-Q5","q":"An inverted cone has vertical height 12 cm and radius 7 cm. What is its volume, to 2 decimal places?","right":"615.75 cm³","wrong":["1847.26 cm³","2463.01 cm³","87.96 cm³"],"why":"V = (1/3)πr²h = (1/3)π(7)²(12) = 196π = 615.75 cm³.","hook":"A cone is one third of the cylinder around it: (1/3)πr²h.","keys":["(1/3)π(7)²(12) = 196π"]},{"id":"2019-P2-Q5:(b):2","from":"2019-P2-Q5","q":"A cone of volume 615.75 cm³ is filled by a pipe at 0.5 litres per minute (1 litre = 1000 cm³). How long does it take, to the nearest second?","right":"74 seconds","wrong":["222 seconds","739 seconds","83 seconds"],"why":"0.5 litres = 500 cm³ a minute. 615.75 ÷ 500 = 1.2315 minutes, and 1.2315 × 60 = 73.89 ≈ 74 seconds.","hook":"Litres → cm³: × 1000. Decimal minutes → seconds: × 60.","keys":["0.5 litres = 500 cm³","1.2315 × 60 = 73.89"]},{"id":"2019-P2-Q8:(a)(i):1","from":"2019-P2-Q8","q":"What is the volume of a solid sphere of radius 3 cm, in terms of π?","right":"36π cm³","wrong":["27π cm³","12π cm³","288π cm³"],"why":"V = (4/3)πr³ = (4/3)π(3)³ = (4/3) × 27 × π = 36π cm³.","hook":"“In terms of π”: work out the number, leave π as it is.","keys":["(4/3) × 27 × π = 36π"]},{"id":"2019-P2-Q8:(a)(ii):1","from":"2019-P2-Q8","q":"A sphere of volume 36π cm³ is taken out of a full cylinder of water with internal radius 5 cm. Which equation gives the drop h in the water level?","right":"π(5)²h = 36π","wrong":["π(3)²h = 36π","2π(5)h = 36π","π(5)²h = (4/3)π(5)³"],"why":"The lost water is a short cylinder of radius 5 and height h, with the same volume as the sphere: π(5)²h = 36π.","hook":"Volume out = volume of the sphere. The water is a cylinder: πr²h.","keys":["π(5)²h = 36π"]},{"id":"2019-P2-Q8:(a)(ii):2","from":"2019-P2-Q8","q":"A sphere of volume 36π cm³ is taken out of a full cylinder of water with internal radius 5 cm. By how much does the water level drop?","right":"1.44 cm","wrong":["7.2 cm","0.36 cm","4.52 cm"],"why":"π(5)²h = 36π, so 25πh = 36π and h = 36π ÷ 25π = 36 ÷ 25 = 1.44 cm (the π’s cancel).","hook":"Divide by the whole πr² — the π’s cancel.","keys":["h = 36π ÷ 25π = 36 ÷ 25 = 1.44"]},{"id":"2019-P2-Q8:(a)(iii):1","from":"2019-P2-Q8","q":"A cylinder has radius 5 cm and height 18 cm. Its curved surface is cut from a 35 cm by 20 cm sheet of metal. How much metal is left over, to 1 decimal place?","right":"134.5 cm²","wrong":["565.5 cm²","417.3 cm²","71.7 cm²"],"why":"Curved surface = 2πrh = 2π(5)(18) = 180π = 565.49 cm². Sheet = 35 × 20 = 700 cm². Left over = 700 − 565.49 ≈ 134.5 cm².","hook":"Left over = whole sheet − the piece cut out.","keys":["700 − 565.49"]},{"id":"2020-P2-Q9:(a)(i):1","from":"2020-P2-Q9","q":"A can’s net is cut from a sheet 16 cm tall: the side is a 10 cm tall rectangle, with the circular top (radius r) standing on it. What is r?","right":"3 cm","wrong":["6 cm","8 cm","5 cm"],"why":"The sheet’s height is 10 + one diameter = 16, so the diameter is 6 cm and the radius r = 6 ÷ 2 = 3 cm.","hook":"A circle stands one diameter tall: halve it for the radius.","keys":["10 + one diameter = 16"]},{"id":"2020-P2-Q9:(a)(ii):1","from":"2020-P2-Q9","q":"A can of radius 3 cm is made from a net. Its side is a rectangle of length y that wraps once round the can. Find y, to the nearest cm.","right":"19 cm","wrong":["12 cm","28 cm","38 cm"],"why":"The side wraps once round the circle, so y is the circumference: y = 2πr = 2π(3) = 6π = 18.85… ≈ 19 cm.","hook":"Wrap the side round the lid: its length = circumference 2πr.","keys":["y = 2πr = 2π(3) = 6π"]},{"id":"2020-P2-Q9:(a)(iii):1","from":"2020-P2-Q9","q":"A 6π cm by 16 cm sheet gives a can’s side (6π by 10 cm) and its top and bottom (circles of radius 3 cm). What area is wasted, to the nearest cm²?","right":"57 cm²","wrong":["85 cm²","75 cm²","245 cm²"],"why":"Sheet 96π − side 60π − two circles 2π(3)² = 18π. Waste = 96π − 78π = 18π = 56.55 ≈ 57 cm².","hook":"Waste = sheet − every piece used (side, top AND bottom).","keys":["96π − 78π = 18π"]},{"id":"2020-P2-Q9:(b)(i):1","from":"2020-P2-Q9","q":"What is the volume of a spherical ice cube of radius 1.5 cm, in terms of π?","right":"4.5π cm³","wrong":["3.375π cm³","3π cm³","36π cm³"],"why":"V = (4/3)πr³ = (4/3)π(1.5)³ = (4/3) × 3.375 × π = 4.5π cm³ (= 9π/2).","hook":"Sphere: (4/3)πr³. Cube first: 1.5³ = 3.375.","keys":["(4/3) × 3.375 × π = 4.5π"]},{"id":"2020-P2-Q9:(b)(ii):1","from":"2020-P2-Q9","q":"Ice cubes are held fully under the water in a cylinder, and the level rises by h. The volume of the risen layer of water (a cylinder of height h) equals…","right":"the volume of all the ice cubes","wrong":["the volume of one ice cube","the surface area of the ice cubes","the volume of the water"],"why":"The ice pushes up exactly its own volume of water, so π(3.5)²h = the total volume of the ice cubes put in.","hook":"Volume in = volume of the rise.","keys":["its own volume of water"]},{"id":"2020-P2-Q9:(b)(ii):2","from":"2020-P2-Q9","q":"Three ice spheres, each 4.5π cm³, are fully submerged in a cylinder of water of internal radius 3.5 cm. Find the rise h in the water level, to 1 decimal place.","right":"1.1 cm","wrong":["0.4 cm","3.9 cm","0.3 cm"],"why":"π(3.5)²h = 3 × 4.5π = 13.5π, so h = 13.5 ÷ 12.25 = 1.102… ≈ 1.1 cm.","hook":"Count every sphere, then divide by r² (the π’s cancel).","keys":["π(3.5)²h = 3 × 4.5π = 13.5π"]},{"id":"2021-P2-Q8:(a)(i):1","from":"2021-P2-Q8","q":"Across a lake, every 10 m along [PQ], the offsets above + below the line are: 0+10, 20+20, 10+20, 30+20, 30+10, 20+20, 0. Estimate the lake’s area (trapezoidal rule).","right":"2050 m²","wrong":["1050 m²","4100 m²","1100 m²"],"why":"Widths: 10, 40, 30, 50, 40, 40, 0. Area ≈ (10/2)[10 + 0 + 2(40 + 30 + 50 + 40 + 40)] = 5 × 410 = 2050 m².","hook":"Add the offsets above and below first: that is the width.","keys":["5 × 410 = 2050"]},{"id":"2021-P2-Q8:(a)(ii):1","from":"2021-P2-Q8","q":"A lake has a surface area of 2050 m² and is, on average, 8 m deep. Estimate the volume of water in the lake.","right":"16,400 m³","wrong":["256.25 m³","8200 m³","5466.67 m³"],"why":"Treat the lake as a slab: area × average depth = 2050 × 8 = 16 400 m³. The average depth already allows for the sloping bed.","hook":"Volume of a slab = area of the top × depth.","keys":["2050 × 8 = 16 400"]},{"id":"2021-P2-Q8:(b)(i):1","from":"2021-P2-Q8","q":"What is the volume of a hemisphere of radius 21 cm, in terms of π?","right":"6174π cm³","wrong":["12,348π cm³","882π cm³","3087π cm³"],"why":"V = (2/3)πr³ = (2/3)π(21)³ = (2/3) × 9261 × π = 6174π cm³.","hook":"Hemisphere = half a sphere: (2/3)πr³.","keys":["(2/3) × 9261 × π = 6174π"]},{"id":"2021-P2-Q8:(b)(ii):1","from":"2021-P2-Q8","q":"A buoy is a cone standing on a hemisphere, both of radius 21 cm. The total height of the buoy is the height of the cone plus…","right":"the radius of the hemisphere","wrong":["the diameter of the hemisphere","the slant height of the cone","nothing more"],"why":"The hemisphere hangs below the cone, and its depth is its radius, 21 cm. So total height = cone height + 21.","hook":"A hemisphere is as deep as its radius.","keys":["its depth is its radius"]},{"id":"2021-P2-Q8:(b)(ii):2","from":"2021-P2-Q8","q":"A buoy is a cone on a hemisphere, both radius 21 cm. The cone’s volume equals the hemisphere’s, 6174π cm³. What is the total height of the buoy?","right":"63 cm","wrong":["42 cm","35 cm","84 cm"],"why":"(1/3)π(21)²h = 6174π, so 147h = 6174 and the cone’s height is 42 cm. Add the hemisphere’s depth: 42 + 21 = 63 cm.","hook":"Solve for the cone’s height, then add the hemisphere’s radius.","keys":["147h = 6174","42 + 21 = 63"]},{"id":"2021-P2-Q8:(c):1","from":"2021-P2-Q8","q":"In triangle PBQ, |PB| = 43 m, |BQ| = 26 m and |PQ| = 60 m. Which rule finds the angle QBP?","right":"The cosine rule","wrong":["The sine rule","Pythagoras’ theorem","Area = ½ab sin C"],"why":"All three sides are known and no angle, so use the cosine rule: 60² = 26² + 43² − 2(26)(43)cos B.","hook":"Three sides, no angle? Cosine rule.","keys":["use the cosine rule"]},{"id":"2021-P2-Q8:(c):2","from":"2021-P2-Q8","q":"In triangle PBQ, |PB| = 43 m, |BQ| = 26 m and |PQ| = 60 m. Find the angle QBP, correct to two decimal places.","right":"118.74°","wrong":["61.26°","38.93°","2.07°"],"why":"cos B = (26² + 43² − 60²) ÷ (2 × 26 × 43) = −1075 ÷ 2236 = −0.4807…, so B = 118.74° (obtuse, as cos B is negative).","hook":"Angle opposite the longest side; a minus cos means over 90°.","keys":["−1075 ÷ 2236 = −0.4807"]},{"id":"2022-P2-Q8:(a)(i):1","from":"2022-P2-Q8","q":"The top of a lighthouse is a hemisphere of radius 3 m. What is the volume of the hemisphere, in terms of π?","right":"18π m³","wrong":["36π m³","9π m³","6π m³"],"why":"V = (2/3)πr³ = (2/3)π(3)³ = (2/3) × 27 × π = 18π m³.","hook":"Hemisphere: half of (4/3)πr³ is (2/3)πr³.","keys":["(2/3) × 27 × π = 18π"]},{"id":"2022-P2-Q8:(a)(ii):1","from":"2022-P2-Q8","q":"A cylinder of radius 3 m has volume 36π m³. What is its height h?","right":"4 m","wrong":["12 m","6 m","1 m"],"why":"πr²h = 36π, so π(3)²h = 36π, 9πh = 36π and h = 36π ÷ 9π = 4 m.","hook":"Volume ÷ (area of the circular end) = height.","keys":["9πh = 36π"]},{"id":"2022-P2-Q8:(b)(i):1","from":"2022-P2-Q8","q":"A cone has base radius 7.5 m and vertical height 47 m. Find the angle A between its slanting side and its base, to the nearest degree.","right":"81°","wrong":["9°","72°","85°"],"why":"Cut the cone in half: a right-angled triangle with 47 opposite A and 7.5 next to it. tan A = 47 ÷ 7.5, so A = 80.93… ≈ 81°.","hook":"Height is opposite the base angle; the radius is adjacent. TOA.","keys":["tan A = 47 ÷ 7.5"]},{"id":"2022-P2-Q8:(b)(ii):1","from":"2022-P2-Q8","q":"A cone of radius 7.5 m and height 47 m has its top cut off at a level circle of radius 3 m. What is the height k of the part left?","right":"28.2 m","wrong":["18.8 m","46.5 m","42.5 m"],"why":"The removed top is a similar cone: x/47 = 3/7.5, so x = 18.8 m. What is left: k = 47 − 18.8 = 28.2 m.","hook":"Similar cones: match radius to radius and height to height.","keys":["x/47 = 3/7.5","k = 47 − 18.8 = 28.2"]},{"id":"2022-P2-Q8:(c)(i):1","from":"2022-P2-Q8","q":"A lighthouse can be seen from anywhere within a circle of radius 50 km. What is the area of the circle, to the nearest km²?","right":"7854 km²","wrong":["314 km²","31,416 km²","2500 km²"],"why":"Area = πr² = π(50)² = 2500π = 7853.98… ≈ 7854 km².","hook":"Area of a circle: πr². 2πr is the distance round it.","keys":["π(50)² = 2500π"]},{"id":"2022-P2-Q8:(c)(ii):1","from":"2022-P2-Q8","q":"50 km = 27 nautical miles. How many km are in 1 nautical mile, correct to 4 significant figures?","right":"1.852 km","wrong":["0.5400 km","1.851 km","1.85 km"],"why":"27 nautical miles = 50 km, so 1 nautical mile = 50 ÷ 27 = 1.85185… ≈ 1.852 km (the 5th figure, 8, rounds the 1 up).","hook":"Unitary method: divide to get ONE, then multiply.","keys":["50 ÷ 27 = 1.85185"]},{"id":"2022-P2-Q8:(d):1","from":"2022-P2-Q8","q":"The top of a lighthouse is 49 m above sea level. From a ship, its angle of elevation is 1.2°. Which equation gives the horizontal distance d?","right":"tan 1.2° = 49/d","wrong":["tan 1.2° = d/49","cos 1.2° = 49/d","sin 1.2° = d/49"],"why":"The 49 m height is opposite the 1.2° angle and d is adjacent to it, so tan 1.2° = 49/d.","hook":"Opposite and adjacent? Tan (TOA).","keys":["tan 1.2° = 49/d"]},{"id":"2022-P2-Q8:(d):2","from":"2022-P2-Q8","q":"The top of a lighthouse is 49 m above sea level. From a ship, its angle of elevation is 1.2°. Find the horizontal distance d, in km to 2 decimal places.","right":"2.34 km","wrong":["23.39 km","2339.24 km","0.02 km"],"why":"d = 49 ÷ tan 1.2° = 2339.2… m, and ÷ 1000 gives 2.34 km. (Calculator in degree mode.)","hook":"Metres to km: ÷ 1000. Check DEG mode on the calculator.","keys":["d = 49 ÷ tan 1.2° = 2339.2"]},{"id":"2022-P2-Q9:(a):1","from":"2022-P2-Q9","q":"A shed is 8.5 m high at its highest point. Which is most likely true, with a height for Seán to back it up?","right":"5 times as high: Seán about 1.7 m","wrong":["3 times as high: Seán about 2.8 m","8 times as high: Seán about 1.1 m","5 times as high: Seán about 42.5 m"],"why":"Divide the shed’s height by each number: 8.5 ÷ 5 = 1.7 m, a normal adult height. 8.5 ÷ 3 = 2.8 m is too tall; 8.5 ÷ 8 = 1.06 m is a small child.","hook":"Test each claim: divide, then ask \"is that a real person?\"","keys":["8.5 ÷ 5 = 1.7 m"]},{"id":"2022-P2-Q9:(b):1","from":"2022-P2-Q9","q":"A shed is a prism 18 m long. Its front is a 12 m wide, 7 m high rectangle with a triangular roof on top, 8.5 m high at its peak. What is its volume?","right":"1674 m³","wrong":["2430 m³","1836 m³","1512 m³"],"why":"Front = rectangle 12 × 7 = 84 + triangle ½(12)(1.5) = 9, so 93 m². Volume = 93 × 18 = 1674 m³.","hook":"Prism: area of the front face × length. Roof height = 8.5 − 7.","keys":["½(12)(1.5) = 9","93 × 18 = 1674"]},{"id":"2022-P2-Q9:(b):2","from":"2022-P2-Q9","q":"A shed has a volume of 1674 m³, and 1 m³ = 1000 litres. What is its capacity in litres?","right":"1,674,000 litres","wrong":["1.674 litres","167,400 litres","1674 litres"],"why":"Each m³ holds 1000 litres, so multiply: 1674 × 1000 = 1 674 000 litres, which is over one million.","hook":"m³ to litres: × 1000 (a cubic metre is a big box).","keys":["1674 × 1000 = 1 674 000"]},{"id":"2022-P2-Q9:(c):1","from":"2022-P2-Q9","q":"A roof is 12 m wide and rises from 7 m to 8.5 m, with its peak above the centre. Find its slant length d, to 1 decimal place.","right":"6.2 m","wrong":["12.1 m","10.4 m","5.8 m"],"why":"Half the roof is a right-angled triangle: across 12 ÷ 2 = 6, up 8.5 − 7 = 1.5. d² = 6² + 1.5² = 38.25, so d = 6.18… ≈ 6.2 m.","hook":"Draw the right-angled triangle first: half the width, the rise.","keys":["d² = 6² + 1.5² = 38.25"]},{"id":"2022-P2-Q9:(d):1","from":"2022-P2-Q9","q":"To enlarge a shape with centre A and scale factor 3, you draw a ray from A through each corner. Where does each image corner go?","right":"On the ray, 3 times as far from A","wrong":["On the ray, 3 cm further out","On the ray, ⅓ as far from A","On the ray, 4 times as far from A"],"why":"Scale factor 3: measure from A to the corner, multiply by 3, and mark the image point that far from A on the same ray.","hook":"Always measure from the centre of enlargement.","keys":["multiply by 3"]},{"id":"2022-P2-Q9:(e)(i):1","from":"2022-P2-Q9","q":"In triangle ABC, |AB| = 3 m, |AC| = 7 m and the angle at A is 30°. Which gives |BC|²?","right":"3² + 7² − 2(3)(7)cos 30°","wrong":["3² + 7²","3² + 7² + 2(3)(7)cos 30°","7² − 3²"],"why":"Two sides and the angle between them: cosine rule. |BC|² = 3² + 7² − 2(3)(7)cos 30° = 21.627, so |BC| = 4.65 m.","hook":"Two sides and the angle between: cosine rule (it isn’t right-angled).","keys":["Two sides and the angle between them"]},{"id":"2022-P2-Q9:(e)(ii):1","from":"2022-P2-Q9","q":"In triangle ABC, |AB| = 3 m, |AC| = 7 m, |BC| = 4.65 m and the angle at A is 30°. Find the angle ACB, to the nearest degree.","right":"19°","wrong":["49°","51°","131°"],"why":"Angle C is opposite the 3 m side: sin C / 3 = sin 30° / 4.65, so sin C = 0.3225… and C = 18.8… ≈ 19°.","hook":"Sine rule: pair each angle with the side opposite it.","keys":["sin C / 3 = sin 30° / 4.65"]},{"id":"2023-P1-Q8:(a):1","from":"2023-P1-Q8","q":"A rectangular garden measures 50 m by 30 m. What is the area of the whole garden?","right":"1500 m²","wrong":["160 m²","750 m²","80 m²"],"why":"Area of a rectangle = length × width = 50 × 30 = 1500 m².","hook":"Area: multiply. Perimeter: add all the way round.","keys":["50 × 30 = 1500"]},{"id":"2023-P1-Q8:(b):1","from":"2023-P1-Q8","q":"A pond is 18 m long. Its widths every 3 m are 0, 10, 14, 12, 10, 8 and 2 m. Use the trapezoidal rule to estimate the area of the pond.","right":"165 m²","wrong":["84 m²","330 m²","168 m²"],"why":"(3/2)[0 + 2 + 2(10 + 14 + 12 + 10 + 8)] = 1.5 × [2 + 108] = 1.5 × 110 = 165 m².","hook":"h/2 × [first + last + 2 × (all the middle ones)].","keys":["1.5 × [2 + 108]"]},{"id":"2023-P1-Q8:(c):1","from":"2023-P1-Q8","q":"How could the trapezoidal rule (with different measurements) give a more accurate estimate of the area of a pond?","right":"Measure the widths at smaller intervals","wrong":["Measure the widths at larger intervals","Double the first and last widths too","Round each width to the nearest 5 m"],"why":"Each strip is treated as a straight-sided trapezium. Thinner strips (more measurements) follow the curved edge more closely.","hook":"More, thinner strips hug the curve better.","keys":["Thinner strips"]},{"id":"2023-P1-Q8:(d):1","from":"2023-P1-Q8","q":"A 1500 m² garden has a pond of actual area 172 m² (estimated 165 m²). The rest is grass, resown at €2.55 per m². What is the cost, to the nearest ten euro?","right":"€3390","wrong":["€3400","€3830","€3380"],"why":"Grass = 1500 − 172 = 1328 m² (use the actual area). 1328 × 2.55 = €3386.40, which is €3390 to the nearest ten euro.","hook":"Grass = garden − pond. Nearest ten: look at the units digit.","keys":["1500 − 172 = 1328","1328 × 2.55 = €3386.40"]},{"id":"2023-P1-Q8:(e):1","from":"2023-P1-Q8","q":"Materials cost £840, which includes an import duty of 16.9%. £840 is what percentage of the price before duty?","right":"116.9%","wrong":["100%","83.1%","16.9%"],"why":"The price before duty is 100%. Adding 16.9% duty makes it 116.9%, so £840 = 116.9%.","hook":"Price with the tax added = 100% + the tax %.","keys":["£840 = 116.9%"]},{"id":"2023-P1-Q8:(e):2","from":"2023-P1-Q8","q":"Materials cost £840, which includes an import duty of 16.9%. What was the cost before the duty was added, to the nearest penny?","right":"£718.56","wrong":["£698.04","£981.96","£1010.83"],"why":"£840 is 116.9% of the original, so 1% = 840 ÷ 116.9 and 100% = 840 ÷ 116.9 × 100 = £718.56.","hook":"Going back: divide by 1.169. Don’t take 16.9% off £840.","keys":["840 ÷ 116.9 × 100 = £718.56"]},{"id":"2023-P1-Q8:(f):1","from":"2023-P1-Q8","q":"A bill of £840 is paid in euro, at €1 = £0.8547, plus a commission of 2.5% of the £840. What is the total paid in euro, to the nearest cent?","right":"€1007.37","wrong":["€735.90","€982.81","€958.23"],"why":"With commission: 840 × 1.025 = £861. In euro: £861 ÷ 0.8547 = €1007.37 (each €1 buys only £0.8547).","hook":"€1 = £0.8547: pounds to euro, divide by 0.8547.","keys":["840 × 1.025 = £861","£861 ÷ 0.8547 = €1007.37"]},{"id":"2023-P2-Q5:(a):1","from":"2023-P2-Q5","q":"A square has sides of 12 cm. Circle c is inside the square and touches all four sides. What is the radius of c?","right":"6 cm","wrong":["12 cm","8.49 cm","3 cm"],"why":"c touches opposite sides, so its diameter is the side of the square, 12 cm. Radius = 12 ÷ 2 = 6 cm.","hook":"A circle that fits snugly in a square: diameter = side.","keys":["its diameter is the side of the square"]},{"id":"2023-P2-Q5:(b):1","from":"2023-P2-Q5","q":"A circle has radius 6 cm. What is its area, correct to 2 decimal places?","right":"113.10 cm²","wrong":["37.70 cm²","452.39 cm²","36.00 cm²"],"why":"Area = πr² = π(6)² = 36π = 113.097… ≈ 113.10 cm².","hook":"Area πr² (square the radius); 2πr is the circumference.","keys":["π(6)² = 36π"]},{"id":"2023-P2-Q5:(c):1","from":"2023-P2-Q5","q":"A circle of area 113.10 cm² fits inside a square of side 12 cm. What percentage of the square’s area does the circle take up, to the nearest percent?","right":"79%","wrong":["127%","21%","78%"],"why":"Square = 12 × 12 = 144 cm². Part ÷ whole × 100: 113.10 ÷ 144 × 100 = 78.54…% ≈ 79%.","hook":"Percentage = part ÷ whole × 100. The whole goes underneath.","keys":["113.10 ÷ 144 × 100 = 78.54"]},{"id":"2023-P2-Q5:(d):1","from":"2023-P2-Q5","q":"Circle k goes through the four corners of a square of side 12 cm, and has the same centre. Which calculation gives the radius of k?","right":"r = √(6² + 6²)","wrong":["r = √(12² + 12²)","r = √(12² − 6²)","r = 12 ÷ 2"],"why":"Centre to corner: across 6 and up 6, so r² = 6² + 6² = 72 and r = √72 = 8.49 cm. √(12² + 12²) is the whole diagonal (the diameter).","hook":"Radius = half the diagonal: centre to corner.","keys":["r² = 6² + 6² = 72"]},{"id":"2023-P2-Q5:(e):1","from":"2023-P2-Q5","q":"Circle k has radius 8.49 cm. What is its circumference, correct to 2 decimal places?","right":"53.34 cm","wrong":["26.67 cm","106.63 cm","226.45 cm"],"why":"Circumference = 2πr = 2π(8.49) = 53.344… ≈ 53.34 cm.","hook":"Circumference: 2πr, or πd. Not both 2 and d!","keys":["2π(8.49) = 53.344"]},{"id":"2023-P2-Q8:(a):1","from":"2023-P2-Q8","q":"A cylindrical paddling pool has internal diameter 2.4 m and depth 0.9 m. It is filled to a depth of 0.75 m. What is the volume of water, to 2 decimal places?","right":"3.39 m³","wrong":["13.57 m³","4.07 m³","5.65 m³"],"why":"r = 2.4 ÷ 2 = 1.2 and the water is 0.75 deep: V = πr²h = π(1.2)²(0.75) = 3.3929… ≈ 3.39 m³.","hook":"Halve the diameter, and use the depth of the WATER.","keys":["π(1.2)²(0.75)"]},{"id":"2023-P2-Q8:(b)(i):1","from":"2023-P2-Q8","q":"Each of 3 pool seats is a cube with sides of 0.5 m. What is the total volume of the 3 seats?","right":"0.375 m³","wrong":["1.5 m³","0.75 m³","3.375 m³"],"why":"One cube: 0.5 × 0.5 × 0.5 = 0.125 m³. Three cubes: 3 × 0.125 = 0.375 m³.","hook":"Cube volume = side³. A decimal cubed gets smaller.","keys":["0.5 × 0.5 × 0.5 = 0.125"]},{"id":"2023-P2-Q8:(b)(ii):1","from":"2023-P2-Q8","q":"A cylindrical pool of radius 1.2 m holds water 0.6 m deep. Seats of total volume 0.375 m³ go fully under water. By how much does the level rise, to 2 decimal places?","right":"0.08 m","wrong":["0.02 m","0.26 m","0.68 m"],"why":"The rise is a cylinder with the seats’ volume: π(1.2)²h = 0.375, so h = 0.375 ÷ 4.524 = 0.0829 ≈ 0.08 m.","hook":"Rise × πr² = volume put in. The rise, not the new depth.","keys":["π(1.2)²h = 0.375"]},{"id":"2023-P2-Q8:(c)(i):1","from":"2023-P2-Q8","q":"A cone-shaped cover has radius 1.3 m and vertical height 0.8 m. What is its slant height l, to 2 decimal places?","right":"1.53 m","wrong":["1.02 m","2.10 m","2.72 m"],"why":"l² = h² + r² = 0.8² + 1.3² = 0.64 + 1.69 = 2.33, so l = √2.33 = 1.526… ≈ 1.53 m.","hook":"Slant height is the hypotenuse: square, add, square root.","keys":["0.64 + 1.69 = 2.33"]},{"id":"2023-P2-Q8:(c)(ii):1","from":"2023-P2-Q8","q":"A cone-shaped cover has radius 1.3 m, vertical height 0.8 m and slant height 1.53 m. What is its curved surface area, to 2 decimal places?","right":"6.25 m²","wrong":["3.27 m²","11.56 m²","12.50 m²"],"why":"Curved surface area = πrl = π(1.3)(1.53) = 6.2486… ≈ 6.25 m². It uses the slant height, not 0.8.","hook":"Cone skin: πrl. No base: it is a cover.","keys":["πrl = π(1.3)(1.53)"]},{"id":"2023-P2-Q8:(c)(iii):1","from":"2023-P2-Q8","q":"A cone (radius 1.3 m, height 0.8 m, slant height 1.53 m) is cut open and laid flat: a sector of radius x. What is x?","right":"1.53 m","wrong":["1.3 m","0.8 m","2.6 m"],"why":"The sector’s radius runs from the tip of the cone down its side to the base, so x is the slant height: 1.53 m.","hook":"In the net, the slant height becomes the sector’s radius.","keys":["x is the slant height"]},{"id":"2023-P2-Q8:(c)(iii):2","from":"2023-P2-Q8","q":"A cone of base radius 1.3 m opens out into a sector of radius 1.53 m. Find the sector’s angle A, to the nearest degree.","right":"306°","wrong":["188°","153°","54°"],"why":"The arc wraps round the base: (A/360) × 2π(1.53) = 2π(1.3), so A = 1.3 × 360 ÷ 1.53 = 305.88… ≈ 306°.","hook":"Arc of the sector = circumference of the base.","keys":["(A/360) × 2π(1.53) = 2π(1.3)"]},{"id":"2024-P2-Q10:(a)(i):1","from":"2024-P2-Q10","q":"The fastest women’s serve at Wimbledon 2023 was 121 miles per hour. Using 1 mile = 1.61 km, how many km is 121 miles?","right":"194.81 km","wrong":["75.16 km","193.60 km","1948.10 km"],"why":"Each mile is 1.61 km, so 121 miles = 121 × 1.61 = 194.81 km. (A km is shorter than a mile, so there are more of them.)","hook":"Miles to km: × 1.61 — the km number is always bigger.","keys":["121 × 1.61 = 194.81"]},{"id":"2024-P2-Q10:(a)(ii):1","from":"2024-P2-Q10","q":"How many seconds are in one hour?","right":"3600 seconds","wrong":["360 seconds","6000 seconds","60 seconds"],"why":"An hour has 60 minutes and each minute has 60 seconds: 60 × 60 = 3600 seconds.","hook":"Time is in 60s, not 100s: 60 × 60 = 3600.","keys":["60 × 60 = 3600"]},{"id":"2024-P2-Q10:(a)(iii):1","from":"2024-P2-Q10","q":"A serve travels at 194.81 km per hour, and 1 hour = 3600 seconds. What is this speed in metres per second, to 2 decimal places?","right":"54.11 m/s","wrong":["0.05 m/s","701.32 m/s","3246.83 m/s"],"why":"194.81 km = 194 810 m, travelled in 3600 s: 194 810 ÷ 3600 = 54.11 m/s.","hook":"km/h to m/s: × 1000 for metres, ÷ 3600 for seconds.","keys":["194 810 ÷ 3600 = 54.11"]},{"id":"2024-P2-Q10:(b):1","from":"2024-P2-Q10","q":"The smallest tennis ball allowed has a radius of 3.27 cm. What is its surface area, to 2 decimal places?","right":"134.37 cm²","wrong":["33.59 cm²","146.46 cm²","537.48 cm²"],"why":"Surface area of a sphere = 4πr² = 4π(3.27)² = 134.3709… ≈ 134.37 cm².","hook":"Sphere skin: 4πr² (squared, cm²). Volume is (4/3)πr³.","keys":["4π(3.27)² = 134.3709"]},{"id":"2024-P2-Q10:(c):1","from":"2024-P2-Q10","q":"A tennis ball has external radius 3.4 cm; its air-filled centre has radius 3.1 cm. What is the volume of the rubber layer, to 2 decimal places?","right":"39.85 cm³","wrong":["0.11 cm³","24.50 cm³","164.64 cm³"],"why":"Whole ball (4/3)π(3.4)³ = 164.636 minus the air (4/3)π(3.1)³ = 124.788 leaves 39.847… ≈ 39.85 cm³.","hook":"A hollow shell: big volume − small volume, not (big − small)³.","keys":["164.636 minus the air"]},{"id":"2024-P2-Q10:(d)(i):1","from":"2024-P2-Q10","q":"Three tennis balls of radius 3.4 cm are stacked one on top of the other in the smallest closed cylinder. What is the height h of the cylinder?","right":"20.4 cm","wrong":["10.2 cm","6.8 cm","40.8 cm"],"why":"Each ball is one diameter tall: 2 × 3.4 = 6.8 cm. Three balls: 3 × 6.8 = 20.4 cm (six radii).","hook":"Stacked balls: count diameters, not radii.","keys":["3 × 6.8 = 20.4"]},{"id":"2024-P2-Q10:(d)(ii):1","from":"2024-P2-Q10","q":"A closed cylinder holds 3 tennis balls exactly: radius 3.4 cm, height 20.4 cm. What is the volume of the cylinder, to the nearest whole number?","right":"741 cm³","wrong":["2963 cm³","436 cm³","494 cm³"],"why":"V = πr²h = π(3.4)²(20.4) = 740.86… ≈ 741 cm³.","hook":"Cylinder volume: πr²h, with the radius (half the width).","keys":["π(3.4)²(20.4)"]},{"id":"2024-P2-Q10:(d)(iii):1","from":"2024-P2-Q10","q":"Three tennis balls of radius 3.4 cm are stacked in the smallest closed rectangular box. What are the box’s dimensions?","right":"6.8 cm × 6.8 cm × 20.4 cm","wrong":["3.4 cm × 3.4 cm × 20.4 cm","6.8 cm × 20.4 cm × 20.4 cm","3.4 cm × 3.4 cm × 10.2 cm"],"why":"One ball must fit across, so the base is one diameter each way, 6.8 by 6.8; the height is three diameters, 20.4.","hook":"A ball needs a full diameter in every direction.","keys":["the base is one diameter each way"]},{"id":"2024-P2-Q10:(d)(iii):2","from":"2024-P2-Q10","q":"A closed rectangular box measures 6.8 cm × 6.8 cm × 20.4 cm. What is its total surface area?","right":"647.36 cm²","wrong":["601.12 cm²","323.68 cm²","943.30 cm²"],"why":"Two square ends 2(6.8 × 6.8) = 92.48 plus four sides 4(6.8 × 20.4) = 554.88: total 647.36 cm².","hook":"Closed box: six faces, in three matching pairs.","keys":["92.48 plus four sides","647.36"]},{"id":"2021-P2-Q2:(b):1","from":"2021-P2-Q2","q":"Figure ABCDE: a large square ACDE stands on the diagonal [AC] of a small square ABCF with side 2 cm, so triangle ABC sticks out below it. Find the area of ABCDE.","right":"10 cm²","wrong":["8 cm²","12 cm²","6 cm²"],"why":"|AC|² = 2² + 2² = 8, so the big square is √8 × √8 = 8 cm². Triangle ABC is half the small square: ½ × 2 × 2 = 2. Total 8 + 2 = 10 cm².","hook":"Square on a diagonal: Pythagoras gives its side; side² its area.","keys":["|AC|² = 2² + 2² = 8","8 + 2 = 10 cm²"]},{"id":"2021-P2-Q2:(b):2","from":"2021-P2-Q2","q":"Figure ABCDE: a large square ACDE on the diagonal [AC] of a small square ABCF (side 2 cm), where |AC| = √8 cm. Find the perimeter of ABCDE, to two decimal places.","right":"12.49 cm","wrong":["15.31 cm","10.00 cm","8.49 cm"],"why":"Go round the outside: AB + BC + CD + DE + EA = 2 + 2 + √8 + √8 + √8 = 4 + 3√8 = 12.485… ≈ 12.49 cm. AC is inside, so leave it out.","hook":"Perimeter: only the outside edges. Lines inside don't count.","keys":["4 + 3√8 = 12.485…","AC is inside"]},{"id":"2023-P2-Q10:(b):1","from":"2023-P2-Q10","q":"Triangle AOB in a regular pentagon has |OA| = |OB| = 6 cm and |∠AOB| = 72°. Find its area, correct to 1 decimal place.","right":"17.1 cm²","wrong":["18.0 cm²","4.6 cm²","34.2 cm²"],"why":"Two sides and the angle between them: Area = ½ab sin C = ½(6)(6) sin 72° = 17.119… ≈ 17.1 cm². Calculator in degrees (radians gives 4.6).","hook":"Two sides and the angle between: Area = ½ab sin C.","keys":["½(6)(6) sin 72° = 17.119…"]},{"id":"2023-P2-Q10:(b):2","from":"2023-P2-Q10","q":"A regular pentagon is made of 5 congruent triangles, each with sides 6 cm and 6 cm and 72° between them (area 17.119… cm²). Find the pentagon's area, to 1 decimal place.","right":"85.6 cm²","wrong":["85.5 cm²","90.0 cm²","22.8 cm²"],"why":"The pentagon is 5 of the triangles: 17.119… × 5 = 85.59… ≈ 85.6 cm². Use the unrounded value: 17.1 × 5 = 85.5 has lost accuracy.","hook":"Round only at the very end.","keys":["17.119… × 5 = 85.59…"]},{"id":"2024-P2-Q9:(d)(i):1","from":"2024-P2-Q9","q":"A cone logo: a sector of radius 20 cm, angle θ at the centre, sits on two right-angled triangles whose angles at the centre are 70° each. Find θ.","right":"220°","wrong":["140°","40°","290°"],"why":"The angles all the way round the centre add to 360°. The two 70° angles belong to the triangles, so θ = 360° − 2(70°) = 220°.","hook":"Angles round a point add up to 360°.","keys":["θ = 360° − 2(70°) = 220°"]},{"id":"2024-P2-Q9:(d)(i):2","from":"2024-P2-Q9","q":"A sector has radius 20 cm and angle 220° at the centre. Find the length of its arc s, correct to 1 decimal place.","right":"76.8 cm","wrong":["38.4 cm","767.9 cm","48.9 cm"],"why":"Arc = (θ/360) × 2πr = (220/360) × 2π(20) = 76.79… ≈ 76.8 cm. (θ/360) × πr² would be the sector's area, not its arc.","hook":"Arc: (θ/360) × 2πr. Area: (θ/360) × πr².","keys":["(220/360) × 2π(20) = 76.79…"]},{"id":"2025-P2-Q7:(c)(i):1","from":"2025-P2-Q7","q":"A child's football is a sphere with a diameter of 18 cm. Find its volume, in cm³, in terms of π.","right":"972π cm³","wrong":["7776π cm³","324π cm³","2916π cm³"],"why":"r = 18 ÷ 2 = 9 cm. V = (4/3)πr³ = (4/3)π(9)³ = (4/3) × 729π = 972π cm³. Leave π as a letter.","hook":"Given the diameter? Halve it first.","keys":["r = 18 ÷ 2 = 9 cm","972π cm³"]},{"id":"2025-P2-Q7:(c)(ii):1","from":"2025-P2-Q7","q":"An adult's football is a sphere with a volume of 5424.6 cm³. Work out its radius, correct to 1 decimal place.","right":"10.9 cm","wrong":["36.0 cm","12.0 cm","21.8 cm"],"why":"(4/3)πr³ = 5424.6, so r³ = 5424.6 ÷ (4/3)π = 1295.03…, and r = ∛1295.03… = 10.899… ≈ 10.9 cm. A cube root, not a square root.","hook":"Undo r³ with a cube root (∛).","keys":["r³ = 5424.6 ÷ (4/3)π = 1295.03…","10.9 cm"]}],"12":[{"id":"2015-P2-Q1:(a):1","from":"2015-P2-Q1","q":"A bank password has 6 digits. Each digit can be any of 0 to 9, and digits may be repeated. How many different passwords are possible?","right":"1 000 000","wrong":["151 200","531 441","60"],"why":"6 boxes with 10 options each, and repeats are allowed: 10 × 10 × 10 × 10 × 10 × 10 = 10⁶ = 1 000 000. (10 × 9 × 8 × … is for no repeats.)","hook":"Repeats allowed: every box keeps all its options. Multiply them.","keys":["10⁶ = 1 000 000"]},{"id":"2015-P2-Q1:(b)(i):1","from":"2015-P2-Q1","q":"A password has 6 digits, each 0 to 9, and digits may be repeated. How many different passwords do not contain any zero?","right":"531 441","wrong":["900 000","60 480","468 559"],"why":"No zero leaves 9 options (1 to 9) for every one of the 6 boxes, repeats still allowed: 9⁶ = 531 441. No zero anywhere, not only in the first box.","hook":"No zero: take 0 out of every box, then multiply.","keys":["9⁶ = 531 441"]},{"id":"2015-P2-Q1:(c):1","from":"2015-P2-Q1","q":"The bank asks John for 3 of the 6 digits of his password, for example the 2nd, 4th and 5th. In how many different ways can the bank select the three boxes?","right":"20","wrong":["120","216","15"],"why":"Boxes 2, 4, 5 are the same pick as 5, 2, 4: not an order, a selection. ⁶C₃ = (6 × 5 × 4) ÷ (3 × 2 × 1) = 20, or list them: 10 + 6 + 3 + 1 = 20.","hook":"Order doesn't matter? Count the orders, then divide by 3 × 2 × 1.","keys":["not an order, a selection","= 20"]},{"id":"2015-P2-Q1:(c):2","from":"2015-P2-Q1","q":"The bank picks 3 of the 6 boxes of John's password (for example the 2nd, 4th and 5th). Is this an arrangement or a selection, and why?","right":"Selection: 2, 4, 5 = 5, 2, 4","wrong":["Arrangement: the boxes are numbered 1–6","Arrangement: each box holds a digit","Selection: the digits may be repeated"],"why":"Asking for boxes 2, 4, 5 or 5, 2, 4 gets the same three digits, so order doesn't matter: a selection, ⁶C₃ = 20, not 6 × 5 × 4 = 120.","hook":"Does swapping the order give something new? No: it's a selection (nCr).","keys":["order doesn't matter"]},{"id":"2020-P2-Q1:(a)(i):1","from":"2020-P2-Q1","q":"A restaurant has 4 starters, 6 main courses and 8 desserts. A meal is one starter, one main course and one dessert. How many different three-course meals are available?","right":"192","wrong":["18","816","24"],"why":"Every starter goes with every main, and every pair with every dessert, so multiply: 4 × 6 × 8 = 192. 4 + 6 + 8 = 18 counts dishes, not meals.","hook":"One from each group: multiply the group sizes.","keys":["4 × 6 × 8 = 192"]},{"id":"2020-P2-Q1:(a)(ii):1","from":"2020-P2-Q1","q":"The restaurant still has its 4 starters and 6 main courses, but some of its 8 desserts have sold out. There are now 120 different three-course meals. How many desserts are still available?","right":"5","wrong":["110","20","3"],"why":"Starters × mains × desserts = meals: 4 × 6 × d = 120, so 24d = 120 and d = 5. Check: 4 × 6 × 5 = 120. (3 is how many sold out.)","hook":"Same counting rule with the unknown in it: then solve for d.","keys":["4 × 6 × d = 120","d = 5"]},{"id":"2020-P2-Q1:(a)(ii):2","from":"2020-P2-Q1","q":"4 starters, 6 main courses and d desserts give 120 different three-course meals. Which equation finds d?","right":"4 × 6 × d = 120","wrong":["4 + 6 + d = 120","4 × 6 + d = 120","4 × 6 × 8 − d = 120"],"why":"The number of meals is starters × mains × desserts, however many desserts there are, so 4 × 6 × d = 120, giving d = 120 ÷ 24 = 5.","hook":"Meals = starters × mains × desserts.","keys":["starters × mains × desserts"]},{"id":"2022-P2-Q3:(b)(i):1","from":"2022-P2-Q3","q":"Ben must pick one subject from each group: Group A has 3 subjects, Group B has 4 and Group C has 5. How many different choices of three subjects can he make?","right":"60","wrong":["12","220","360"],"why":"Each A subject goes with each B subject and each C subject: 3 × 4 × 5 = 60. 3 + 4 + 5 = 12 is the number of subjects, not of choices.","hook":"One from each group: multiply.","keys":["3 × 4 × 5 = 60"]},{"id":"2022-P2-Q3:(b)(ii):1","from":"2022-P2-Q3","q":"Groups A, B and C have 3, 4 and 5 subjects, and Ben picks one from each. One extra subject is added to one group. Which group should get it, to give Ben the most choices?","right":"Group A","wrong":["Group B","Group C","It makes no difference"],"why":"Try each: extra in A gives 4 × 4 × 5 = 80, in B 3 × 5 × 5 = 75, in C 3 × 4 × 6 = 72. 80 is the biggest, so Group A.","hook":"Test every option and compare: show all three products.","keys":["4 × 4 × 5 = 80"]},{"id":"2022-P2-Q3:(b)(ii):2","from":"2022-P2-Q3","q":"Groups A, B and C have 3, 4 and 5 subjects: 60 choices of one from each. One extra subject is added to Group A. How many choices are there now?","right":"80","wrong":["61","13","120"],"why":"Group A now has 4: 4 × 4 × 5 = 80. The new subject pairs with every one of the 4 × 5 = 20 B-and-C pairs, so 20 more choices, not 1 more.","hook":"One new item adds a choice for every pairing of the other groups.","keys":["4 × 4 × 5 = 80","20 more choices"]},{"id":"2023-P2-Q3:(a)(i):1","from":"2023-P2-Q3","q":"In how many ways can the letters of the word CAMOGIE be arranged?","right":"5040","wrong":["823 543","28","720"],"why":"7 different letters: 7 choices for the 1st place, 6 left for the 2nd, and so on: 7 × 6 × 5 × 4 × 3 × 2 × 1 = 7! = 5040. No letter repeats, so not 7⁷.","hook":"n different things in a row: n! ways.","keys":["7! = 5040"]},{"id":"2023-P2-Q3:(a)(ii):1","from":"2023-P2-Q3","q":"How many arrangements of the letters of CAMOGIE start with M and end with a vowel (A, O, I or E)?","right":"480","wrong":["120","2880","720"],"why":"Restricted places first: the 1st must be M (1 way), the last a vowel (4 ways). 5 letters are left for the 5 middle places: 5! = 120. 1 × 120 × 4 = 480.","hook":"Restricted places first (first, last), then fill the rest.","keys":["1 × 120 × 4 = 480"]},{"id":"2023-P2-Q3:(a)(ii):2","from":"2023-P2-Q3","q":"You are counting the arrangements of CAMOGIE that start with M and end with a vowel. Which places should you fill first?","right":"The first and last places","wrong":["The places in order, left to right","The five middle places","The places with the most options"],"why":"Places with rules come first: the 1st (only M: 1 way) and the last (a vowel: 4 ways). Then the 5 free letters fill the middle: 5 × 4 × 3 × 2 × 1.","hook":"Rules first, free places last.","keys":["Places with rules come first"]},{"id":"2023-P2-Q3:(a)(iii):1","from":"2023-P2-Q3","q":"How many arrangements of 3 different letters can be made from the letters of the word CAMOGIE?","right":"210","wrong":["35","343","5040"],"why":"3 places, 7 letters, no letter twice: 7 × 6 × 5 = 210. Stop after 3 places (not 7!), and order counts, so not ⁷C₃ = 35.","hook":"r places from n things: n × (n − 1) × … with only r numbers.","keys":["7 × 6 × 5 = 210"]},{"id":"2018-P2-Q3:(a)(i):1","from":"2018-P2-Q3","q":"Find the number of different arrangements that can be made using all the letters of the word RAINBOW, each letter used only once.","right":"5040","wrong":["823 543","720","49"],"why":"7 different letters fill 7 places: 7, then 6, 5, 4, 3, 2, 1 options. 7! = 7 × 6 × 5 × 4 × 3 × 2 × 1 = 5040.","hook":"All n different letters in a row: n! (the x! key).","keys":["7! = 7 × 6 × 5 × 4 × 3 × 2 × 1 = 5040"]},{"id":"2018-P2-Q3:(a)(i):2","from":"2018-P2-Q3","q":"Arranging all 7 letters of RAINBOW: why is it 7 × 6 × 5 × … and not 7 × 7 × 7 × …?","right":"Each letter is used only once","wrong":["There are 7 letters to choose from","The order of the letters matters","There are 7 places to fill"],"why":"Once a letter is placed it can't be used again, so each place has one option fewer: 7, 6, 5, … 7 × 7 × 7 × … would let letters repeat.","hook":"No repeats: the options drop by 1 at each place.","keys":["each place has one option fewer"]},{"id":"2018-P2-Q3:(a)(ii):1","from":"2018-P2-Q3","q":"How many different 3-letter arrangements can be made using the letters of the word RAINBOW, each letter used at most once?","right":"210","wrong":["35","343","18"],"why":"3 places, 7 letters, no repeats: 7 × 6 × 5 = 210. Order matters (RAI isn't IAR), so not ⁷C₃ = 35; no repeats, so not 7³ = 343.","hook":"Stop after 3 places: 7 × 6 × 5, not 7!.","keys":["7 × 6 × 5 = 210"]},{"id":"2021-P2-Q1:(a):1","from":"2021-P2-Q1","q":"Twister: one spinner gives Left Hand, Right Hand, Left Foot or Right Foot; the other gives Yellow, Red, Blue or Green. How many different outcomes are there?","right":"16","wrong":["8","24","6"],"why":"Each of the 4 body parts can go with each of the 4 colours: 4 × 4 = 16 outcomes (a 4 by 4 table). 4 + 4 = 8 counts the sections, not the pairs.","hook":"Two spinners: multiply their numbers of sections.","keys":["4 × 4 = 16"]},{"id":"2024-P2-Q2:(a):1","from":"2024-P2-Q2","q":"Seán's cards: green ones numbered 1 to 7 and red ones numbered 1 to 7. A table has Colour (G, R) down the side and Number (1 to 7) across. How many outcomes does it show?","right":"14","wrong":["9","49","7"],"why":"Each of the 2 colours goes with each of the 7 numbers: 2 × 7 = 14 cells, G1 to G7 and R1 to R7: one for each card.","hook":"Outcomes in a table = rows × columns.","keys":["2 × 7 = 14"]},{"id":"2024-P2-Q9:(a)(i):1","from":"2024-P2-Q9","q":"An ice cream van sells 7 flavours, 4 toppings, and a cone or a tub. How many different choices are there of one flavour, one topping, and a cone or a tub?","right":"56","wrong":["13","28","286"],"why":"One from each group: 7 × 4 × 2 = 56. Every flavour goes with every topping, and each pair comes in a cone or a tub. 7 + 4 + 2 = 13 counts items.","hook":"Choices from separate groups: multiply.","keys":["7 × 4 × 2 = 56"]},{"id":"2024-P2-Q9:(a)(ii):1","from":"2024-P2-Q9","q":"7 flavours, 4 toppings, 2 containers: 56 choices. How many choices would there be with one extra flavour, and how many with one extra topping instead?","right":"Flavour 64, topping 70","wrong":["Flavour 70, topping 64","Both 57","Both 14"],"why":"Extra flavour: 8 × 4 × 2 = 64. Extra topping: 7 × 5 × 2 = 70. 70 > 64, so he should add a topping.","hook":"An extra topping pairs with 7 × 2 = 14 others; a flavour only with 4 × 2 = 8.","keys":["7 × 5 × 2 = 70","add a topping"]},{"id":"2022-P2-Q7:(d):1","from":"2022-P2-Q7","q":"The 9 female cats are put in 9 separate pens, one cat per pen. In how many different ways can this be done?","right":"362 880","wrong":["387 420 489","45","81"],"why":"The first pen can have any of 9 cats, the next any of the 8 left, and so on: 9 × 8 × 7 × … × 1 = 9! = 362 880.","hook":"Arranging n different things in order: n! ways.","keys":["9! = 362 880"]}],"13":[{"id":"2015-P2-Q1:(b)(ii):1","from":"2015-P2-Q1","q":"Of the 1 000 000 possible 6-digit passwords, 531 441 contain no zero. One password is picked at random. What is the probability that it contains at least one zero?","right":"0.468559","wrong":["0.531441","0.6","0.354294"],"why":"Take the no-zero passwords from the total: 1 000 000 − 531 441 = 468 559 have at least one zero. P = 468 559 ÷ 1 000 000 = 0.468559 (= 1 − 0.531441).","hook":"At least one = 1 − none.","keys":["1 000 000 − 531 441 = 468 559"]},{"id":"2015-P2-Q1:(b)(ii):2","from":"2015-P2-Q1","q":"What is the quickest correct way to find the probability that a random 6-digit password contains at least one zero?","right":"1 − P(no zero)","wrong":["1 − P(all six digits are 0)","6 × P(a digit is 0)","P(exactly one zero)"],"why":"\"At least one zero\" is every password except those with no zero, so take P(no zero) away from 1. 6 × 0.1 counts passwords with two or more zeros more than once.","hook":"At least one? Find P(none), then take it from 1.","keys":["take P(no zero) away from 1"]},{"id":"2020-P2-Q1:(b)(i):1","from":"2020-P2-Q1","q":"In a large population, 1 in 8 people play tennis. Four people are chosen at random. What is the probability that the fourth person chosen is the only one to play tennis?","right":"343/4096","wrong":["1372/4096","7/4096","1/8"],"why":"Only the 4th plays: no, no, no, yes. People are independent, so 7/8 × 7/8 × 7/8 × 1/8 = 343/4096 ≈ 0.0837. The question names the person, so no × 4.","hook":"Named position (the 4th)? One order only: no × 4.","keys":["7/8 × 7/8 × 7/8 × 1/8 = 343/4096"]},{"id":"2020-P2-Q1:(b)(i):2","from":"2020-P2-Q1","q":"1 in 8 people play tennis. Four people are chosen. Why is P(the fourth is the only one who plays) just 7/8 × 7/8 × 7/8 × 1/8, with no × 4?","right":"The question says which person plays","wrong":["The four people are independent","Only one of the four people plays","Each person has the same 1/8 chance"],"why":"A × 4 would count the 4 places the one player could be in. Here the player must be the 4th, so only the order no, no, no, yes counts.","hook":"\"Exactly one\": × the number of orders. \"Only the 4th\": one order.","keys":["only the order no, no, no, yes counts"]},{"id":"2020-P2-Q1:(b)(ii):1","from":"2020-P2-Q1","q":"1 in 8 people play tennis. Three people are chosen at random. What is the probability that exactly two of them play tennis?","right":"21/512","wrong":["7/512","147/512","3/64"],"why":"Two play, one doesn't: 1/8 × 1/8 × 7/8 = 7/512 for each order. The non-player can be 1st, 2nd or 3rd, so 3 × 7/512 = 21/512 ≈ 0.041.","hook":"Exactly two of three: one order's chance × 3.","keys":["3 × 7/512 = 21/512"]},{"id":"2020-P2-Q1:(b)(ii):2","from":"2020-P2-Q1","q":"Three people are chosen and exactly two of them play tennis (T = plays, N = doesn't play). In how many different orders can this happen?","right":"3","wrong":["2","6","8"],"why":"The one who doesn't play can be 1st, 2nd or 3rd: TTN, TNT, NTT. So there are 3 orders, each with the same probability.","hook":"Not sure how many orders? List them: TTN, TNT, NTT.","keys":["TTN, TNT, NTT"]},{"id":"2016-P2-Q1:(a)(i):1","from":"2016-P2-Q1","q":"168 people were surveyed: 64 own a cat and a dog, 48 own a dog only and 19 own neither. How many own a cat only?","right":"37","wrong":["56","101","85"],"why":"All four regions of the Venn diagram add to 168, so cats only = 168 − 19 − 64 − 48 = 37. The 19 go outside both circles.","hook":"Venn regions add up to the total: take away the ones you know.","keys":["168 − 19 − 64 − 48 = 37"]},{"id":"2016-P2-Q1:(a)(ii):1","from":"2016-P2-Q1","q":"168 people surveyed: 37 own a cat only, 64 a cat and a dog, 48 a dog only, 19 neither. One is picked at random. What is the probability they own both a cat and a dog?","right":"64/168 (= 8/21)","wrong":["64/149","64/112","64/101"],"why":"Both = the overlap, 64 people. Divide by everyone surveyed, 168 (the 19 with no pet were surveyed too): 64/168 = 8/21.","hook":"Probability = how many fit ÷ everyone who could be picked.","keys":["64/168 = 8/21"]},{"id":"2016-P2-Q1:(a)(iii):1","from":"2016-P2-Q1","q":"168 surveyed: 37 own a cat only, 64 a cat and a dog, 48 a dog only, 19 neither. What percentage own one animal only, correct to one decimal place?","right":"50.6%","wrong":["88.7%","57.0%","0.5%"],"why":"One animal only = cats only + dogs only = 37 + 48 = 85 (leave out the 64 with both). 85 ÷ 168 × 100 = 50.59…% ≈ 50.6%.","hook":"\"Only one\" leaves out the overlap. A percentage: × 100.","keys":["37 + 48 = 85","50.6%"]},{"id":"2016-P2-Q1:(a)(iii):2","from":"2016-P2-Q1","q":"In a Venn diagram of cat owners and dog owners, which regions hold the people who own one animal only?","right":"Cats only and dogs only","wrong":["Cats only, dogs only and both","The overlap of the two circles","Everything outside the overlap"],"why":"One animal only means a cat but no dog, or a dog but no cat: the two parts of the circles that don't overlap. The overlap owns two; outside owns none.","hook":"Only one = the circles without the overlap.","keys":["the two parts of the circles that don't overlap"]},{"id":"2016-P2-Q1:(b):1","from":"2016-P2-Q1","q":"Mandy picks Balcony or Stalls, then Monday, Wednesday or Friday, then VIP or show only. All choices are equally likely. What is the probability that she chooses a VIP ticket on a Wednesday?","right":"1/6","wrong":["1/12","5/6","2/7"],"why":"Two paths fit: B→W→V and S→W→V, each ½ × ⅓ × ½ = 1/12. Add them: 1/12 + 1/12 = 2/12 = 1/6. Or: 2 of the 12 equally likely outcomes.","hook":"Multiply along a path; add the paths that fit.","keys":["1/12 + 1/12 = 2/12 = 1/6"]},{"id":"2016-P2-Q1:(b):2","from":"2016-P2-Q1","q":"Mandy chooses Balcony or Stalls, then Monday, Wednesday or Friday, then VIP or show only. How many outcomes does the finished tree diagram have?","right":"12","wrong":["7","6","8"],"why":"Each seat splits into 3 days, and each day into 2 ticket types: 2 × 3 × 2 = 12 outcomes at the ends of the branches. 2 + 3 + 2 = 7 adds instead.","hook":"Tree outcomes = the numbers of branches multiplied.","keys":["2 × 3 × 2 = 12"]},{"id":"2017-P2-Q1:(a)(i):1","from":"2017-P2-Q1","q":"65 909 babies were born in Ireland in 2015, and 32 290 of them were girls. How many boys were born?","right":"33 619","wrong":["98 199","33 799","33 719"],"why":"Every baby is a boy or a girl, so boys = all babies − girls = 65 909 − 32 290 = 33 619. Check by adding back: 33 619 + 32 290 = 65 909.","hook":"Check a subtraction by adding the answer back.","keys":["65 909 − 32 290 = 33 619"]},{"id":"2017-P2-Q1:(a)(ii):1","from":"2017-P2-Q1","q":"Of the 65 909 babies born in 2015, 33 619 were boys. What is the probability that a baby picked at random is a boy, correct to 2 decimal places?","right":"0.51","wrong":["0.49","1.04","0.50"],"why":"P(boy) = boys ÷ all babies = 33 619 ÷ 65 909 = 0.5100… ≈ 0.51. Divide by all the babies, not by the girls, and use the real counts, not 50:50.","hook":"Probability = what you want ÷ the total.","keys":["33 619 ÷ 65 909 = 0.5100…"]},{"id":"2017-P2-Q1:(b)(i):1","from":"2017-P2-Q1","q":"P(a baby is a boy) = 0.51, and births are independent. 8 babies are born in a hospital one day. What is the probability that the first three are boys, to 4 decimal places?","right":"0.1327","wrong":["0.2601","0.0037","0.1176"],"why":"Independent births: multiply. 0.51 × 0.51 × 0.51 = 0.132651 ≈ 0.1327. The other 5 babies can be boys or girls, so they don't come into it.","hook":"Independent events one after another: multiply.","keys":["0.51 × 0.51 × 0.51 = 0.132651"]},{"id":"2017-P2-Q1:(b)(ii):1","from":"2017-P2-Q1","q":"P(a baby is a boy) = 0.51, and births are independent. What is the probability that the third birth was the first girl born that day, to 4 decimal places?","right":"0.1274","wrong":["0.1225","0.3823","0.4900"],"why":"Third birth the first girl: boy, boy, girl. P(girl) = 1 − 0.51 = 0.49, so 0.51 × 0.51 × 0.49 = 0.127449 ≈ 0.1274. One order only: no × 3.","hook":"\"First … on the 3rd\": fail, fail, then succeed.","keys":["boy, boy, girl","0.51 × 0.51 × 0.49 = 0.127449"]},{"id":"2017-P2-Q1:(b)(ii):2","from":"2017-P2-Q1","q":"\"The third baby born was the first girl born that day.\" Which outcomes for births 1, 2 and 3 does this mean?","right":"Boy, boy, girl","wrong":["Girl, boy, boy","Any order with exactly one girl","Boy, boy, then a boy or a girl"],"why":"The first girl comes 3rd, so births 1 and 2 must both be boys, and birth 3 a girl. Only that one order fits.","hook":"First success on go 3 = fail, fail, success.","keys":["births 1 and 2 must both be boys"]},{"id":"2017-P2-Q1:(c)(i):1","from":"2017-P2-Q1","q":"Probability of being born on each day: Mon 0.14, Tue ?, Wed 0.15, Thu 0.18, Fri 0.15, Sat 0.12, Sun 0.1. What is the probability for Tuesday?","right":"0.16","wrong":["0.84","0.14","0.25"],"why":"The six known ones add to 0.14 + 0.15 + 0.18 + 0.15 + 0.12 + 0.1 = 0.84. All seven add to 1, so Tuesday = 1 − 0.84 = 0.16. (Sunday 0.1 = 0.10.)","hook":"The probabilities of all the outcomes add up to 1.","keys":["1 − 0.84 = 0.16"]},{"id":"2017-P2-Q1:(c)(i):2","from":"2017-P2-Q1","q":"Why must the probabilities of being born on Monday, Tuesday, …, Sunday add up to exactly 1?","right":"Every baby is born on exactly one day","wrong":["There are 7 days in the week","Each day is equally likely","Probabilities are never more than 1"],"why":"The seven days cover every possible outcome, and no baby is born on two days, so together they are certain: total probability 1.","hook":"Outcomes that cover everything, with no overlap, add to 1.","keys":["together they are certain"]},{"id":"2017-P2-Q1:(c)(ii):1","from":"2017-P2-Q1","q":"P(a baby is born on a Tuesday) = 0.16. In one week 1300 babies were born. How many babies would you expect to be born on the Tuesday of that week?","right":"208","wrong":["186","8125","1092"],"why":"Expected number = total × probability = 1300 × 0.16 = 208. (1300 ÷ 7 would treat all days as equally likely, but Tuesday's is 0.16.)","hook":"Expected number = how many there are × the probability.","keys":["1300 × 0.16 = 208"]},{"id":"2018-P2-Q1:(a)(i):1","from":"2018-P2-Q1","q":"Two fair dice are thrown and the scores added. A table shows the total for every pair of scores (Die 1 across, Die 2 down). How many cells does it have?","right":"36","wrong":["11","12","21"],"why":"Each of Die 1's 6 scores goes with each of Die 2's 6 scores: 6 × 6 = 36 outcomes. 11 is only the number of different totals (2 to 12).","hook":"Count outcomes, not totals: two dice give 6 × 6 = 36.","keys":["6 × 6 = 36"]},{"id":"2018-P2-Q1:(a)(ii):1","from":"2018-P2-Q1","q":"Two fair dice are thrown and the scores added. What is the probability of getting a total of 7 or 11?","right":"8/36","wrong":["2/11","6/36","12/1296"],"why":"Six of the 36 outcomes make 7 (1+6, 2+5, … 6+1) and two make 11 (5+6, 6+5). A total can't be both, so add: 8/36 = 2/9.","hook":"\"Or\" with no overlap: add the counts.","keys":["8/36 = 2/9"]},{"id":"2018-P2-Q1:(a)(ii):2","from":"2018-P2-Q1","q":"Two dice: P(total of 7 or 11) = 6/36 + 2/36. Why can you simply add the two here?","right":"A total can't be 7 and 11 at once","wrong":["The two dice are independent","7 and 11 are both odd numbers","Each total is equally likely"],"why":"No outcome is in both groups (they are mutually exclusive), so nothing is counted twice and P(7 or 11) = P(7) + P(11).","hook":"Add for \"or\" only when nothing can be in both.","keys":["mutually exclusive"]},{"id":"2018-P2-Q1:(a)(iii):1","from":"2018-P2-Q1","q":"Two fair dice are thrown and the scores added. What is the probability that the total is a prime number?","right":"15/36","wrong":["5/11","19/36","14/36"],"why":"Prime totals: 2, 3, 5, 7, 11. They come up 1 + 2 + 4 + 6 + 2 = 15 times in the 36 outcomes: 15/36 = 5/12. (9 = 3 × 3 is not prime.)","hook":"Primes up to 12: 2, 3, 5, 7, 11. Then count outcomes.","keys":["1 + 2 + 4 + 6 + 2 = 15"]},{"id":"2018-P2-Q1:(a)(iii):2","from":"2018-P2-Q1","q":"Two dice are thrown and the scores added. Which of the possible totals are prime numbers?","right":"2, 3, 5, 7, 11","wrong":["3, 5, 7, 11","2, 3, 5, 7, 9, 11","3, 5, 7, 9, 11"],"why":"A prime has exactly two factors, 1 and itself. 2 is prime (the only even one); 9 = 3 × 3 is not. The totals run 2 to 12, so: 2, 3, 5, 7, 11.","hook":"2 is prime; 9 isn't (3 × 3).","keys":["exactly two factors"]},{"id":"2018-P2-Q1:(b):1","from":"2018-P2-Q1","q":"30 cars: 18 Fords (7 of them red) and 12 Renaults (4 of them red). One car is chosen at random. What is the probability that it is a Ford or a car which is not red?","right":"26/30","wrong":["37/30","11/30","19/30"],"why":"All 18 Fords, plus the Renaults that are not red: 12 − 4 = 8. Not-red Fords are already in the 18. 18 + 8 = 26, so 26/30 = 13/15. (Or 30 − 4.)","hook":"\"Or\": count everything in either group, but each car only once.","keys":["18 + 8 = 26","26/30 = 13/15"]},{"id":"2018-P2-Q1:(b):2","from":"2018-P2-Q1","q":"30 cars: Ford 18 (7 red, 11 not red), Renault 12 (4 red, 8 not red). Which cars are NOT \"a Ford or not red\"?","right":"The 4 red Renaults","wrong":["The 7 red Fords","The 8 not-red Renaults","The 11 not-red Fords"],"why":"A car fails \"Ford or not red\" only if it is not a Ford and is red: a red Renault. There are 4, so P = (30 − 4)/30 = 26/30.","hook":"Tricky \"or\"? Count what fits neither, and take it away.","keys":["(30 − 4)/30 = 26/30"]},{"id":"2018-P2-Q3:(b)(i):1","from":"2018-P2-Q3","q":"A spinner has 7 sectors: red 72°, orange 30°, yellow 45°, green 90°, blue 60°, indigo 18°, violet 45°. Yellow's probability is 1/8. What is the probability of red?","right":"1/5","wrong":["1/7","18/25","2/5"],"why":"Probability = the sector's angle ÷ 360° (check: yellow 45/360 = 1/8). Red: 72/360 = 1/5. The sectors aren't equal, so not 1/7.","hook":"Spinner probability = angle ÷ 360°.","keys":["72/360 = 1/5"]},{"id":"2018-P2-Q3:(b)(i):2","from":"2018-P2-Q3","q":"A spinner has 7 sectors of different sizes. How do you find the probability of it stopping in each sector?","right":"Its angle ÷ 360°","wrong":["1 ÷ 7, the number of sectors","Its angle ÷ 100","Its angle ÷ 180°"],"why":"A sector's chance is the fraction of the full turn it covers: its angle ÷ 360°. 1/7 only works if all 7 sectors are the same size.","hook":"Fraction of the circle = fraction of the time.","keys":["the fraction of the full turn it covers"]},{"id":"2018-P2-Q3:(b)(ii):1","from":"2018-P2-Q3","q":"Spinner prizes (probability): red €20 (1/5), orange €60 (1/12), yellow €24 (1/8), green €8 (1/4), blue €42 (1/6), indigo €90 (1/20), violet €48 (1/8). Expected prize?","right":"€31.50","wrong":["€41.71","€4.50","€25.50"],"why":"E(X) = Σ prize × probability = 4 + 5 + 3 + 2 + 7 + 4.5 + 6 = €31.50. Add all seven products, and don't divide by 7.","hook":"Expected value: each value × its probability, then add them all.","keys":["4 + 5 + 3 + 2 + 7 + 4.5 + 6 = €31.50"]},{"id":"2018-P2-Q3:(b)(ii):2","from":"2018-P2-Q3","q":"A spinner game has seven prizes, each with its own probability. How do you find the expected value of the prize?","right":"Add up prize × probability for all 7","wrong":["Add the 7 prizes and divide by 7","Biggest prize × its probability","The prize of the likeliest colour"],"why":"E(X) = Σ x·P(x): multiply each prize by its probability and add all seven. Dividing by 7 would treat every colour as equally likely.","hook":"E(X) = Σ x × P(x).","keys":["Σ x·P(x)"]},{"id":"2019-P2-Q3:(a):1","from":"2019-P2-Q3","q":"In a population, the probability that a person has blue eyes is 0.7. One person is chosen at random. What is the probability that they do not have blue eyes?","right":"0.3","wrong":["30","0.03","0.7"],"why":"A person either has blue eyes or doesn't, so the two add to 1: P(not blue) = 1 − 0.7 = 0.3. A probability is never more than 1 (30% = 0.3).","hook":"P(not A) = 1 − P(A).","keys":["1 − 0.7 = 0.3"]},{"id":"2019-P2-Q3:(b):1","from":"2019-P2-Q3","q":"P(a person has blue eyes) = 0.7. Two people are chosen at random. What is the probability that both have blue eyes?","right":"0.49","wrong":["0.09","0.21","0.7"],"why":"The two people are independent, so multiply along blue, blue: 0.7 × 0.7 = 0.49. (0.3 × 0.3 = 0.09 is the chance that neither has blue eyes.)","hook":"\"Both\", with independent people: multiply.","keys":["0.7 × 0.7 = 0.49"]},{"id":"2019-P2-Q3:(b):2","from":"2019-P2-Q3","q":"P(blue eyes) = 0.7. Why can you multiply 0.7 × 0.7 for two people chosen at random from a large population?","right":"One person's eyes don't affect another's","wrong":["Both people have the same probability","There are two people","0.7 is more than a half"],"why":"Multiplying works for independent events: one person's eye colour doesn't change the chance for the next, so P(blue, blue) = 0.7 × 0.7.","hook":"Multiply only when one result doesn't change the other's chance.","keys":["independent events"]},{"id":"2019-P2-Q3:(c):1","from":"2019-P2-Q3","q":"P(a person has blue eyes) = 0.7. Three people are chosen at random. What is the probability that exactly two of them have blue eyes?","right":"0.441","wrong":["0.147","0.343","0.189"],"why":"One order: 0.7 × 0.7 × 0.3 = 0.147. The person without blue eyes can be 1st, 2nd or 3rd, so × 3: 3 × 0.147 = 0.441.","hook":"Exactly 2 of 3: one order's chance × 3.","keys":["3 × 0.147 = 0.441"]},{"id":"2019-P2-Q3:(c):2","from":"2019-P2-Q3","q":"Three people are chosen. Which list shows every way that exactly two have blue eyes (B = blue, N = not blue)?","right":"BBN, BNB, NBB","wrong":["BBN only","BBN, NBB","BBN, BNB, NBB, BBB"],"why":"Exactly two blue means exactly one N, and the N can be in any of the 3 places: BBN, BNB, NBB. BBB has three blue, so it doesn't count.","hook":"Exactly 2: list every place the odd one out can go.","keys":["BBN, BNB, NBB"]},{"id":"2019-P2-Q3:(d):1","from":"2019-P2-Q3","q":"P(a person has blue eyes) = 0.7. Four people are chosen one after another. What is the probability that the fourth person is the only one with blue eyes?","right":"0.0189","wrong":["0.0756","0.0081","0.1029"],"why":"Not, not, not, blue: 0.3 × 0.3 × 0.3 × 0.7 = 0.0189. The question names the 4th person, so only this one order counts: no × 4.","hook":"Named position? One order only.","keys":["0.3 × 0.3 × 0.3 × 0.7 = 0.0189"]},{"id":"2021-P2-Q1:(b)(i):1","from":"2021-P2-Q1","q":"Twister: spinner 1 gives LH, RH, LF or RF; spinner 2 gives one of 4 colours (equal sections). Kate spins both once. What is the probability that she must use her left foot?","right":"1/4","wrong":["1/16","1/8","1/2"],"why":"Left foot is a whole row of the 4 × 4 table: 4 of the 16 outcomes, any colour. 4/16 = 1/4 (or just spinner 1: 1 of its 4 sections).","hook":"Only one spinner matters? Use just that spinner.","keys":["4/16 = 1/4"]},{"id":"2021-P2-Q1:(b)(ii):1","from":"2021-P2-Q1","q":"Twister: the colour spinner has 4 equal sections: Yellow, Red, Blue and Green. Kate spins both spinners once. What is the probability of a red or yellow spot?","right":"1/2","wrong":["1/16","2/16","1/4"],"why":"Red and Yellow are 2 of the 4 colours: 8 of the 16 outcomes, or 1/4 + 1/4 = 1/2. A spot can't be both, so just add. Multiplying is for \"and\".","hook":"\"Or\" with no overlap: add.","keys":["1/4 + 1/4 = 1/2"]},{"id":"2021-P2-Q1:(c)(i):1","from":"2021-P2-Q1","q":"Twister: spinner 1 has 4 equal sections (LH, RH, LF, RF), spinner 2 has 4 equal colours. Jack spins both. What is the probability of his right hand and a blue spot?","right":"1/16","wrong":["1/2","1/8","7/16"],"why":"Right hand and blue is one cell of the 16-cell table: 1/16. Or, as the spinners are independent, 1/4 × 1/4 = 1/16. Adding 1/4 + 1/4 is for \"or\".","hook":"\"And\" with independent spinners: multiply.","keys":["1/4 × 1/4 = 1/16"]},{"id":"2021-P2-Q1:(c)(ii):1","from":"2021-P2-Q1","q":"Twister: spinner 1 has 4 equal sections (LH, RH, LF, RF), spinner 2 has 4 equal colours. Jack spins both. What is the probability of his right hand or a blue spot?","right":"7/16","wrong":["8/16","1/16","6/16"],"why":"Right hand is a row of 4, blue a column of 4, and they share 1 cell. 4/16 + 4/16 − 1/16 = 7/16: take off the shared cell so it's counted once.","hook":"P(A or B) = P(A) + P(B) − P(A and B).","keys":["4/16 + 4/16 − 1/16 = 7/16"]},{"id":"2021-P2-Q1:(c)(ii):2","from":"2021-P2-Q1","q":"Twister: P(right hand or blue) = 4/16 + 4/16 − 1/16. Why take away the 1/16?","right":"Right hand AND blue was counted twice","wrong":["The two spinners are independent","Right hand with blue doesn't count","Blue is only one of the 4 colours"],"why":"Right hand + blue is in the right-hand row AND the blue column, so 4 + 4 counts it twice. Take 1 off so it is counted once: it still counts.","hook":"\"Or\" means either one or both: count the overlap once.","keys":["counts it twice"]},{"id":"2021-P2-Q2:(a)(i):1","from":"2021-P2-Q2","q":"At a fun fair stall, the probability of knocking a coconut off its support is 0.34. What is the probability of not knocking it off?","right":"0.66","wrong":["0.34","66","0.066"],"why":"You either knock it off or you don't, so the two add to 1: P(not) = 1 − 0.34 = 0.66. Keep it a decimal: 66 is the percentage (66%).","hook":"P(not) = 1 − P(it happens).","keys":["1 − 0.34 = 0.66"]},{"id":"2021-P2-Q2:(a)(ii):1","from":"2021-P2-Q2","q":"P(knocking the coconut off) = 0.34 each go, independently. David has three goes. What is the probability he knocks it off for the first time on his third go, to 3 d.p.?","right":"0.148","wrong":["0.444","0.076","0.287"],"why":"First time on the 3rd go: miss, miss, hit. 0.66 × 0.66 × 0.34 = 0.148104 ≈ 0.148. One order only, so no × 3.","hook":"First success on go 3: miss, miss, hit.","keys":["miss, miss, hit","0.66 × 0.66 × 0.34 = 0.148104"]},{"id":"2023-P2-Q4:(a)(i):1","from":"2023-P2-Q4","q":"Rohan scores 70% of his free throws, and his throws are independent. What is the probability that he scores his first 3 free throws?","right":"0.343","wrong":["0.027","0.49","0.7"],"why":"P(score) = 0.7 each time, and the throws are independent, so multiply: 0.7 × 0.7 × 0.7 = 0.343. (0.027 is missing all three.)","hook":"Independent, and all three must happen: multiply three times.","keys":["0.7 × 0.7 × 0.7 = 0.343"]},{"id":"2023-P2-Q4:(a)(ii):1","from":"2023-P2-Q4","q":"Rohan scores 70% of his free throws, independently. What is the probability that he scores exactly 2 of his first 3 free throws?","right":"0.441","wrong":["0.147","0.189","0.294"],"why":"A miss is 1 − 0.7 = 0.3. One order: 0.7 × 0.7 × 0.3 = 0.147. The miss can be 1st, 2nd or 3rd (SSF, SFS, FSS), so 3 × 0.147 = 0.441.","hook":"Exactly 2 of 3: one order's chance × 3.","keys":["3 × 0.147 = 0.441"]},{"id":"2023-P2-Q4:(a)(ii):2","from":"2023-P2-Q4","q":"Rohan scores each free throw with probability 0.7. Why is 0.7 × 0.7 × 0.3 = 0.147 not the answer to \"exactly 2 of his first 3\"?","right":"It is only one order: score, score, miss","wrong":["It leaves out 0.343 for all three","The 0.3 should be another 0.7","They should be added, not multiplied"],"why":"0.147 is the chance of S, S, F in that order. SFS and FSS also give exactly 2 scores, each 0.147, so the answer is 3 × 0.147 = 0.441.","hook":"Same chance for each order? Multiply by how many orders.","keys":["SFS and FSS also give exactly 2 scores"]},{"id":"2023-P2-Q4:(a)(iii):1","from":"2023-P2-Q4","q":"Give one reason why Rohan scoring his free throws might not be independent events.","right":"A miss may make him nervous next time","wrong":["He scores 70% of his throws","Every throw has the same 0.7 chance","Each throw is either a score or a miss"],"why":"Independent means one throw doesn't change the chance of the next. But earlier throws can affect him: a miss may make him nervous, a score more confident.","hook":"Not independent = one result changes the next one's chance.","keys":["one throw doesn't change the chance of the next"]},{"id":"2023-P2-Q10:(a):1","from":"2023-P2-Q10","q":"A regular pentagon ABCDE is split into five congruent isosceles triangles meeting at its centre O, and |∠BOC| = 72°. Find |∠CBA|.","right":"108°","wrong":["54°","72°","36°"],"why":"|OB| = |OC|, so triangle BOC's base angles are (180° − 72°) ÷ 2 = 54°. ∠CBA is two of them, ∠OBC + ∠OBA: 54° + 54° = 108°.","hook":"Isosceles: the two base angles are equal; share what's left of 180°.","keys":["(180° − 72°) ÷ 2 = 54°","54° + 54° = 108°"]},{"id":"2023-P2-Q10:(c)(i):1","from":"2023-P2-Q10","q":"A spinner numbered 1 to 5 is spun twice, and each number landed on is recorded. How many outcomes are in the sample space?","right":"25","wrong":["10","15","9"],"why":"Each of the 5 first spins goes with each of the 5 second spins: 5 × 5 = 25 pairs, (1,1) to (5,5). (1,2) and (2,1) are different outcomes.","hook":"Two-way table: rows × columns.","keys":["5 × 5 = 25"]},{"id":"2023-P2-Q10:(c)(ii):1","from":"2023-P2-Q10","q":"A spinner numbered 1 to 5 is spun twice and the two numbers are added. What are the maximum and minimum possible totals?","right":"Max 10, min 2","wrong":["Max 9, min 3","Max 25, min 1","Max 5, min 1"],"why":"The same number can come up on both spins. Biggest: 5 + 5 = 10. Smallest: 1 + 1 = 2.","hook":"Spun twice: the same number can come up both times.","keys":["5 + 5 = 10","1 + 1 = 2"]},{"id":"2023-P2-Q10:(c)(iii):1","from":"2023-P2-Q10","q":"A spinner numbered 1 to 5 (each equally likely) is spun twice and the two numbers are added. What is the probability of a total of either 4 or 5?","right":"7/25","wrong":["2/9","12/625","4/15"],"why":"Total 4: (1,3), (2,2), (3,1): 3 ways. Total 5: (1,4), (2,3), (3,2), (4,1): 4 ways. 3 + 4 = 7 of the 25 outcomes: 7/25 = 0.28.","hook":"Count outcomes in the 25-cell table, not totals.","keys":["3 + 4 = 7 of the 25 outcomes"]},{"id":"2023-P2-Q10:(d):1","from":"2023-P2-Q10","q":"Jena pays €1 to spin. N: probability 0.3, she gets €1. S: 0.2, €0.50. E: 0.4, €0. W: 0.1, €5. What is the expected value of the money she gets?","right":"€0.90","wrong":["€1.63","€6.50","€0.40"],"why":"E(x) = Σ x·P(x) = 1(0.3) + 0.5(0.2) + 0(0.4) + 5(0.1) = 0.3 + 0.1 + 0 + 0.5 = €0.90.","hook":"Each amount × its probability, then add all four.","keys":["0.3 + 0.1 + 0 + 0.5 = €0.90"]},{"id":"2023-P2-Q10:(d):2","from":"2023-P2-Q10","q":"Jena pays €1 for each spin, and the expected value of the money she gets back is €0.90. Is the game fair?","right":"No: on average she loses 10c a go","wrong":["Yes: €0.90 is close to €1","Yes: the probabilities add up to 1","No: she gets nothing 40% of the time"],"why":"A fair game gives back, on average, what you pay. She pays €1 and expects €0.90 back: €0.90 < €1, so she loses 10c a go. Not fair.","hook":"Fair: the expected payout equals the cost to play.","keys":["€0.90 < €1"]},{"id":"2024-P2-Q2:(b):1","from":"2024-P2-Q2","q":"Seán has 14 cards: green G1 to G7 and red R1 to R7. A card is chosen at random. What is the probability that it has an even number?","right":"3/7","wrong":["3/14","4/7","1/2"],"why":"Even numbers are 2, 4 and 6 in both colours: G2, G4, G6, R2, R4, R6. That's 6 of the 14 cards: 6/14 = 3/7. (1 to 7 has more odds than evens.)","hook":"List the cards that fit, in every colour.","keys":["6/14 = 3/7"]},{"id":"2024-P2-Q2:(c):1","from":"2024-P2-Q2","q":"Seán's 14 cards: G1–G7 and R1–R7. He picks a card, Red 5, and doesn't put it back. He then picks a second card at random. What is the probability that it is green?","right":"7/13","wrong":["7/14","6/13","1/26"],"why":"R5 is not put back, so 13 cards are left. It wasn't green, so all 7 greens are still there: P(green) = 7/13.","hook":"Without replacement: the total goes down by one.","keys":["13 cards are left","7/13"]},{"id":"2024-P2-Q2:(d):1","from":"2024-P2-Q2","q":"Seán's 14 cards: G1–G7 and R1–R7. He picks a card, doesn't replace it, then picks a second. What is the probability the 2nd is a different colour and a different number?","right":"6/13","wrong":["7/13","6/14","12/13"],"why":"Say the first is G3: 13 cards are left. A different colour means a red card (7), and a different number rules out R3: 7 − 1 = 6. So 6/13.","hook":"Without replacement, two conditions: count the cards left that fit both.","keys":["7 − 1 = 6","6/13"]},{"id":"2024-P2-Q5:(b)(i):1","from":"2024-P2-Q5","q":"Owen gets the recommended amount of sleep 10% of the time. What is the probability that he does not get the recommended amount of sleep on a particular night?","right":"0.9","wrong":["0.1","90","0.09"],"why":"10% = 0.1 is the chance he does get enough sleep. Enough or not enough: they add to 1, so P(not) = 1 − 0.1 = 0.9 (that is 90%).","hook":"Change % to a decimal first, then use 1 − P.","keys":["1 − 0.1 = 0.9"]},{"id":"2024-P2-Q5:(b)(ii):1","from":"2024-P2-Q5","q":"Owen gets enough sleep on a night with probability 0.1, independently each night. Starting Sunday, what is the probability that Tuesday (the 3rd night) is the first night with enough sleep?","right":"0.081","wrong":["0.009","0.243","0.729"],"why":"First time on Tuesday: Sunday no, Monday no, Tuesday yes. The nights are independent, so multiply: 0.9 × 0.9 × 0.1 = 0.081.","hook":"First success on the 3rd try: fail × fail × success.","keys":["0.9 × 0.9 × 0.1 = 0.081"]},{"id":"2024-P2-Q9:(b)(i):1","from":"2024-P2-Q9","q":"100 customers: 42 bought vanilla (V), 37 bought a cone (C), and 45 bought neither vanilla nor a cone. How many bought vanilla in a cone (both)?","right":"24","wrong":["79","55","34"],"why":"100 − 45 = 55 are inside the circles. 42 + 37 = 79 counts the overlap twice, so 79 − 55 = 24 bought both. Then V only 18 and C only 13.","hook":"Both circles added − people inside = the overlap.","keys":["79 − 55 = 24"]},{"id":"2024-P2-Q9:(b)(i):2","from":"2024-P2-Q9","q":"100 customers: 42 bought vanilla, 37 a cone, 45 neither. Why is 42 + 37 = 79 more than the 55 people inside the two circles?","right":"Those who bought both were counted twice","wrong":["The 45 outside were counted as well","Vanilla and cones are independent","Some customers bought two ice creams"],"why":"Anyone with vanilla in a cone is in the 42 and in the 37, so adding counts those people twice. The extra, 79 − 55 = 24, is the overlap.","hook":"Adding two circles counts the overlap twice.","keys":["counts those people twice"]},{"id":"2024-P2-Q9:(b)(ii):1","from":"2024-P2-Q9","q":"Venn diagram of 100 customers: vanilla only 18, vanilla and cone 24, cone only 13, neither 45. What is P(a customer bought a cone with a flavour other than vanilla)?","right":"13/100","wrong":["37/100","24/100","58/100"],"why":"A cone but not vanilla is the cone-only region: 13 of the 100 customers, so 13/100 = 0.13. The 24 in the overlap had vanilla.","hook":"\"A but not B\" = the part of A's circle outside B.","keys":["13/100 = 0.13"]},{"id":"2024-P2-Q9:(c):1","from":"2024-P2-Q9","q":"Typical Sunday sales: wet €150 (probability 30%), dry and cold €200 (45%), dry and warm €450 (25%). What is the expected value of next Sunday's sales?","right":"€247.50","wrong":["€266.67","€24 750","€200.00"],"why":"Percentages to decimals, then Σ x·P(x): 150(0.3) + 200(0.45) + 450(0.25) = 45 + 90 + 112.5 = €247.50.","hook":"Percentages → decimals before you multiply.","keys":["45 + 90 + 112.5 = €247.50"]},{"id":"2024-P2-Q9:(d)(ii):1","from":"2024-P2-Q9","q":"In the logo, a right-angled triangle has a 70° angle at the centre, the 20 cm radius next to that angle (adjacent) and side l opposite it. Find l, to the nearest cm.","right":"55 cm","wrong":["19 cm","58 cm","7 cm"],"why":"Opposite and adjacent: use tan. tan 70° = l/20, so l = 20 tan 70° = 54.9… ≈ 55 cm (calculator in degrees).","hook":"SOH CAH TOA: opposite and adjacent → tan.","keys":["l = 20 tan 70° = 54.9…"]},{"id":"2024-P2-Q9:(d)(ii):2","from":"2024-P2-Q9","q":"A right-angled triangle has a 70° angle. The side next to it (adjacent) is 20 cm, and side l is opposite it. Which equation gives l?","right":"tan 70° = l/20","wrong":["sin 70° = l/20","cos 70° = 20/l","tan 70° = 20/l"],"why":"tan = opposite ÷ adjacent. l is opposite the 70° and 20 is adjacent, so tan 70° = l/20. (cos 70° = 20/l would find the hypotenuse.)","hook":"TOA: Tan = Opposite ÷ Adjacent.","keys":["tan = opposite ÷ adjacent"]},{"id":"2025-P2-Q7:(a)(i):1","from":"2025-P2-Q7","q":"Seán wins match 1 with probability 0.6 and match 2 with probability 0.7, independently. On a tree diagram, what goes on the \"Win match 2\" branch after he loses match 1?","right":"0.7","wrong":["0.3","0.4","0.28"],"why":"The matches are independent, so match 2's chances don't depend on match 1: Win 0.7 (and Lose 0.3), after a win or after a loss.","hook":"Independent: the second set of branches is the same every time.","keys":["match 2's chances don't depend on match 1"]},{"id":"2025-P2-Q7:(a)(ii):1","from":"2025-P2-Q7","q":"Tree: match 1 Win 0.6, Lose 0.4; match 2 Win 0.7, Lose 0.3 (independent). Win-Win = 0.42 and Lose-Lose = 0.12. What are Win-Lose and Lose-Win?","right":"W-L 0.18, L-W 0.28","wrong":["W-L 0.28, L-W 0.18","W-L 0.3, L-W 0.7","W-L 0.23, L-W 0.23"],"why":"Multiply along each path: W-L = 0.6 × 0.3 = 0.18 and L-W = 0.4 × 0.7 = 0.28. Check: 0.42 + 0.18 + 0.28 + 0.12 = 1.","hook":"Along a path: multiply. The ends of the tree add up to 1.","keys":["0.6 × 0.3 = 0.18","0.4 × 0.7 = 0.28"]},{"id":"2025-P2-Q7:(a)(iii):1","from":"2025-P2-Q7","q":"Two matches: P(Win-Win) = 0.42, P(Win-Lose) = 0.18, P(Lose-Win) = 0.28, P(Lose-Lose) = 0.12. What is the probability that Seán wins at least 1 match?","right":"0.88","wrong":["0.46","0.12","0.58"],"why":"At least 1 win is every outcome except Lose-Lose: 1 − 0.12 = 0.88. (Or 0.42 + 0.18 + 0.28 = 0.88: Win-Win counts too.)","hook":"At least one = 1 − none.","keys":["1 − 0.12 = 0.88"]},{"id":"2025-P2-Q7:(a)(iii):2","from":"2025-P2-Q7","q":"Seán plays two matches and wins or loses each. What is the quickest way to find the probability that he wins at least 1 match?","right":"1 − P(lose both)","wrong":["1 − P(win both)","P(W-L) + P(L-W)","P(win 1st) + P(win 2nd)"],"why":"\"At least 1 win\" leaves out only Lose-Lose, so take that from 1. P(W-L) + P(L-W) is exactly one win; 0.6 + 0.7 = 1.3 is more than 1.","hook":"At least one? 1 − P(none).","keys":["leaves out only Lose-Lose"]},{"id":"2025-P2-Q7:(b)(i):1","from":"2025-P2-Q7","q":"Each time Sarah plays a service game, the probability that she wins it is 0.78. What is the probability that she loses her next service game?","right":"0.22","wrong":["0.78","22","0.022"],"why":"Each game she either wins or loses, so P(lose) = 1 − P(win) = 1 − 0.78 = 0.22.","hook":"Win or lose, nothing else: P(lose) = 1 − P(win).","keys":["1 − 0.78 = 0.22"]},{"id":"2025-P2-Q7:(b)(ii):1","from":"2025-P2-Q7","q":"Sarah wins each service game with probability 0.78, independently. What is the probability that the first service game she loses is her third, to 3 decimal places?","right":"0.134","wrong":["0.038","0.402","0.475"],"why":"First loss on game 3: win, win, lose. 0.78 × 0.78 × 0.22 = 0.133848 ≈ 0.134. One order only: no × 3.","hook":"First loss on game 3: win, win, lose.","keys":["0.78 × 0.78 × 0.22 = 0.133848"]},{"id":"2025-P2-Q7:(d):1","from":"2025-P2-Q7","q":"A team had 15 shots: 6 with a 10% chance of a goal, 5 with 20%, 3 with 40% and 1 with 70%. What are the Expected Goals (the expected number of goals)?","right":"3.5","wrong":["1.4","350","0.23"],"why":"Each shot is worth its probability in goals: 6(0.1) + 5(0.2) + 3(0.4) + 1(0.7) = 0.6 + 1 + 1.2 + 0.7 = 3.5 goals.","hook":"Expected number = Σ (how many × probability).","keys":["0.6 + 1 + 1.2 + 0.7 = 3.5"]},{"id":"2019-P2-Q1:(c)(i):1","from":"2019-P2-Q1","q":"A business has 28 employees. The youngest rows of its stem-and-leaf diagram are 1 | 8 8 9 and 2 | 0 1 1 2 (key 1|9 = 19 years). One employee is chosen at random. P(teenager, under 20)?","right":"3/28","wrong":["2/28","4/28","3/25"],"why":"Under 20 means the 1 row only: 18, 18 and 19, so 3 people. P = 3 ÷ all 28 employees = 3/28. Someone aged 20 is not a teenager.","hook":"Probability = how many fit ÷ how many there are in total.","keys":["3 ÷ all 28 employees"]},{"id":"2019-P2-Q1:(c)(ii):1","from":"2019-P2-Q1","q":"28 employees; rows 3 | 2 3 3 4 4 5 9 and 4 | 1 2 3 3 9 (key 1|9 = 19). One is picked at random. P(in their thirties with an even age, or in their forties with an odd age)?","right":"7/28 (= 1/4)","wrong":["3/196","5/28","7/12"],"why":"Thirties, even: 32, 34, 34 (3). Forties, odd: 41, 43, 43, 49 (4). Nobody is in both, so add: 3/28 + 4/28 = 7/28 = 1/4.","hook":"'Or' with no overlap: add the probabilities.","keys":["3/28 + 4/28 = 7/28"]},{"id":"2019-P2-Q1:(c)(ii):2","from":"2019-P2-Q1","q":"One of 28 employees is picked. P(thirties and an even age) = 3/28 and P(forties and an odd age) = 4/28. How do you find P(one or the other)?","right":"Add them: no one is in both groups","wrong":["Multiply them: 3/28 × 4/28","Add, then take away 3/28 × 4/28","Find their mean: (3/28 + 4/28) ÷ 2"],"why":"Nobody can be in their thirties and their forties, so the groups are mutually exclusive: P(A or B) = P(A) + P(B), with no overlap to take away.","hook":"OR with no overlap: add. AND for independent events: multiply.","keys":["mutually exclusive"]},{"id":"2022-P2-Q7:(c)(i):1","from":"2022-P2-Q7","q":"A shelter has 5 male and 9 female cats, and 11 male and 15 female dogs: 40 animals. One animal is picked at random. What is the probability that it is a cat?","right":"14/40 (= 7/20)","wrong":["14/26","1/2","26/40"],"why":"Probability = cats ÷ all animals = 14/40 = 7/20. Cats and dogs aren't equally likely, because there are more dogs.","hook":"Divide by everything you could pick, not by the other group.","keys":["14/40 = 7/20"]},{"id":"2022-P2-Q7:(c)(ii):1","from":"2022-P2-Q7","q":"A shelter has 40 animals: 16 males, of which 11 are male dogs. Three different animals are picked at random. Find the probability that all three are male dogs, to 3 decimal places.","right":"0.017","wrong":["0.021","0.057","0.015"],"why":"No animal is picked twice, so both counts drop each time: 11/40 × 10/39 × 9/38 = 0.01670… ≈ 0.017.","hook":"AND over several picks: multiply the fractions.","keys":["11/40 × 10/39 × 9/38"]},{"id":"2022-P2-Q7:(c)(ii):2","from":"2022-P2-Q7","q":"A shelter has 40 animals, 11 of them male dogs. The first animal picked (and kept out) is a male dog. What is the probability the second one picked is also a male dog?","right":"10/39","wrong":["11/40","10/40","11/39"],"why":"One male dog has gone, so there are 10 male dogs left out of 39 animals: 10/39.","hook":"Picked animals don't go back: one fewer of that kind AND one fewer in total.","keys":["10 male dogs left out of 39 animals"]},{"id":"2022-P2-Q7:(e):1","from":"2022-P2-Q7","q":"A shelter had 14 cats and 26 dogs. During the week 10 animals left and none came in. Now the probability of picking a dog is 11/15. How many cats left the shelter?","right":"6","wrong":["8","4","22"],"why":"30 animals remain. Dogs: 11/15 × 30 = 22, so the cats still there: 30 − 22 = 8. The cats that left: 14 − 8 = 6.","hook":"Work out what's left first, then compare with the start.","keys":["14 − 8 = 6"]}],"14":[{"id":"2018-P2-Q9:(b)(i):1","from":"2018-P2-Q9","q":"A random sample of 1560 television viewers was surveyed. What is the margin of error of the survey, as a percentage to 1 decimal place?","right":"2.5%","wrong":["0.1%","5.0%","4.3%"],"why":"Margin of error = 1/√n = 1/√1560 = 0.0253… = 2.5%.","hook":"Margin of error: one over root n.","keys":["1/√n = 1/√1560"]},{"id":"2018-P2-Q9:(b)(ii):1","from":"2018-P2-Q9","q":"In a survey of 1560 viewers (margin of error 2.5%), 546 said they liked the show. What is the 95% confidence interval for the percentage who like it?","right":"32.5% to 37.5%","wrong":["35% to 37.5%","30% to 40%","33.75% to 36.25%"],"why":"Sample proportion: 546 ÷ 1560 = 0.35 = 35%. Go 2.5% either side: 35 − 2.5 to 35 + 2.5, so 32.5% to 37.5%.","hook":"Confidence interval: sample % ± margin of error.","keys":["546 ÷ 1560 = 0.35 = 35%","2.5% either side"]},{"id":"2018-P2-Q9:(b)(iii):1","from":"2018-P2-Q9","q":"An executive claims 40% of viewers like a show. A survey found 35% liked it. To test the claim, what is the null hypothesis?","right":"H₀: p = 40%","wrong":["H₀: p ≠ 40%","H₀: p = 35%","H₀: p > 40%"],"why":"The null hypothesis is the claim being tested: H₀: p = 40%. The alternative is H₁: p ≠ 40%.","hook":"H₀ is the claim (an \"equals\"); H₁ says it is wrong.","keys":["the claim being tested"]},{"id":"2018-P2-Q9:(b)(iii):2","from":"2018-P2-Q9","q":"H₀: 40% of viewers like a show. The 95% confidence interval from a survey is 32.5% to 37.5%. What is the conclusion at the 5% level?","right":"Reject H₀: 40% is outside the interval","wrong":["Don’t reject H₀: 40% is outside it","Don’t reject H₀: 40% is near 37.5%","Don’t reject H₀: 35% is inside it"],"why":"40% is not in [32.5%, 37.5%], so reject H₀: the evidence suggests the percentage who like the show is not 40%.","hook":"Claim inside the interval: keep it. Outside: reject it.","keys":["40% is not in [32.5%, 37.5%]"]},{"id":"2019-P2-Q8:(b)(i):1","from":"2019-P2-Q8","q":"A class surveyed a random sample of 800 people. What is the margin of error of the survey, as a percentage to 2 decimal places?","right":"3.54%","wrong":["0.13%","6.93%","5.35%"],"why":"Margin of error = 1/√n = 1/√800 = 0.035355… = 3.54%.","hook":"Margin of error = 1 ÷ √(sample size).","keys":["1/√n = 1/√800"]},{"id":"2019-P2-Q8:(b)(ii):1","from":"2019-P2-Q8","q":"In a random sample of 800 people (margin of error 3.54%), 350 supported a proposal. What is the 95% confidence interval for the percentage who support it?","right":"40.21% to 47.29%","wrong":["36.67% to 50.83%","52.71% to 59.79%","43.75% to 47.29%"],"why":"Sample %: 350 ÷ 800 = 43.75%. Then 43.75 − 3.54 to 43.75 + 3.54: 40.21% to 47.29%.","hook":"Centre on the sample %, then go the margin of error each way.","keys":["350 ÷ 800 = 43.75%","43.75 − 3.54 to 43.75 + 3.54"]},{"id":"2019-P2-Q8:(b)(iii):1","from":"2019-P2-Q8","q":"A newspaper claims 50% support a proposal. A survey gives a 95% confidence interval of 40.21% to 47.29%. What do you conclude at the 5% level?","right":"Reject the claim: 50% is outside it","wrong":["Don’t reject: 50% is outside it","Don’t reject: 43.75% is inside it","Don’t reject: 50% is within 3.54% of it"],"why":"H₀: support is 50%. 50% is not in 40.21% to 47.29%, so reject H₀: support in the area is not 50%.","hook":"Test the CLAIM against the interval: outside means reject.","keys":["50% is not in 40.21% to 47.29%"]},{"id":"2022-P2-Q3:(a)(i):1","from":"2022-P2-Q3","q":"Find the mean of these 7 numbers, correct to 1 decimal place: 17, 8, 9, 8, 14, 11, 28.","right":"13.6","wrong":["11.0","13.5","14.5"],"why":"Add all 7 numbers, both 8s included: 95. Divide by 7: 95 ÷ 7 = 13.571…, and the next digit (7) rounds up: 13.6.","hook":"Mean = total ÷ how many. Every value counts, repeats too.","keys":["95 ÷ 7 = 13.571…"]},{"id":"2022-P2-Q3:(a)(ii):1","from":"2022-P2-Q3","q":"Find the median of these 7 numbers: 17, 8, 9, 8, 14, 11, 28.","right":"11","wrong":["8","13.6","18"],"why":"In order: 8, 8, 9, 11, 14, 17, 28. With 7 numbers the median is the (7 + 1) ÷ 2 = 4th one: 11. (13.6 is the mean.)","hook":"Median: put them in order first, then take the middle one.","keys":["8, 8, 9, 11, 14, 17, 28","4th one: 11"]},{"id":"2022-P2-Q3:(a)(ii):2","from":"2022-P2-Q3","q":"To find the median of 17, 8, 9, 8, 14, 11, 28, what must you do first?","right":"Put the numbers in order","wrong":["Add them and divide by 7","Cross out the repeated 8","Find halfway between 8 and 28"],"why":"The median is the middle value of the ordered list, so sort first: 8, 8, 9, 11, 14, 17, 28. Keep both 8s: every value counts.","hook":"Median = middle of the sorted list.","keys":["sort first"]},{"id":"2022-P2-Q3:(a)(iii):1","from":"2022-P2-Q3","q":"The list 8, 8, 9, 11, 14, 17, 28 has median 11. One more number is added, and the new median is 10.5. What number was added?","right":"10","wrong":["10.5","12","21"],"why":"8 numbers: the median is halfway between the 4th and 5th. The new number x sits between 9 and 11, so (x + 11) ÷ 2 = 10.5, x + 11 = 21, x = 10.","hook":"Even count: the median is the average of the two middle numbers.","keys":["(x + 11) ÷ 2 = 10.5","x = 10"]},{"id":"2022-P2-Q3:(a)(iii):2","from":"2022-P2-Q3","q":"A list of numbers in order now has 8 numbers. Where is its median?","right":"Halfway between the 4th and 5th","wrong":["The 4th number","The 5th number","Halfway between the 1st and 8th"],"why":"(8 + 1) ÷ 2 = 4.5, so the median is halfway between the 4th and 5th numbers of the ordered list: add those two and halve.","hook":"Odd count: the middle one. Even count: the average of the middle two.","keys":["(8 + 1) ÷ 2 = 4.5"]},{"id":"2023-P2-Q3:(b)(i):1","from":"2023-P2-Q3","q":"Scatterplot A: points go down, close to a line. B: points go up, close to a line. C: points go up but are spread out. Match them to r = 0.95, 0.6 and −0.95.","right":"0.95: B, 0.6: C, −0.95: A","wrong":["0.95: C, 0.6: B, −0.95: A","0.95: A, 0.6: C, −0.95: B","0.95: B, 0.6: A, −0.95: C"],"why":"A goes down, so it is the negative one: −0.95. B and C go up; B's points hug a line, so B is 0.95, and the spread-out C is 0.6.","hook":"Sign = direction. Size = how tightly the points hug a line.","keys":["A goes down","B is 0.95"]},{"id":"2023-P2-Q3:(b)(i):2","from":"2023-P2-Q3","q":"Three scatterplots have correlation coefficients 0.95, 0.6 and −0.95. How do you spot the one with r = −0.95?","right":"Its points go down from left to right","wrong":["Its points are the most spread out","Its points are closest to the x-axis","Its points go up most steeply"],"why":"A negative r means y goes down as x goes up. −0.95 is also close to −1, so its points go downhill and sit close to a straight line.","hook":"Minus sign = downhill.","keys":["A negative r means y goes down as x goes up"]},{"id":"2023-P2-Q3:(b)(ii):1","from":"2023-P2-Q3","q":"Scatterplot B: the points go up and lie close to a straight line, and r = 0.95. What must a full explanation of why 0.95 is right say?","right":"Positive, and points close to a line","wrong":["Positive: as x goes up, y goes up","The points rise along a steep line","There are lots of points in the plot"],"why":"Say both: the direction (as x goes up, y goes up: positive) and the strength (the points lie close to a straight line: strong). So r is close to +1.","hook":"Explain r with two things: direction and strength.","keys":["the direction","the strength"]},{"id":"2023-P2-Q4:(b):1","from":"2023-P2-Q4","q":"Points Rohan scored (number of games): 0 (4 games), 6 (5), 8 (4), 10 (2), 12 (3), 16 (1). Find his mean number of points per game, to 2 decimal places.","right":"7.05","wrong":["22.33","8.67","8.93"],"why":"Total points = 4(0) + 5(6) + 4(8) + 2(10) + 3(12) + 1(16) = 134. Games = 4 + 5 + 4 + 2 + 3 + 1 = 19. Mean = 134 ÷ 19 = 7.05.","hook":"Mean from a frequency table: Σfx ÷ Σf.","keys":["134 ÷ 19 = 7.05"]},{"id":"2023-P2-Q4:(b):2","from":"2023-P2-Q4","q":"Rohan's frequency table gives a total of 134 points over all his games. To find his mean points per game, what do you divide 134 by?","right":"19, the total number of games","wrong":["6, the number of columns","52, the total of the point values","15, the games where he scored"],"why":"The mean is per game, so divide by the number of games: 4 + 5 + 4 + 2 + 3 + 1 = 19, including the 4 games where he scored 0.","hook":"Divide by Σf (how many games), not by the number of columns.","keys":["divide by the number of games"]},{"id":"2024-P2-Q5:(a)(i):1","from":"2024-P2-Q5","q":"Hours of sleep are normally distributed, and the middle 68% slept between 7.2 and 8.4 hours. Which values go in the axis boxes: left of 7.2, in the middle, right of 8.4?","right":"6.6, 7.8, 9.0","wrong":["6.0, 7.8, 9.6","5.4, 7.8, 10.2","6.9, 7.8, 8.7"],"why":"68% is μ ± σ, so μ = (7.2 + 8.4) ÷ 2 = 7.8 and 2σ = 8.4 − 7.2 = 1.2, so σ = 0.6. The outer boxes are μ ± 2σ: 6.6 and 9.0.","hook":"Empirical rule: 68% within 1σ, 95% within 2σ, 99.7% within 3σ.","keys":["σ = 0.6","6.6 and 9.0"]},{"id":"2024-P2-Q5:(a)(i):2","from":"2024-P2-Q5","q":"On a normal curve with mean μ and standard deviation σ, the middle 68% of the data lies between which two values?","right":"μ − σ and μ + σ","wrong":["μ and μ + σ","μ − 2σ and μ + 2σ","μ − 3σ and μ + 3σ"],"why":"The empirical rule: about 68% lie within 1 standard deviation of the mean (μ ± σ), 95% within 2 (μ ± 2σ) and 99.7% within 3 (μ ± 3σ).","hook":"68 – 95 – 99.7 for 1σ – 2σ – 3σ.","keys":["within 1 standard deviation of the mean"]},{"id":"2024-P2-Q5:(a)(ii):1","from":"2024-P2-Q5","q":"Sleep is normally distributed with mean 7.8 hours and standard deviation 0.6 hours. Using the empirical rule, what percentage got at least 9 hours of sleep?","right":"2.5%","wrong":["5%","97.5%","16%"],"why":"9 = 7.8 + 2(0.6) = μ + 2σ. 95% lie between 6.6 and 9.0; the other 5% splits equally between the two ends, so 2.5% got 9 hours or more.","hook":"Only one end? Halve what's outside.","keys":["μ + 2σ","2.5%"]},{"id":"2015-P2-Q6:(a)(i):1","from":"2015-P2-Q6","q":"On a scatter graph you must mark ten or more points to show strong positive correlation. Which pattern of points should you draw?","right":"Up to the right, close to a line","wrong":["Up to the right, loosely spread","Down to the right, close to a line","Very steep, however spread out"],"why":"Positive: the points go up as you move right. Strong: they all lie close to one straight line. Steepness doesn't matter; the spread does.","hook":"Direction gives the sign; closeness to a line gives the strength.","keys":["close to one straight line"]},{"id":"2015-P2-Q6:(a)(ii):1","from":"2015-P2-Q6","q":"A scatter graph shows strong negative correlation between x and y. Which description fits it?","right":"y falls as x rises, close to a line","wrong":["y rises as x rises, close to a line","y falls as x rises, widely spread","Points have negative x and y values"],"why":"Negative describes the direction: the points fall from top left to bottom right. It has nothing to do with negative numbers. Strong means close to one line.","hook":"Negative = downhill, left to right. It's about slope, not minus numbers.","keys":["fall from top left to bottom right"]},{"id":"2015-P2-Q6:(a)(iii):1","from":"2015-P2-Q6","q":"You must mark ten or more points on a scatter graph to show no correlation. Which set of points does that?","right":"Spread all over with no trend up or down","wrong":["Down to the right, close to a line","Up to the right, loosely spread","Down to the right, loosely spread"],"why":"No correlation: knowing x tells you nothing about y, so the dots fill the grid with no trend. Going down is negative; loosely spread is weak, not none.","hook":"No correlation = no trend at all. Weak and negative are still trends.","keys":["no trend"]},{"id":"2015-P2-Q6:(b)(i):1","from":"2015-P2-Q6","q":"A poll of 1000 people estimated support for the ‘No’ campaign at 54%. Find the margin of error, as a percentage correct to one decimal place.","right":"3.2%","wrong":["0.1%","31.6%","0.03%"],"why":"Margin of error = 1/√n = 1/√1000 = 0.0316… Multiply by 100 for a percentage: 3.2%.","hook":"Margin of error: one over root n, then × 100 for a %.","keys":["1/√n = 1/√1000"]},{"id":"2015-P2-Q6:(b)(i):2","from":"2015-P2-Q6","q":"At the 95% confidence level, which formula gives the margin of error of a survey of n people?","right":"1/√n","wrong":["1/n","√n","2/√n"],"why":"The margin of error is 1/√n. Because of the square root, a bigger sample gives a smaller error, but four times the people only halves it.","hook":"Bigger sample, smaller error: E = 1/√n.","keys":["1/√n"]},{"id":"2015-P2-Q6:(b)(ii):1","from":"2015-P2-Q6","q":"A poll of 1000 people found 54% support ‘No’. The margin of error is 3.2%. What is the 95% confidence interval for the support for ‘No’?","right":"50.8% ≤ p ≤ 57.2%","wrong":["52.4% ≤ p ≤ 55.6%","53.97% ≤ p ≤ 54.03%","47.6% ≤ p ≤ 60.4%"],"why":"Go one whole margin of error below and above the sample result: 54 − 3.2 ≤ p ≤ 54 + 3.2, so 50.8% ≤ p ≤ 57.2%.","hook":"Sample result ± the whole margin of error, on each side.","keys":["54 − 3.2 ≤ p ≤ 54 + 3.2"]},{"id":"2015-P2-Q6:(b)(ii):2","from":"2015-P2-Q6","q":"From a poll of 1000 people, the 95% confidence interval for support for ‘No’ is 50.8% ≤ p ≤ 57.2%. What does this tell you?","right":"95% confident the true % is in it","wrong":["95% of all voters support ‘No’","Exactly 54% of all voters support ‘No’","The poll's 54% is 95% accurate"],"why":"The poll is only a sample. We are 95% confident that the true support among all voters lies between 50.8% and 57.2%; 54% is just the sample's estimate.","hook":"A confidence interval traps the true population value, with 95% confidence.","keys":["95% confident"]},{"id":"2019-P2-Q1:(a):1","from":"2019-P2-Q1","q":"A stem-and-leaf diagram of employees' ages has the key 1|9 = 19 years. What ages does the row 6 | 3 3 4 5 show?","right":"63, 63, 64 and 65","wrong":["6.3, 6.3, 6.4 and 6.5","63, 64 and 65","36, 36, 46 and 56"],"why":"The key says the stem is the tens digit and the leaf is the units: 6|3 = 63. Each leaf is one person, so the two 3s are two people aged 63.","hook":"Read the key first: stem = tens, leaf = units. Every leaf is one person.","keys":["6|3 = 63","Each leaf is one person"]},{"id":"2019-P2-Q1:(a):2","from":"2019-P2-Q1","q":"Employees in their fifties are aged 57, 54, 58, 55 and 57 (key 1|9 = 19 years). What is the 5 row of the finished stem-and-leaf diagram, leaves in order?","right":"5 | 4 5 7 7 8","wrong":["5 | 4 5 7 8","5 | 54 55 57 57 58","5 | 7 4 8 5 7"],"why":"Each age gives one leaf, its units digit. In order: 4 5 7 7 8. Both 57s are written, one leaf for each person.","hook":"One leaf per person, units digit only, smallest next to the stem.","keys":["one leaf for each person"]},{"id":"2019-P2-Q1:(b):1","from":"2019-P2-Q1","q":"Ages of 28 employees (key 1|9 = 19): 1|8 8 9, 2|0 1 1 2, 3|2 3 3 4 4 5 9, 4|1 2 3 3 9, 5|4 5 7 7 8, 6|3 3 4 5. What percentage of the employees are older than 40?","right":"50%","wrong":["14%","39.3%","17.9%"],"why":"Older than 40 means the 4, 5 and 6 rows (nobody is exactly 40): 5 + 5 + 4 = 14 leaves. 14/28 × 100 = 50%.","hook":"Count leaves, not different values, then ÷ total × 100.","keys":["14/28 × 100 = 50%"]},{"id":"2020-P2-Q8:(a)(i):1","from":"2020-P2-Q8","q":"In 2005, 2779 kilotonnes of waste were collected and 1833 kilotonnes of it were sent to landfill. What percentage of the waste collected was sent to landfill?","right":"66.0%","wrong":["151.6%","34.0%","39.7%"],"why":"Percentage = part ÷ whole × 100. The landfill waste is part of the waste collected: 1833 ÷ 2779 × 100 = 65.96… ≈ 66.0%.","hook":"Part over whole, times 100. The whole is what it's 'a percentage of'.","keys":["1833 ÷ 2779 × 100"]},{"id":"2020-P2-Q8:(a)(i):2","from":"2020-P2-Q8","q":"Waste (kilotonnes): 2005: 2779 collected, 1833 to landfill. 2011: 2547 collected, 1344 to landfill. Find the difference between the two years' landfill percentages, to 1 d.p.","right":"13.2%","wrong":["17.6%","26.7%","37.9%"],"why":"Work out each year's percentage first: 1833/2779 × 100 = 65.96% and 1344/2547 × 100 = 52.77%. Then subtract: 13.19… ≈ 13.2%.","hook":"Each year has its own total: find both percentages, then subtract.","keys":["Work out each year's percentage first"]},{"id":"2020-P2-Q8:(a)(ii):1","from":"2020-P2-Q8","q":"Total waste collected (kilotonnes), 2005 to 2011: 2779, 3100, 3175, 3104, 2825, 2580, 2547. Find the mean amount collected each year, correct to 1 decimal place.","right":"2872.9 kt","wrong":["2825.0 kt","3351.7 kt","2861.0 kt"],"why":"Mean = sum ÷ number of values. 2005 to 2011 is 7 years: 20110 ÷ 7 = 2872.857… ≈ 2872.9 kilotonnes.","hook":"Mean: add them all, divide by how many. Count the years, both ends included.","keys":["20110 ÷ 7"]},{"id":"2020-P2-Q8:(a)(iii):1","from":"2020-P2-Q8","q":"The mean amount of waste sent to landfill in the 4 years from 2009 to 2012 was 1398 kilotonnes. What was the total sent to landfill in those 4 years?","right":"5592 kt","wrong":["349.5 kt","4194 kt","1398 kt"],"why":"Mean = total ÷ 4, so total = mean × 4 = 1398 × 4 = 5592 kilotonnes.","hook":"Know the mean? Multiply by how many to get the total back.","keys":["total = mean × 4"]},{"id":"2020-P2-Q8:(a)(iii):2","from":"2020-P2-Q8","q":"Mean landfill waste for the 4 years 2009 to 2012 was 1398 kilotonnes. 2009: 1724, 2010: 1496, 2011: 1344 kilotonnes. How much waste was sent to landfill in 2012?","right":"1028 kt","wrong":["1398 kt","1521 kt","2372 kt"],"why":"The 4 years total 4 × 1398 = 5592. The three known years add to 1724 + 1496 + 1344 = 4564. So 2012 = 5592 − 4564 = 1028 kilotonnes.","hook":"Total from the mean, minus what you know: the rest is the missing value.","keys":["5592 − 4564 = 1028"]},{"id":"2020-P2-Q8:(b)(i):1","from":"2020-P2-Q8","q":"In 2014 Denmark's energy came from Oil 31%, Solid Fuel 11%, Gas 13%, Electricity 12%, Other 13% and Renewable (left blank). What percentage was renewable?","right":"20%","wrong":["80%","16%","32%"],"why":"One country's row is all of its energy, so it adds to 100%. 31 + 11 + 13 + 12 + 13 = 80, so renewable = 100 − 80 = 20%.","hook":"Parts of a whole add to 100%: the missing part is what's left.","keys":["100 − 80 = 20%"]},{"id":"2020-P2-Q8:(b)(ii):1","from":"2020-P2-Q8","q":"Renewable % of energy in 2014: Austria 25, Bulgaria 8, Cyprus 5, Denmark 20, France 7, Germany 10, Greece 9, Ireland 6, Latvia 31, Luxembourg 4, Malta 2, Netherlands 4, Portugal 21. Which four were lower than Ireland?","right":"Cyprus, Luxembourg, Malta, Netherlands","wrong":["Latvia, Luxembourg, Malta, Netherlands","Austria, Denmark, Latvia, Portugal","Cyprus, France, Luxembourg, Malta"],"why":"Ireland's renewable figure is 6%. Go down the Renewable column for numbers below 6: Cyprus 5, Luxembourg 4, Malta 2 and Netherlands 4.","hook":"Lower means a smaller number in that column, not further down the table.","keys":["numbers below 6"]},{"id":"2020-P2-Q8:(b)(iii):1","from":"2020-P2-Q8","q":"Energy % in 2014 (Renewable, Oil, Solid Fuel, Gas, Electricity, Other): Cyprus 5, 82, 0, 0, 13, 0; Greece 9, 43, 24, 9, 15, 0; Ireland 6, 42, 13, 24, 15, 0; Latvia 31, 26, 1, 20, 11, 11. Which did not use gas?","right":"Cyprus","wrong":["Greece","Ireland","Latvia"],"why":"Not using gas means 0% in the Gas column, the fourth number. Of these four only Cyprus has 0 there (Malta does too). Greece and Ireland have 0 under Other, not Gas.","hook":"Find the right column first, then look for the 0.","keys":["0% in the Gas column"]},{"id":"2020-P2-Q8:(b)(iv):1","from":"2020-P2-Q8","q":"In a pie chart of Ireland's energy, Renewable (6%) has an angle of 22°. Oil is 42%. What is the angle for Oil, correct to the nearest degree?","right":"151°","wrong":["42°","154°","12°"],"why":"100% is the full 360°, so Oil = 42/100 × 360 = 151.2 ≈ 151°. Scaling up the 22° gives 154°, because 22° is itself rounded (6% is 21.6°).","hook":"Angle = percentage ÷ 100 × 360. Start from 360°, not from a rounded angle.","keys":["42/100 × 360 = 151.2"]},{"id":"2020-P2-Q8:(b)(iv):2","from":"2020-P2-Q8","q":"Gas is 24% of Ireland's energy. Which calculation gives the angle of the Gas sector in a pie chart?","right":"24 ÷ 100 × 360","wrong":["24 ÷ 360 × 100","24 ÷ 100 × 180","24 × 360"],"why":"The full circle, 360°, is 100% of the energy, so Gas gets 24/100 of 360°: 24 ÷ 100 × 360 = 86.4 ≈ 86°.","hook":"Fraction of the whole × 360°.","keys":["24/100 of 360°"]},{"id":"2020-P2-Q8:(b)(v):1","from":"2020-P2-Q8","q":"Ireland's energy pie chart: Renewable 22°, Oil 151°, Solid Fuel 47° and Gas 86° are drawn. What angle should the gap left for Electricity measure?","right":"54°","wrong":["76°","15°","306°"],"why":"The angles must fill the circle: 360 − (22 + 151 + 47 + 86) = 360 − 306 = 54°, which is 15% × 3.6. Measure the gap to check.","hook":"All the sectors together make 360°.","keys":["360 − (22 + 151 + 47 + 86)"]},{"id":"2021-P2-Q5:(a):1","from":"2021-P2-Q5","q":"Heights are normally distributed. 95% of the population are between 147.9 cm and 178.7 cm. Using the empirical rule, find the mean and the standard deviation.","right":"mean 163.3 cm, sd 7.7 cm","wrong":["mean 163.3 cm, sd 15.4 cm","mean 163.3 cm, sd 5.1 cm","mean 163.3 cm, sd 30.8 cm"],"why":"Mean: halfway, (147.9 + 178.7) ÷ 2 = 163.3. 95% is μ ± 2σ, so the gap is 4σ: 30.8 ÷ 4 = 7.7 cm.","hook":"Halfway gives the mean; the 95% gap is 4 standard deviations wide.","keys":["30.8 ÷ 4 = 7.7"]},{"id":"2021-P2-Q5:(a):2","from":"2021-P2-Q5","q":"By the empirical rule, between which two values does about 95% of a normal distribution lie (mean μ, standard deviation σ)?","right":"μ − 2σ and μ + 2σ","wrong":["μ − σ and μ + σ","μ − 3σ and μ + 3σ","μ and μ + 2σ"],"why":"About 68% lies within 1σ of the mean, 95% within 2σ and 99.7% within 3σ, each measured on both sides of μ.","hook":"68, 95, 99.7 go with 1, 2, 3 standard deviations, both sides.","keys":["95% within 2σ"]},{"id":"2021-P2-Q5:(b)(i):1","from":"2021-P2-Q5","q":"On a scatter plot, height (cm) goes across and arm span (cm) goes up. Person 13 is 168 cm tall with an arm span of 169 cm. Which point do you plot?","right":"(168, 169)","wrong":["(169, 168)","(13, 169)","(170, 170)"],"why":"Each person is one point (height, arm span): go across to 168 on the height axis, then up to 169. The grid lines are 5 apart, so it goes between them.","hook":"Across first (x), then up (y): (height, arm span).","keys":["(height, arm span)"]},{"id":"2021-P2-Q5:(b)(ii):1","from":"2021-P2-Q5","q":"Height and arm span (cm) of teenagers: (139, 129), (147, 150), (153, 148), (160, 160), (164, 144), (169, 174), (174, 170), (177, 176). Which value best represents the correlation coefficient?","right":"0.9","wrong":["0.2","−0.6","−0.9"],"why":"Taller teenagers have longer arm spans, so r is positive, and the points lie close to a straight line, so it's strong: near 1. That is 0.9.","hook":"Sign = direction (up or down); size = how close to a line (near ±1 is strong).","keys":["r is positive","close to a straight line"]},{"id":"2021-P2-Q5:(b)(iii):1","from":"2021-P2-Q5","q":"The correlation coefficient between height and arm span for twenty teenagers is 0.9. What does it tell you about the relationship?","right":"Strong positive: taller, longer arm span","wrong":["Weak positive: hardly related","Strong negative: taller, shorter span","90% have an arm span equal to height"],"why":"0.9 is close to 1, so the relationship is strong (points near a straight line). It is positive, so as height goes up, arm span tends to go up too.","hook":"Say both: how strong (near 1?) and which way (+ or −), in context.","keys":["0.9 is close to 1"]},{"id":"2022-P2-Q4:(a):1","from":"2022-P2-Q4","q":"Grades: Distinction 8, High Merit 12, Merit 39, Achieved 13 students. In a pie chart, Distinction has 40°. How many degrees does each student get?","right":"5°","wrong":["0.2°","90°","5.625°"],"why":"Total students: 8 + 12 + 39 + 13 = 72. The whole 360° is shared by all 72: 360 ÷ 72 = 5° each. Check: 40 ÷ 8 = 5.","hook":"Degrees per person = 360 ÷ total. Check it against the sector you're given.","keys":["360 ÷ 72 = 5°"]},{"id":"2022-P2-Q4:(a):2","from":"2022-P2-Q4","q":"Grades: Distinction 8, High Merit 12, Merit 39, Achieved 13 students. Distinction's pie-chart sector is 40°. What angle is the Merit sector?","right":"195°","wrong":["39°","54°","140°"],"why":"Each student is worth 360 ÷ 72 = 5° (and 40 ÷ 8 = 5 agrees), so Merit = 39 × 5 = 195°.","hook":"Number in the group × degrees per person.","keys":["39 × 5 = 195°"]},{"id":"2022-P2-Q4:(b)(i):1","from":"2022-P2-Q4","q":"Reading test scores are normally distributed with mean 100 and standard deviation 20. Using the empirical rule, what percentage scored between 80 and 120?","right":"68%","wrong":["95%","34%","99.7%"],"why":"80 = 100 − 20 and 120 = 100 + 20: one standard deviation either side of the mean. The empirical rule puts about 68% there.","hook":"Count how many σ from the mean first, then pick 68, 95 or 99.7.","keys":["one standard deviation either side"]},{"id":"2022-P2-Q4:(b)(ii):1","from":"2022-P2-Q4","q":"Reading scores are normal with mean 100 and standard deviation 20. The top 2.5% got ‘Exceptional’. Using the empirical rule, what was the least score needed?","right":"140","wrong":["120","160","60"],"why":"95% lie within 2σ: 60 to 140. The other 5% is split between the two tails, so 2.5% are above 140. 140 = 100 + 2(20).","hook":"Outside the 95%: 5% shared by two tails, 2.5% each.","keys":["2.5% are above 140"]},{"id":"2022-P2-Q4:(b)(ii):2","from":"2022-P2-Q4","q":"By the empirical rule, what percentage of a normal distribution lies above μ + 2σ?","right":"2.5%","wrong":["5%","47.5%","16%"],"why":"95% lies between μ − 2σ and μ + 2σ. The 5% left over is split equally between the two tails: 5 ÷ 2 = 2.5% above μ + 2σ.","hook":"Picture the bell: what's left over splits evenly into two tails.","keys":["5 ÷ 2 = 2.5%"]},{"id":"2022-P2-Q4:(c):1","from":"2022-P2-Q4","q":"Six people's test scores were 104, 82, 94, 113, 98 and 105. What is the range?","right":"31","wrong":["8","1","99.3"],"why":"Range = largest − smallest. In order: 82, 94, 98, 104, 105, 113, so the range is 113 − 82 = 31.","hook":"Range: biggest minus smallest, one number.","keys":["113 − 82 = 31"]},{"id":"2022-P2-Q4:(c):2","from":"2022-P2-Q4","q":"Six test scores: 104, 82, 94, 113, 98, 105 (mean 99.3). Find the standard deviation, correct to 1 decimal place.","right":"9.8","wrong":["10.7","95.2","23.9"],"why":"σ = √(Σ(x − μ)² ÷ n) = √(571.33… ÷ 6) = √95.22… = 9.758… ≈ 9.8. On a calculator use σx, not sx.","hook":"Square the gaps, average them, then square root.","keys":["√(571.33… ÷ 6)"]},{"id":"2022-P2-Q7:(a)(i):1","from":"2022-P2-Q7","q":"A back-to-back stem-and-leaf plot has Day X on the left and Day Y on the right, key 6 | 0 = 6.0 kg. A row reads 7 5 3 3 | 5 | 4 5. What are the Day X weights on it?","right":"5.3, 5.3, 5.5 and 5.7 kg","wrong":["7.5, 5.5, 3.5 and 3.5 kg","53, 53, 55 and 57 kg","5.4 and 5.5 kg"],"why":"The stem 5 is the whole kilograms and each leaf is the tenths. Left leaves grow going outwards: 3, 3, 5, 7 give 5.3, 5.3, 5.5 and 5.7 kg.","hook":"The stem sits in the middle for both sides: stem first, then the leaf.","keys":["each leaf is the tenths"]},{"id":"2022-P2-Q7:(a)(i):2","from":"2022-P2-Q7","q":"Day Y weights (kg) of 10 dogs: 4.8, 5.4, 5.5, 6.1, 6.3, 6.0, 7.0, 7.6, 8.1, 7.9. Key 6 | 0 = 6.0 kg. Which leaves go beside stem 7, in order?","right":"0 6 9","wrong":["6 9","0 6","7.0 7.6 7.9"],"why":"7.0, 7.6 and 7.9 kg have stem 7 and leaves 0, 6 and 9. 7.0 still needs its leaf 0, and 7.9 comes after 8.1 in the list, so don't miss it.","hook":"A 0 is a real leaf. Tick off each value as you place it.","keys":["7.0 still needs its leaf 0"]},{"id":"2022-P2-Q7:(a)(ii):1","from":"2022-P2-Q7","q":"Back-to-back stem-and-leaf of 10 dogs' weights (Day X left, Day Y right, key 6 | 0 = 6.0 kg): 9 5 | 4 | 8; 7 5 3 3 | 5 | 4 5; 9 7 | 6 | 0 1 3; 4 3 | 7 | 0 6 9; | 8 | 1. What does it show?","right":"Weights increased from Day X to Day Y","wrong":["Weights decreased from Day X to Day Y","No change: 10 leaves on each side","Day Y had more dogs than Day X"],"why":"On Day X most leaves are on the 5 row; on Day Y they've moved to the 6 and 7 rows and one reaches 8. The weights increased from Day X to Day Y.","hook":"Compare where the leaves sit on each side: lower stems = lighter.","keys":["The weights increased"]},{"id":"2022-P2-Q7:(a)(iii):1","from":"2022-P2-Q7","q":"Weights (kg) of 10 dogs, Day X → Day Y: 4.5→4.8, 4.9→5.4, 5.3→5.5, 5.3→6.1, 5.5→6.3, 5.7→6.0, 6.7→7.0, 6.9→7.6, 7.3→8.1, 7.4→7.9. Most likely correlation coefficient r?","right":"0.9","wrong":["−0.9","0.2","−0.2"],"why":"Dogs heavy on Day X are still heavy on Day Y, so r is positive, and the points (X, Y) lie very close to a line: strong. A calculator gives 0.979…","hook":"Heavy stays heavy: positive. Tight to a line: near 1.","keys":["r is positive"]},{"id":"2022-P2-Q7:(b):1","from":"2022-P2-Q7","q":"Shelter animals. Cats: Male 5, Female 9, Total 14. Dogs: Male 11, Female ?, Total ?. Grand total: 40. How many female dogs are there?","right":"15","wrong":["29","26","20"],"why":"First the dogs' total: 40 − 14 = 26. Then the female dogs are the dogs that aren't male: 26 − 11 = 15.","hook":"Every row and column adds to its total. Fill in the easiest gap first.","keys":["26 − 11 = 15"]},{"id":"2022-P2-Q7:(b):2","from":"2022-P2-Q7","q":"Shelter animals. Cats: 5 male, 9 female (14 cats). Dogs: 11 male, 15 female (26 dogs). 40 animals in all. How many males are there altogether?","right":"16","wrong":["20","25","24"],"why":"Add down the Male column: 5 male cats + 11 male dogs = 16. Check with the females: 9 + 15 = 24, and 16 + 24 = 40.","hook":"Totals row: add down each column, then check it makes the grand total.","keys":["5 male cats + 11 male dogs = 16"]},{"id":"2023-P2-Q9:(a)(i):1","from":"2023-P2-Q9","q":"Minutes reading per day for 200 students: 0−30: 16, 30−60: 35, 60−90: 62, 90−120: 59, 120−150: 18, 150−180: 10. What is the largest number of students who could have read for more than 100 minutes?","right":"87","wrong":["28","67","58"],"why":"We don't know where in 90−120 those 59 students are, so at most all 59 read over 100. Add the higher classes: 59 + 18 + 10 = 87.","hook":"'Maximum' from a class: assume the whole class could count.","keys":["59 + 18 + 10 = 87"]},{"id":"2023-P2-Q9:(a)(ii):1","from":"2023-P2-Q9","q":"Minutes reading per day for 200 students: 0−30: 16, 30−60: 35, 60−90: 62, 90−120: 59, 120−150: 18, 150−180: 10 (60−90 means 60 or more but under 90). Best estimate of the median time spent reading?","right":"75 minutes","wrong":["100.5 minutes","26.5 minutes","90 minutes"],"why":"The median is between the 100th and 101st students. Running totals: 16, 51, 113, so they're in the 60−90 class: about 75 minutes.","hook":"Median: find the middle person with running totals, then read their class.","keys":["between the 100th and 101st students"]},{"id":"2023-P2-Q9:(a)(iii):1","from":"2023-P2-Q9","q":"To estimate how long students in Ireland read each day, a group asked the first 200 students to arrive at their school one Monday morning. What is wrong with how the students were chosen?","right":"Not random: may not be representative","wrong":["200 students is too small a sample","Nothing: the first 200 are random","Some students may lie about reading"],"why":"The first 200 into one school (maybe locals, or one early bus) aren't a random sample, so they may not represent all students in Ireland: the sample is biased.","hook":"A sample must be random to stand for everyone. Convenient isn't random.","keys":["aren't a random sample"]},{"id":"2023-P2-Q9:(a)(iv):1","from":"2023-P2-Q9","q":"Minutes spent reading per day, grouped 0−30, 30−60, …, 150−180, with the number of students in each, is drawn as a histogram. Why do the bars touch?","right":"Time is continuous: the classes join up","wrong":["All bar charts have touching bars","The data are categories, like colours","The bars all have the same height"],"why":"Time is continuous data: 30−60 ends exactly where 60−90 starts, with no gap between classes. So the histogram's bars touch, unlike a bar chart's.","hook":"Continuous data (time, height): bars touch. Categories: gaps.","keys":["Time is continuous data"]},{"id":"2023-P2-Q9:(b)(i):1","from":"2023-P2-Q9","q":"In a random sample of 500 Cork students, 61 were rated Excellent on a statistics test. What percentage of the sample was rated Excellent?","right":"12.2%","wrong":["0.122%","8.2%","61%"],"why":"Sample proportion = 61 ÷ 500 = 0.122. Multiply by 100 for a percentage: 12.2%.","hook":"Part ÷ whole, then × 100.","keys":["61 ÷ 500 = 0.122"]},{"id":"2023-P2-Q9:(b)(ii):1","from":"2023-P2-Q9","q":"In a random sample of 500 students, 61 were rated Excellent. Which calculation shows that the margin of error is 4.5%, to 1 decimal place?","right":"1 ÷ √500 × 100","wrong":["1 ÷ 500 × 100","1 ÷ √61 × 100","2 ÷ √500 × 100"],"why":"The margin of error uses the whole sample size, n = 500: 1/√500 = 0.0447… = 4.47…% ≈ 4.5%. The 61 only gives the sample's percentage.","hook":"n is everyone in the sample, not just the ones who said yes.","keys":["n = 500"]},{"id":"2023-P2-Q9:(b)(iii):1","from":"2023-P2-Q9","q":"In a sample of 500 Cork students, 12.2% were rated Excellent; the margin of error is 4.5%. What is the 95% confidence interval for the percentage in Cork? (Usually 10% get Excellent.)","right":"7.7% ≤ p ≤ 16.7%","wrong":["5.5% ≤ p ≤ 14.5%","9.95% ≤ p ≤ 14.45%","11.65% ≤ p ≤ 12.75%"],"why":"Confidence interval = sample result ± margin of error: 12.2 − 4.5 ≤ p ≤ 12.2 + 4.5, so 7.7% ≤ p ≤ 16.7%.","hook":"Centre the interval on the sample's %, not on the claimed figure.","keys":["12.2 − 4.5 ≤ p ≤ 12.2 + 4.5"]},{"id":"2023-P2-Q9:(b)(iii):2","from":"2023-P2-Q9","q":"Usually 10% of students are rated Excellent. Cork's sample: 12.2% Excellent, 95% confidence interval 7.7% ≤ p ≤ 16.7%. At the 5% level, is Cork different?","right":"No: 10% is inside the interval","wrong":["Yes: 10% is inside the interval","Yes: 12.2% is more than 10%","Yes: 4.5% is less than 5%"],"why":"10% lies inside 7.7% to 16.7%, so the sample fits the usual 10%: there is no evidence that Cork is different.","hook":"Inside the interval: no evidence of a change. Outside: evidence of a difference.","keys":["no evidence that Cork is different"]},{"id":"2025-P2-Q8:(a)(i):1","from":"2025-P2-Q8","q":"Of 117 400 new cars sold in 2023, 25 900 were Diesel. What percentage were Diesel, correct to 2 decimal places?","right":"22.06%","wrong":["0.22%","4.53%","79.42%"],"why":"Percentage = Diesel ÷ total × 100 = 25 900 ÷ 117 400 × 100 = 22.061… ≈ 22.06%.","hook":"Part ÷ whole × 100 for a %; × 360 is for a pie-chart angle.","keys":["25 900 ÷ 117 400 × 100"]},{"id":"2025-P2-Q8:(a)(i):2","from":"2025-P2-Q8","q":"Of 117 400 new cars, 22 500 were Fully Electric (19.17%). What is the angle for Fully Electric in a pie chart, correct to the nearest degree?","right":"69°","wrong":["19°","68°","5°"],"why":"Angle = 22 500 ÷ 117 400 × 360 = 68.99… ≈ 69°. Rounding the % to 19 first gives 19 × 3.6 = 68.4, which rounds the wrong way.","hook":"Fraction × 360°, and round only at the very end.","keys":["22 500 ÷ 117 400 × 360"]},{"id":"2025-P2-Q8:(a)(ii):1","from":"2025-P2-Q8","q":"Pie chart of new cars: Petrol 119°, Diesel 79° and Fully Electric 69° are drawn. Hybrid (25.81% of the cars) fills the rest. What angle should the Hybrid sector measure?","right":"93°","wrong":["26°","267°","162°"],"why":"The sectors fill 360°: 360 − (119 + 79 + 69) = 93°. Check: 25.81% × 3.6 = 92.9 ≈ 93°.","hook":"Measure the last gap as a check: everything adds to 360°.","keys":["360 − (119 + 79 + 69) = 93°"]},{"id":"2025-P2-Q8:(b)(i):1","from":"2025-P2-Q8","q":"Ten petrol cars (engine size in litres, km per litre): (1, 17.5), (1.2, 16), (1.4, 14), (1.6, 13), (1.9, 10.5), (2, 11), (2.5, 9), (3, 9), (3.5, 8.5), (4, 7). Which best describes the correlation?","right":"Strong negative","wrong":["Strong positive","Weak negative","Weak positive"],"why":"As engine size goes up, km per litre goes down: negative. The points follow that downward pattern closely, with none far off: strong.","hook":"Read left to right: down = negative; tight pattern = strong.","keys":["km per litre goes down"]},{"id":"2025-P2-Q8:(b)(i):2","from":"2025-P2-Q8","q":"Engine size and fuel efficiency (km per litre) of ten petrol cars have a strong negative correlation. Which explanation, in context, is right?","right":"Bigger engines tend to do fewer km/l","wrong":["Bigger engines tend to do more km/l","Engine size barely affects km/l","Every bigger engine does fewer km/l"],"why":"Negative: as engine size rises, km per litre falls; strong: the cars follow it closely. It's a trend, not a rule: the 2-litre car does 11 km/l, the 1.9-litre 10.5.","hook":"Explain in context: name both variables and say which way they move.","keys":["It's a trend, not a rule"]},{"id":"2025-P2-Q8:(b)(ii):1","from":"2025-P2-Q8","q":"Tom says that the correlation coefficient for two sets of data is 5. Why can't this be correct?","right":"r is always between −1 and 1","wrong":["r is always between 0 and 1","r can only be −1, 0 or 1","r must be a decimal, not 5"],"why":"The correlation coefficient always lies in −1 ≤ r ≤ 1: 1 is a perfect rising line, −1 a perfect falling one. 5 is bigger than 1.","hook":"r lives between −1 and 1. Anything outside is a mistake.","keys":["−1 ≤ r ≤ 1"]},{"id":"2025-P2-Q8:(c)(i):1","from":"2025-P2-Q8","q":"A random sample of 815 cars gives a margin of error of 1/√815 ≈ 3.5%. About how many cars would a sample need to halve this, to about 1.75%?","right":"3260","wrong":["1630","408","664 225"],"why":"E = 1/√n, so halving E means doubling √n, which needs 4 times n: 4 × 815 = 3260, and 1/√3260 ≈ 1.75%.","hook":"Four times the sample, half the margin of error.","keys":["4 × 815 = 3260"]},{"id":"2025-P2-Q8:(c)(ii):1","from":"2025-P2-Q8","q":"106 of a random sample of 815 new cars bought in 2024 were electric. What percentage of the sample were electric, correct to the nearest percent?","right":"13%","wrong":["8%","12%","47%"],"why":"Sample proportion = 106 ÷ 815 = 0.13006…; × 100 = 13.006…% ≈ 13%.","hook":"Of the sample: divide by the sample size, 815.","keys":["106 ÷ 815 = 0.13006…"]},{"id":"2025-P2-Q8:(c)(iii):1","from":"2025-P2-Q8","q":"In 2023, 19.2% of new cars were electric. A 2024 sample gives 13% with a margin of error of 3.5%. At the 5% level, is the 2024 percentage different?","right":"Yes: 19.2% is outside 9.5% to 16.5%","wrong":["No: 19.2% is outside 9.5% to 16.5%","No: 13% is inside 9.5% to 16.5%","No: 19.2% is inside 15.7% to 22.7%"],"why":"CI: 13 − 3.5 ≤ p ≤ 13 + 3.5, so 9.5% to 16.5%. 19.2% is outside it, so there is evidence that the 2024 percentage is different.","hook":"Test the OLD figure against the NEW sample's interval.","keys":["19.2% is outside it"]}]};
